\subsection*{A Computational details}

\subsection*{Calculation of derivatives}
The partial derivatives in (\ref{eq:score}) have a recursive structure. For the standard GARCH case, this structure is considered in detail by \textcite{FiorentiniCP96}. For example, for an ATV-GARCH$(1,1)$ model with one transition function we have \begin{align*}
\frac{\partial \sigma_{t}^{2}}{\partial \boldsymbol{\theta}_{1}}=& \frac{\partial}{\partial \boldsymbol{\theta}_{1}}\left\{\alpha_{0}+\alpha_{01} G_{1}\left(t / T ; \gamma_{1}, \mathbf{c}_{1}\right)+\alpha_{1} X_{t-1}^{2}+\beta_{1} \sigma_{t-1}^{2}\right\} \\
=&\left(G_{1}\left(t / T ; \gamma_{1}, \mathbf{c}_{1}\right),\right.\\
& \alpha_{01} G_{1}^{2}\left(t / T ; \gamma_{1}, \mathbf{c}_{1}\right) \exp \left(-\gamma_{1}\left(t / T-c_{11}\right)\right)\left(t / T-c_{11}\right), \\
&\left.\alpha_{01} G_{1}^{2}\left(t / T ; \gamma_{1}, \mathbf{c}_{1}\right) \exp \left(-\gamma_{1}\left(t / T-c_{11}\right)\right) \gamma_{1}\right)^{\intercal} \\
&+\beta_{1} \frac{\partial \sigma_{t-1}^{2}}{\partial \boldsymbol{\theta}_{1}}
\end{align*}
and \begin{align*}\frac{\partial \sigma_{t}^{2}}{\partial \boldsymbol{\theta}_{2}}&=\frac{\partial}{\partial \boldsymbol{\theta}_{2}}\left\{\alpha_{0}+\alpha_{01} G_{1}\left(t / T ; \gamma_{1}, \mathbf{c}_{1}\right)+\alpha_{1} X_{t-1}^{2}+\beta_{1} \sigma_{t-1}^{2}\right\} \\
&=\left(1, X_{t-1}^{2}, \sigma_{t-1}^{2}\right)^{\intercal}+\beta_{1} \frac{\partial \sigma_{t-1}^{2}}{\partial \boldsymbol{\theta}_{2}}.\end{align*}

The partial derivatives corresponding to the alternative hypothesis are given in (\ref{eq:dft}). The recursions are infinite, but decay geometrically with $\beta_1.$ By using the analytic expressions of the derivatives, one has to truncate the geometric series at the first observed data point. This introduces an error in the expression for the score, especially for small $T$ and large $\beta_1$. However, since the test relies on an asymptotic distribution, this is not a concern in large samples. An alternative is to use numerically computed derivatives. Here, we shall use analytic derivatives.  

\subsection*{Calculation of the LM statistic by auxiliary regressions}
For the computation of the LM statistic, it is convenient to introduce the
matrix%
\begin{equation*}
\boldsymbol{\widehat{S}}=\left( 
\begin{array}{ccc}
\widehat{\boldsymbol{s}}^\intercal_{11} & \widehat{\boldsymbol{s}}^\intercal_{21} & \widehat{\boldsymbol{s}}^\intercal_{31} \\ 
\widehat{\boldsymbol{s}}^\intercal_{12} & \widehat{\boldsymbol{s}}^\intercal_{22} & \widehat{\boldsymbol{s}}^\intercal_{32} \\ 
\vdots & \vdots & \vdots \\ 
\widehat{\boldsymbol{s}}^\intercal_{1T} & \widehat{\boldsymbol{s}}^\intercal_{2T} & \widehat{\boldsymbol{s}}^\intercal_{3T}%
\end{array}%
\right)
\end{equation*}%
and the vector $\widehat{\boldsymbol{e}}=(\widehat{Z}_{1}^{2}-1, \widehat{Z}_{2}^{2}-1,\ldots, \widehat{Z}_{T}^{2}-1)^{\intercal}.$
The LM statistic can be written as
\begin{equation*}
LM=\frac{1}{2}\widehat{\boldsymbol{e}}^{\intercal }\boldsymbol{\widehat{S}}(\boldsymbol{\widehat{S}}^{\intercal}\boldsymbol{\widehat{S}})^{-1}\boldsymbol{\widehat{S}}^{\intercal}\widehat{\boldsymbol{e}}.
\end{equation*}
Noting that under normality,
\begin{equation*}
\mbox{plim}_{T\rightarrow \infty }\frac{\widehat{\boldsymbol{e}}^{\intercal}\widehat{\boldsymbol{e}}}{T}=2,
\end{equation*}%
an asymptotically equivalent statistic is%
\begin{equation*}
LM=T\frac{\widehat{\boldsymbol{e}}^{\intercal}\boldsymbol{\widehat{S}}(\boldsymbol{\widehat{S}}^{\intercal }\boldsymbol{\widehat{S}})^{-1}\boldsymbol{\widehat{S}}^{\intercal }\widehat{\boldsymbol{e}}}{\widehat{\boldsymbol{e}}^{\intercal}\widehat{\boldsymbol{e}}}=TR^{2},
\end{equation*}%
where $R^{2}$ is the $R^{2}$ from a regression of $\widehat{\boldsymbol{e}}$ on  $\boldsymbol{\widehat{S}}$. This form of the LM\ test in ARCH\ models was originally
suggested by \textcite{Engle82}. The derivatives in $\widehat{\boldsymbol{s}}_{3}$ are here approximated by the partial derivatives of the polynomial $\boldsymbol{\delta}^{\intercal} \boldsymbol{\tau}_{t}$ in (\ref{eq:unidLM2}). For notational brevity, define
\begin{equation*}
\widehat{\boldsymbol{r}}_{1t}:= (\widehat{\boldsymbol{s}}^\intercal_{1t}, \widehat{\boldsymbol{s}}^\intercal_{2t})^\intercal   
\end{equation*}
and
\begin{equation*}
 \widehat{\boldsymbol{r}}_{2t}:=  \frac{1}{\widehat{\sigma}^2_t}\left(\boldsymbol{\tau}_t + \widehat{\beta}_1\boldsymbol{\tau}_{t-1} + \widehat{\beta}_1^2\boldsymbol{\tau}_{t-2} + \cdots \right). \label{eq:r2t}
\end{equation*}

The following algorithm can be used to calculate the LM statistic.
\subsubsection*{LM test}
\begin{enumerate}
    \item Estimate the model under the null hypothesis. Save the standardized residuals $\widehat{Z}_t=X_t/\widehat{\sigma}_t.$ Construct the residual sum of squares $SSR_0=\sum_{t=1}^T\left(\widehat{Z}^2_t-1\right)^2.$
    \item Regress $\left(\widehat{Z}_t^2-1\right)$ on $\widehat{\boldsymbol{r}}_{1t}$ and $\widehat{\boldsymbol{r}}_{2t}$. Form the residual sum of squares $SSR_1$.
    \item Compute the test statistic $$LM=T\frac{SSR_0-SSR_1}{SSR_0}.$$
\end{enumerate}
Assuming that $Z_t$ is standard normal and that the order of the polynomial is three as in (\ref{eq:unidLM2}), the asymptotic distribution of the test statistic $LM$ is $\chi^2(3)$. 

The test statistic can be made robust against violations of distributional assumptions.
\textcite[Procedure 2.1]{wooldridge1990} shows that the robust version can be calculated as follows. 

\subsubsection*{Robust LM test}

\begin{enumerate}
    \item Estimate the model under the null hypothesis. Save the standardized residuals $\widehat{Z}_t=X_t/\widehat{\sigma}_t.$
    \item Regress $\widehat{\boldsymbol{r}}_{2t}$ component-wise on $\widehat{\boldsymbol{r}}_{1t}$ and compute the residual vector $\widehat{\boldsymbol{w}}_t=\left(\widehat{w}_{1t},\widehat{w}_{2t},\widehat{w}_{3t}\right)^{\intercal}$.
    \item Regress a constant $1$ on $\left(\widehat{Z}^2_t-1\right)\widehat{\boldsymbol{w}}_t.$ Compute the residual sum of squares $SSR$ and the test statistic $$LMr=T-SSR.$$
\end{enumerate}
The asymptotic distribution of the test statistic $LMr$ under the null hypothesis is again $\chi^2(3)$ if the order of the polynomial is three as in (\ref{eq:unidLM2}).

In theory, under the null, the elements of $\widehat{\boldsymbol{r}}_{1t}$ are orthogonal to $\widehat{Z}_{t}^{2}-1=X^2_t/\widehat{\sigma}^2_t - 1.$ However, due to the numerical optimization, this might not hold in practice. We therefore orthogonalize this term by regressing it onto $\widehat{\boldsymbol{r}}_{1t}$ and use the residuals from this regression as $\widehat{Z}^2_t$ in our tests. A similar stabilizing correction was used by \textcite{eitrheim1996} in a STAR context, and by \textcite{EngleNg93} in a GARCH framework. To improve the numerical accuracy of the estimation of the shape parameter $\gamma_{1}$, we apply the transformation $\gamma_{1}=\eta_{1}/(1-\eta_{1})^{-1}$ proposed by \textcite{ekner2013parameter} when estimating the ATV-GARCH model.
