Solving the Lyapunov equation~(12) for the covariance matrix, we obtain the following expression of variances and covariances,
%
\begin{eqnarray}
    \sigma_x^2 &=& \langle x\rangle,
    \label{S4} \\
    \sigma_{xy}^2 &=& \frac{f_{yx}^\prime}{\beta_x+\beta_y} \sigma_x^2,
    \label{S5} \\
    \sigma_{xz}^2 &=& \frac{f_{zx}^\prime}{\beta_x+\beta_z} \sigma_x^2 + \frac{f_{zy}^\prime}{\beta_x+\beta_z} \sigma_{xy}^2,
    \label{S6} \\
    \sigma_y^2 &=& \langle y\rangle + \frac{f_{yx}^\prime}{\beta_y} \sigma_{xy}^2,
    \label{S7} \\
    \sigma_{yz}^2 &=& \frac{f_{zy}^\prime}{\beta_y+\beta_z} \sigma_y^2 + \frac{f_{zx}^\prime}{\beta_y+\beta_z} \sigma_{xy}^2 + \frac{f_{yx}^\prime}{\beta_y+\beta_z} \sigma_{xz}^2,
    \label{S8} \\
    \sigma_z^2 &=& \langle z\rangle + \frac{f_{zx}^\prime}{\beta_z} \sigma_{xz}^2 + \frac{f_{zy}^\prime}{\beta_z} \sigma_{yz}^2,
    \label{S9}
\end{eqnarray}

\noindent where, $\sigma_i^2$ and $\sigma_{ij}^2$ stand for the variance of the $i$-th component and covariance between $i$ and $j$, where $i,j~(\neq i) \in \{ x,y,z \}$. In the above expressions, we use $f_{ij}^\prime = d\bar{f}_i(\cdots)/d\langle j\rangle$. 


We define the normalized covariance as $\eta_{ij}^2=\sigma_{ij}^2/[\langle i\rangle \langle j\rangle]$. Substituting this definition into Eqs.~(\ref{S5}),~(\ref{S6})~and~(\ref{S8}) and rearranging yields,
%
\begin{eqnarray}
    \eta_{xy}^2 &=& \frac{\Gamma_{xy}}{\langle y\rangle} \times f_{yx}^\prime
    \label{eqs10} \\
    %
    \eta_{xz}^2 &=& 
    \underbrace{\frac{\Gamma_{xz}}{\langle z\rangle} \times f_{zx}^\prime}_{\eta_{xz,d}^2}
    +
    \underbrace{\frac{\Gamma_{xyz}^{(1)}}{\langle z\rangle} \times f_{yx}^\prime f_{zy}^\prime}_{\eta_{xz,ind}^2},
    \label{eqs11} \\
    %
    \eta_{yz}^2 &=& 
    \underbrace{\frac{\Gamma_{yz}}{\langle z\rangle} \times f_{zy}^\prime}_{\eta_{yz,ind_1}^2} 
    +
    \underbrace{\frac{\Gamma_{xyz}^{(2)} \langle x\rangle}{\langle y\rangle \langle z\rangle} \times f_{yx}^{\prime^2} f_{zy}^\prime}_{\eta_{yz,ind_2}^2}
    \nonumber \\
    && 
    + \underbrace{\frac{\Gamma_{xyz}^{(3)} \langle x\rangle}{\langle y\rangle \langle z\rangle} \times f_{yx}^\prime f_{zx}^\prime}_{\eta_{yz,cross}^2},
    \label{eqs12}
\end{eqnarray}


\noindent where the under-braced terms represent the partial covariances contributing to the total normalized covariance. Here, $\Gamma_{xy}=1/(\beta_x+\beta_y)$, $\Gamma_{xz}=1/(\beta_x+\beta_z)$, $\Gamma_{yz}=1/(\beta_y+\beta_z)$, $\Gamma_{xyz}^{(1)}=1/[(\beta_x+\beta_y)(\beta_x+\beta_z)]$, $\Gamma_{xyz}^{(2)}=(\beta_x+\beta_y+\beta_z)/[\beta_y(\beta_x+\beta_y)(\beta_x+\beta_z)(\beta_y+\beta_z)]$, and $\Gamma_{xyz}^{(3)}=(2\beta_x+\beta_y+\beta_z)/[(\beta_x+\beta_y)(\beta_x+\beta_z)(\beta_y+\beta_z)]$. 


We now define the output noise by $\eta_z^2=\sigma_z^2/\langle z\rangle^2$. Using this definition in Eq.~(\ref{S9}), we write the expression of noise of Z in terms of partial covariances given in Eqs.~(\ref{eqs10}-\ref{eqs12}) as
% %
\begin{eqnarray}
    \eta_z^2 &=& 
    \underbrace{\frac{1}
    {\langle z\rangle}
    }_{\eta_{z,int}^2}
    +
    \underbrace{
    \frac{f_{zx}^\prime \langle x\rangle}{\beta_z \langle z\rangle} \eta_{xz,d}^2
    }_{\eta_{z,d}^2}
    +
    \underbrace{
    \frac{f_{zy}^\prime \langle y\rangle}{\beta_z \langle z\rangle} \left( \eta_{yz,ind_1}^2 + \sigma_{yz,ind_2}^2 \right)
    }_{\eta_{z,ind}^2}
    \nonumber \\
    && + 
    \underbrace{
    \frac{f_{zx}^\prime \langle x\rangle}{\beta_z \langle z\rangle} \eta_{xz,ind}^2
    +
    \frac{f_{zy}^\prime \langle y\rangle}{\beta_z \langle z\rangle} \eta_{yz,cross}^2
    }_{\eta_{z,cross}^2},
    \label{eqs13}
\end{eqnarray}

\noindent where the under-braced terms represent distinct noise sources. The expressions in Eq.~(\ref{eqs13}) are general and hold for any FFL type. However, to apply them specifically to C1- or I1-FFL with particular pathway regulation mechanisms to output-- such as AND or OR-- one must use the corresponding forms of the production vector $\bm{f}$ (see Table~S1).


We note that the noise of X, defined as $\eta_x^2=1/\langle x\rangle$, is used as the tuning parameter in our analysis. We set different values of $\langle x\rangle$ to obtain the range of the tuning parameter upon which we measure different quantities.



