\section{Intracellular 5-HT$_{2A}$ Signaling Pathways and the Complexity Axis}
\label{sec:5HT_pathways}

\paragraph{Beyond canonical signaling.} The 5-HT$_{2A}$ receptor's contribution to consciousness complexity emerges from its remarkable signaling diversity. While canonically coupled to G$_q$/PLC activation, 5-HT$_{2A}$ receptors engage at least three distinct intracellular cascades with differential effects on neural computation\ref{5ht2a_signalling}:

\begin{enumerate}
    \item \textbf{G$_q$--PLC--IP$_3$/DAG pathway}: Drives classical hallucinogenic effects through cortical excitation
    \item \textbf{$\beta$-arrestin 2 scaffolding}: Mediates neuroplasticity and long-term cognitive changes
    \item \textbf{mGluR2 heterodimerization}: Modulates the psychedelic response through cross-talk inhibition
\end{enumerate}

This pathway diversity allows us to refine the complexity modulator (Eq.~\ref{eq:5HT_modulation}) as:
\begin{equation}
\Psi_{\text{complex}} = \Psi_0 \left(1 + \sum_{i} \lambda_i f_i(L, t)\right) \cdot \exp\left(-\gamma \left(\frac{\DA}{\DA_{\max}}\right)^2\right) \cdot R_{\text{desens}}(t)
\end{equation}
where $f_i(L,t)$ represents the fractional activation of pathway $i$ by ligand $L$ at time $t$, and $\lambda_i$ quantifies each pathway's contribution to cognitive flexibility.

\begin{hypothesis}[Pathway-specific consciousness modulation]
\label{hyp:pathway_specific}
Different 5-HT$_{2A}$ signaling pathways selectively enhance distinct aspects of consciousness:
\begin{itemize}
    \item G$_q$ activation $\rightarrow$ sensory richness and perceptual alterations
    \item $\beta$-arrestin recruitment $\rightarrow$ insight, meaning, and cognitive flexibility
    \item mGluR2 heterodimers $\rightarrow$ integration and reality-testing preservation
\end{itemize}
\end{hypothesis}

