In order to tackle the challenge of allowing variable stepsizes for the DR algorithm, we develop an extension of the successive approximation scheme examined in \cite{MR211301}, allowing the use of a sequence $(\gamma_n)_{\nnn}$ of variable stepsizes. To do so, we introduce the notion of a \emph{\Qname} (Definition~\ref{d:Q-transport}). A key property of these operators is the following: given an % nonexpansive 
operator $T_{\gamma}$ parametrized by a positive parameter $\gamma \in\RPP$, its fixed-point relocator operator, denoted $Q_{\delta\gets \gamma}$, is a  bijection which maps fixed-points of $T_{\gamma}$ to fixed-points of $T_{\delta}$ for a different parameter $\delta \in \RPP$. 

Given  \Qname{s} $(Q_{\delta\gets \gamma})_{\gamma,\delta\in\RPP}$ for $(T_\gamma)_{\gamma\in\RPP}$, a stepsize sequence $(\gamma_n)_\nnn$  and initial point $x_0\in X$, we consider iterations of the form
\begin{equation}\label{eq:RFP}
(\forall \nnn)\quad x_{n+1} = Q_{\gamma_{n+1}\gets \gamma_n}T_{\gamma_n}x_n. 
\end{equation}
We refer to the family of methods defined this way as \emph{relocated fixed-point iterations.}
For the DR operator, we show that a fixed-point relocator is given by
\begin{equation} \label{e:DR-FPR}
    (\forall \gamma,\delta \in \RPP)(\forall x \in X)\; Q_{\delta\gets \gamma}(x) =  \tfrac{\delta}{\gamma}x +
\big(1-\tfrac{\delta}{\gamma}\big)J_{\gamma A}x.
\end{equation}
The corresponding \emph{relocated DR algorithm} in the form of \eqref{eq:RFP} can therefore be expressed as 
\begin{equation}\label{eq:RDR}
\left\{\begin{aligned}
    w_{n} &= x_n-J_{\gamma_n A}x_n + J_{\gamma_n B}R_{\gamma_n A}x_n \\
    x_{n+1} &= \tfrac{\gamma_{n+1}}{\gamma_n}w_n + \left(1-\tfrac{\gamma_{n+1}}{\gamma_n}\right)J_{\gamma_n A}w_n.
\end{aligned}\right.
\end{equation}
%Observe that it can be expressed in terms of resolvents only---an observation which, to our knowledge, has not yet been highlighted in the literature. 
Note that, in its current form, \eqref{eq:RDR} appears to require an extra resolvent evaluation as compared to the standard DR algorithm. However, this can be circumvented using the equivalent implementation described in Algorithm~\ref{a:DR-2}. For further details, see Proposition~\ref{p:DR-N-reformulation}.
\begin{algorithm}[!ht]
\caption{Relocated DR algorithm for finding a zero of $A+B$. \label{a:DR-2}}
\SetKwInOut{Input}{Input}
\Input{Choose $x_0 \in X$ and a stepsize sequence $(\gamma_n)_\nnn$ in $\RPP$.}

Set $z_0 = J_{\gamma_0 A}x_0$. 

\For{$n=0,1,2,\dots$}{
Step 1. Intermediate step. Compute \begin{equation} \label{DR:variable-stepsize-1}
    \left\{\begin{aligned}
    y_n & = J_{\gamma_nB}(2z_n - x_n) \\
    w_n & = x_n - z_n + y_n. \\
    %z_{n+1} & = J_{\gamma_n A}(w_n) \\
    %x_{n+1} & = \dfrac{\gamma_{n+1}}{\gamma_n} w_n + \left( 1 - \dfrac{\gamma_{n+1}}{\gamma_n} \right) z_{n+1}. 
    \end{aligned}\right.
\end{equation}

Step 2. Next iterate. Compute
\begin{equation} \label{DR:variable-stepsize-2}
    \left\{\begin{aligned}
    %y_n & = J_{\gamma_nB}(2z_n - x_n) \\
    %w_n & = x_n - z_n + y_n \\
    z_{n+1} & = J_{\gamma_n A}w_n \\
    x_{n+1} & = \dfrac{\gamma_{n+1}}{\gamma_n} w_n + \left( 1 - \dfrac{\gamma_{n+1}}{\gamma_n} \right) z_{n+1}. 
    \end{aligned}\right.
\end{equation}

}
\end{algorithm}
