The convergence framework we develop in this work focuses on a particular type of iteration operators, the so-called \emph{nonexpansive} operators. A single-valued operator $T: X \to X$ is said to be:
\begin{enumerate}
\item \emph{nonexpansive} if
  $(\forall x,y \in X) \; \|Tx - Ty\| \leq \|x-y\|.$
\item \emph{firmly nonexpansive}  if 
  $(\forall x,y \in X) \; \|Tx - Ty\|^2 + \|(\Id - T)x - (\Id - T)y\|^2 \leq \|x-y\|^2.$
\item \label{it:avg} \emph{$\alpha$-averaged (nonexpansive)}  if $\alpha \in (0,1)$ and 
  $(\forall x,y \in X) \; \|Tx - Ty\|^2 + \frac{1-\alpha}{\alpha}\|(\Id - T)x - (\Id - T)y\|^2 \leq \|x-y\|^2.$
\end{enumerate}
Equivalent to \ref{it:avg}, $T$ is $\alpha$-averaged nonexpansive if there exists a nonexpansive operator $R$ such that $T = (1-\alpha)\Id + \alpha R$. Thus, in particular, an operator $T$ is firmly nonexpansive if and only if $T$ is $\frac{1}{2}$-averaged. 


Given a nonempty set $C \subseteq X$, the \emph{normal cone} to $C$ at $x\in C$ is given by $N_C(x) := \{ v\in C: (\forall y \in C) \; \langle v, y - x \rangle \leq 0 \}$, and if $x \notin C$, $N_C(x) := \varnothing$ . If $C \subseteq X$ is a nonempty closed convex set, then $N_C$ is maximally monotone. The \emph{projection} operator onto $C$ is  $ P_{C} = J_{N_C}$.

The following fact summarizes important properties of resolvents and averaged operators. 
\begin{fact}[Properties of resolvents]  \label{f:resolvents}
Suppose $A$ is a maximally monotone operator on $X$. Then, the following statements hold true.
    \begin{enumerate}
        \item \label{f:resolvents-nonexpansive}
        $(\forall \alpha \in \RPP )$ $J_{\alpha A}$ and $\Id - J_{\alpha A}$  are well-defined, have full domain, and are firmly nonexpansive and maximally monotone.
        \item \label{f:resolvents-stepsize-trick}
        $(\forall \gamma, \lambda \in \RPP )(\forall x \in X)$ $J_{\gamma A}x = J_{\lambda\gamma A}(\lambda x + (1-\lambda)J_{\gamma A}x)$.
        \item \label{f:resolvents-lip}
        $(\forall \gamma, \lambda \in \RPP )(\forall x \in X)$ $\| J_{\gamma A}x - J_{\lambda\gamma A} x \| \leq |1-\lambda| \| J_{\gamma A}x - x\|$.
        \item \label{f:resolvents-asymptotic}
        $(\forall x \in X)$ $J_{\gamma A}x \to P_{\overline{\dom A}}x $ as $\gamma \downarrow 0$.
    \end{enumerate}
\end{fact}

\begin{proof}
    The properties in \ref{f:resolvents-nonexpansive} follows from \cite{Minty}, \cite[Corollary~23.9]{BC2017} and \cite[Corollary~23.11(i)]{BC2017}. Moreover, items \ref{f:resolvents-stepsize-trick}--\ref{f:resolvents-asymptotic} are, respectively,  \cite[Proposition~23.31(i)]{BC2017}, \cite[Proposition~23.31(iii)]{BC2017}, and \cite[Theorem 23.48]{BC2017}.

    %\ref{f:resolvents-lip} is \cite[Proposition~23.31(iii)]{BC2017}

    %\ref{f:resolvents-asymptotic} is \cite[Theorem 23.48]{BC2017}
\end{proof}

%From Fact~\ref{f:resolvents}, we see that the projection operator onto a nonempty closed convex set is nonexpansive, as well as the reflected resolvent.

\begin{fact}[Properties of averaged operators] \label{f:averaged}

Let $\alpha \in (0,1)$ and $T: X\to X$ be a nonexpansive operator. Then, the following hold.
\begin{enumerate}
    \item \label{f:averaged-characterization}
    $T$ is $\alpha$-averaged operator if and only if $(1-\frac{1}{\alpha}) \Id + \frac{1}{\alpha} T$ is nonexpansive.
    \item \label{f:averaged-scaling}
    $(\forall \lambda \in (0, \frac{1}{\alpha}))$ $T$ is $\alpha$-averaged operator if and only if $(1-\lambda) \Id + \lambda T$ is $\lambda\alpha$-averaged.
\end{enumerate}

\end{fact}

\begin{proof}
    Item \ref{f:averaged-characterization} is \cite[Proposition~4.35]{BC2017}, and item \ref{f:averaged-scaling} is \cite[Proposition~4.40]{BC2017}. 
\end{proof}

