\begin{fact}[{\cite[Proposition~2.1, Corollary~2.3]{arakcheev2025opial},\cite[Lemma 5.2]{peypouquet2015convex}}]\label{f:Opial}
Let $(x_n)_\nnn$ be a sequence in $X$ which is Opial with respect to a nonempty set $C\subseteq X$. Then, the following statements are true.
\begin{enumerate}
    \item \label{f:Opial-bounded}
    $(x_n)_\nnn$ is bounded. 
    \item \label{f:Opial-cluster}
    $(x_n)_\nnn$ converges weakly to a point in $C$ if and only if all weak cluster points of $(x_n)_\nnn$ lie in~$C$.
\end{enumerate}
\end{fact}

\section{Properties of resolvents and nonexpansive operators}  \label{s:resolvents-and-nonexpansive}


In this section, we derive a number of new properties of resolvents and explore their consequences for the Douglas--Rachford operator. The insights of this section will form the basis and motivating examples for the framework developed in the subsequent sections. 

\subsection{Properties of resolvents}
\label{sec:resolvents}
%We start by establishing new properties of resolvents. In particular, w
In this section, we first present a resolvent rule that yields a bijection between fixed-point sets of the DR operator as a function of the stepsize. This rule allows us to define an operator that transforms fixed-points of the DR operator as a function of stepsize. We also establish continuity properties of the map $(x, \gamma) \mapsto J_{\gamma A}x$ for a given maximally monotone operator $A$. %, and its implications for the DR operator.

\begin{lemma}
\label{l:bijection}
Let $A$ be maximally monotone on $X$, 
and let $\alpha,\beta\in\RPP$. 
Then 
\begin{equation}
\label{e:0222a}
J_{\beta A}\Big(\tfrac{\beta}{\alpha}\Id 
+ \big(1-\tfrac{\beta}{\alpha}\big)J_{\alpha A} \Big) = J_{\alpha A} 
\end{equation}
and 
\begin{equation}
\label{e:0222b}
\Big(\tfrac{\alpha}{\beta}\Id 
+\big(1-\tfrac{\alpha}{\beta}\big)J_{\beta A} \Big)
\Big(\tfrac{\beta}{\alpha}\Id 
+\big(1-\tfrac{\beta}{\alpha}\big)J_{\alpha A} \Big) 
= \Id = 
\Big(\tfrac{\beta}{\alpha}\Id 
+\big(1-\tfrac{\beta}{\alpha}\big)J_{\alpha A} \Big)
\Big(\tfrac{\alpha}{\beta}\Id 
+\big(1-\tfrac{\alpha}{\beta}\big)J_{\beta A} \Big). 
\end{equation}
Consequently, 
\begin{equation}
\label{e:0222c}
\tfrac{\alpha}{\beta}\Id 
+\big(1-\tfrac{\alpha}{\beta}\big)J_{\beta A} 
\colon X\to X \text{ is a bijection with inverse }
\tfrac{\beta}{\alpha}\Id 
+\big(1-\tfrac{\beta}{\alpha}\big)J_{\alpha A}. 
\end{equation}
\end{lemma}
\begin{proof}
Applying Fact~\ref{f:resolvents}\ref{f:resolvents-stepsize-trick} with $\gamma=\alpha$ and $\lambda = \beta/\alpha$
yields \eqref{e:0222a}. 
Using \eqref{e:0222a} in the second identity, we deduce 
\begin{align*}
\Big(\tfrac{\alpha}{\beta}\Id 
+\big(1-\tfrac{\alpha}{\beta}\big)J_{\beta A} \Big)
\Big(\tfrac{\beta}{\alpha}\Id 
+\big(1-\tfrac{\beta}{\alpha}\big)J_{\alpha A} \Big)
&= \Id + \Big(\tfrac{\alpha}{\beta}-1\Big)J_{\alpha A}
+ \Big(1-\tfrac{\alpha}{\beta}\Big)J_{\beta A}%
\Big(\tfrac{\beta}{\alpha}\Id 
+\big(1-\tfrac{\beta}{\alpha}\big)J_{\alpha A} \Big)\\
&=\Id,
\end{align*}
and so the left identity in \eqref{e:0222b} holds. 
To obtain the right identity in \eqref{e:0222b},
we use the left identity, with the roles of $\alpha$ and $\beta$ 
interchanged. 
Finally, \eqref{e:0222c} follows from \eqref{e:0222b}.
\end{proof}



