\begin{proposition}
\label{p:Q}
Let $A$ be maximally monotone on $X$, and let $\alpha,\beta\in\RPP$.
Consider the operator defined by 
\begin{equation*}
  Q_{\beta\gets \alpha} := \tfrac{\beta}{\alpha}\Id 
  +\big(1-\tfrac{\beta}{\alpha}\big)J_{\alpha A}.
\end{equation*}
Then:
\begin{enumerate}
\item 
\label{r:Qi}
If $\beta <\alpha$, then $Q_{\beta\gets \alpha}$ 
is $(\thalb-\tfrac{\beta}{2\alpha})$-averaged and hence firmly nonexpansive.
\item 
\label{r:Qii}
If $\beta \geq \alpha$, then 
$Q_{\beta\gets \alpha}$ is monotone,
$\tfrac{\beta}{\alpha}$-Lipschitz continuous, and
\begin{equation}\label{eq:Qab 2}
(\forall z,\bar{z}\in X)\quad \| Q_{\beta\gets \alpha}z- Q_{\beta\gets \alpha}\bar{z}\|^2 + \bigl(\frac{\beta^2}{\alpha^2}-1\bigr)\|J_{\alpha A}z-J_{\alpha A}\bar{z}\|^2\leq \frac{\beta^2}{\alpha^2}\|z-\bar{z}\|^2. 
\end{equation}
\end{enumerate}
\end{proposition}
\begin{proof}
\ref{r:Qi}~Since $J_{\alpha A}$ is firmly nonexpansive from Fact~\ref{f:resolvents}\ref{f:resolvents-nonexpansive} and $0<1-\frac{\beta}{\alpha}< 1<2$, the result follows from Fact~\ref{f:averaged}\ref{f:averaged-scaling} with $\alpha=1/2$ and $\lambda=1-\beta/\alpha$.

\ref{r:Qii}~Assume $\beta \geq \alpha$ and let $z,\bar{z}\in X$. Since $J_{\alpha A}$ is firmly nonexpansive, we have
$  \|J_{\alpha A}z-J_{\alpha A}\bar{z}\|^2\leq \langle z-\bar{z},J_{\alpha A}z-J_{\alpha A}\bar{z}\rangle. $
Using this inequality and noting that $1-\frac{\beta}{\alpha} \leq 0$, we deduce
\begin{align*}
&\| Q_{\beta\gets \alpha}z- Q_{\beta\gets \alpha}\bar{z}\|^2\\
&= \left\|\frac{\beta}{\alpha}(z-\bar{z})+\left(1-\frac{\beta}{\alpha}\right)(J_{\alpha A}z-J_{\alpha A}\bar{z})\right\|^2 \\
&= \frac{\beta^2}{\alpha^2}\|z-\bar{z}\|^2 + \left(1-\frac{\beta}{\alpha}\right)^2\|J_{\alpha A}z-J_{\alpha A}\bar{z}\|^2 + 2\frac{\beta}{\alpha}\left(1-\frac{\beta}{\alpha}\right)\langle z-\bar{z},J_{\alpha A}z-J_{\alpha A}\bar{z}\rangle \\
&\leq \frac{\beta^2}{\alpha^2}\|z-\bar{z}\|^2 + \left(1-\frac{\beta}{\alpha}\right)^2\|J_{\alpha A}z-J_{\alpha A}\bar{z}\|^2 + 2\frac{\beta}{\alpha}\left(1-\frac{\beta}{\alpha}\right)\|J_{\alpha A}z-J_{\alpha A}\bar{z}\|^2\\
&= \frac{\beta^2}{\alpha^2}\|z-\bar{z}\|^2 + \left(1-\frac{\beta^2}{\alpha^2}\right)\|J_{\alpha A}z-J_{\alpha A}\bar{z}\|^2,
\end{align*}
which yields \eqref{eq:Qab 2}, and hence $\tfrac{\beta}{\alpha}$-Lipschitz continuity of $Q_{\beta\gets \alpha}$. To see that $Q_{\beta\gets \alpha}$ is monotone, note the representation $Q_{\beta\gets \alpha}=\frac{\beta}{\alpha}(\Id-J_{\alpha A})+J_{\alpha A}$. Since both $\Id-J_{\alpha A}$ and $J_{\alpha A}$ are monotone in view of Fact~\ref{f:resolvents}\ref{f:resolvents-nonexpansive} and $\frac{\beta}{\alpha}\in\RPP$, monotonicity of $Q_{\beta\gets \alpha}$ follows. 
\end{proof}


