Note that, due to \eqref{e:0222a}, the operator $Q_{\beta\gets \alpha}$ in Proposition~\ref{p:Q} satisfies $J_{\beta A}Q_{\beta\gets \alpha} = J_{\alpha A} .$ This identity will be used to propose a variable stepsize extension of the Douglas--Rachford algorithm. In order to analyze its convergence, we will also need the following continuity properties of the resolvent $J_{\gamma A}x$ as a function of both $x$ and $\gamma$, which were considered in \cite[Corollary 7]{friedlander2023perspective} in the context of convex subdifferentials in finite dimensional Euclidean spaces.


\begin{proposition}\label{p:resnice}
Let $A$ be maximally monotone on $X$, and define $S_A\colon X\times\RP \to X$ according to
$$ S_A(x,\gamma) := \begin{cases} 
                    J_{\gamma A}x & \gamma\in\RPP, \\
                    P_{\overline{\dom A}}x & \gamma=0. \\
                  \end{cases} $$
Then $S_A$ is continuous on $X\times\RP$ and Lipschitz continuous on compact subsets of $X\times\RPP$.
\end{proposition}
\begin{proof}
We first show that $S_A$ is continuous on $X\times\RP$. To this end, let $(x,\lambda)\in X\times\RP$ and suppose $(y,\gamma)\to(x,\lambda)$. First, assume $\lambda\in\RPP$. Using Facts~\ref{f:resolvents}\ref{f:resolvents-lip} and \ref{f:resolvents-nonexpansive}, %\cite[Proposition~23.31]{BC2017} and nonexpansivenes of the resolvent, 
we deduce that
\begin{equation}\label{eq:Sxl}
\begin{aligned}
 \|S_A(x,\lambda)-S_A(y,\gamma)\| 
   &\leq \|J_{\lambda A}x-J_{\gamma A}x\| + \|J_{\gamma A}x-J_{\gamma A}y\| \\
   &\leq \frac{\|J_{\lambda A}x-x\|}{\lambda}|\lambda-\gamma|+\|x-y\|\to0.
\end{aligned}
\end{equation}
%Next, assume $\lambda=0$. If $\gamma > 0$, using Facts~\ref{f:resolvents}\ref{f:resolvents-asymptotic} and \ref{f:resolvents-nonexpansive},  %\cite[Theorem~23.48]{BC2017} and nonexpansivenes of the resolvent, 
%we deduce
%\begin{align*}
% \|S_A(x,0)-S_A(y,\gamma)\| 
% &\leq \|P_{\overline{\dom A}}x-J_{\gamma A}x\| + \|J_{\gamma A}x-J_{\gamma A}y\| \\
% &\leq \|P_{\overline{\dom A}}x-J_{\gamma A}x\|+\|x-y\|.%\to 0.
%\end{align*} Otherwise, if $\gamma = 0$, then \begin{align*}
 %\|S_A(x,0)-S_A(y,0)\| 
 %&\leq \|P_{\overline{\dom A}}x-P_{\overline{\dom A}}y\| 
 %\leq \|x-y\|.%\to 0.
%\end{align*}
Next, assume $\lambda=0$. If $\gamma > 0$, using Fact~\ref{f:resolvents}\ref{f:resolvents-nonexpansive},  %\cite[Theorem~23.48]{BC2017} and nonexpansivenes of the resolvent, 
we deduce
\begin{align*}
 \|S_A(x,0)-S_A(y,\gamma)\| 
 &\leq \|P_{\overline{\dom A}}x-J_{\gamma A}x\| + \|J_{\gamma A}x-J_{\gamma A}y\| \\
 &\leq \|P_{\overline{\dom A}}x-J_{\gamma A}x\|+\|x-y\|.%\to 0.
\end{align*}
And, if $\gamma = 0$, Fact~\ref{f:resolvents}\ref{f:resolvents-nonexpansive} gives
%\begin{align*}
 $\|S_A(x,0)-S_A(y,0)\| 
 \leq \|P_{\overline{\dom A}}x-P_{\overline{\dom A}}y\| 
 \leq \|x-y\|.$ %\to 0.
%\end{align*}
Combining these two subcases and noting Fact~\ref{f:resolvents}\ref{f:resolvents-asymptotic}, we deduce that $\|S_A(x,0)-S_A(y,\gamma)\|\to 0$.
Thus, in all cases, $\lim_{(y,\lambda)\to(x,\gamma)}S_A(y,\lambda)=S_A(x,\gamma)$ which establishes continuity of $S_A$ on $X\times\RP$.

To show that $S_A$ is Lipschitz continuous on compact subsets of $X\times\RPP$, let %$(z,\eta)\in X\times\RPP$ 
$U \subseteq X\times\RPP$ be compact. Since $S_A$ is continuous and the continuous image of compact sets is compact, we have
$ L := \max_{(x,\lambda)\in U}\frac{\|J_{\lambda A}x-x\|}{\lambda} < +\infty. $
Then, using \eqref{eq:Sxl}, we obtain $(\forall (x,\lambda), (y,\gamma) \in U)$
$$ \|S_A(x,\lambda)-S_A(y,\gamma)\| \leq \max\{L,1\}\left(|\lambda-\gamma|+\|x-y\|\right) \leq \sqrt{2}\max\{L,1\}\|(x,\lambda)-(y,\gamma)\|,  $$
which shows that $S_A$ is Lipschitz on $U$.
\end{proof}

\subsection{Properties of the Douglas--Rachford operator}

In this section, we explore a number of consequences of the resolvent properties derived in the previous section for the Douglas--Rachford operator $T_\gamma := \Id-J_{\gamma A} + J_{\gamma B}R_{\gamma A}$. First, we show that the bijective map of Lemma~\ref{l:bijection} also defines a bijection between fixed-point sets of the DR operator for different stepsize parameters, and show continuity properties of the operator $(x,\gamma) \mapsto T_{\gamma}x$. %Then, in Theorem~\ref{c:DR}, we prove that our proposed variation of the DR algorithm, in the limit, finds a solution to the problem \eqref{e:gen-prob}. 

\begin{theorem}
\label{t:DRbijection}
Let $A, B$ be maximally monotone on $X$, $T_{\gamma}$ be the DR operator defined in \eqref{e:0222d}, and $\alpha, \beta\in\RPP$.  Then 
\begin{equation*}
  \Big(\tfrac{\beta}{\alpha}\Id 
  +\big(1-\tfrac{\beta}{\alpha}\big)J_{\alpha A}\Big)\Big|_{\Fix T_\alpha}
  \colon \Fix T_\alpha\to \Fix T_\beta
  \text{ is a bijection, with inverse }
  \Big(\tfrac{\alpha}{\beta}\Id 
  +\big(1-\tfrac{\alpha}{\beta}\big)J_{\beta A}\Big)\Big|_{\Fix T_\beta}. 
\end{equation*}
\end{theorem}
\begin{proof}
Let $x\in \Fix T_\alpha$.
Then  
%\begin{equation*}
$z := J_{\alpha A}x = J_{\alpha B}R_{\alpha A}x \in \zer ( A + B)
\;\text{ and }\; 
R_{\alpha A}x = 2z-x.$ 
%\end{equation*}
Now set 
%\begin{equation*}
$y := 
\tfrac{\beta}{\alpha}x
+ \big(1-\tfrac{\beta}{\alpha}\big)J_{\alpha A}x 
= 
\tfrac{\beta}{\alpha}x
+ \big(1-\tfrac{\beta}{\alpha}\big)z. $ 
%\end{equation*}
Using \eqref{e:0222a} thrice, we deduce that $ J_{\beta A}y =  J_{\alpha A}x = z $ and
\begin{align*}
  J_{\beta A}y
&= 
J_{\beta A}\Big(\tfrac{\beta}{\alpha}\Id
+ \big(1-\tfrac{\beta}{\alpha}\big)J_{\alpha A}\Big)x
= J_{\alpha A}x = z = J_{\alpha B}R_{\alpha A}x  = 
J_{\alpha B}(2z-x) \\
&= J_{\beta B}\Big(\tfrac{\beta}{\alpha}(2z-x)+ 
\big(1-\tfrac{\beta}{\alpha}\big)J_{\alpha B}(2z-x) \Big)= 
J_{\beta B}\Big(\tfrac{\beta}{\alpha}(2z-x)+ 
\big(1-\tfrac{\beta}{\alpha}\big)z \Big) \\
&=
J_{\beta B}\Big(2 z - \big(1-\tfrac{\beta}{\alpha}\big)z - 
\tfrac{\beta}{\alpha}x \Big)
= 
J_{\beta B}(2z - y)= J_{\beta B}R_{\beta A}y.
\end{align*}
Hence $z=J_{\beta A}y = J_{\beta B}R_{\beta A}y$ 
and so $y\in \Fix T_\beta$. 
The conclusion now follows from Lemma~\ref{l:bijection}.
\end{proof}

Combining the previous theorem with the continuity result in Proposition~\ref{p:resnice} yields the following for the DR operator.

\begin{corollary} \label{c:DR-op-bicont}
Let $A$ and $B$ be maximally monotone on $X$, and $T_{\gamma}$ be the DR operator defined in \eqref{e:0222d}. The operator 
\begin{equation*}
X\times \RP \to X \colon (x,\gamma)\mapsto \begin{cases} 
                                             T_{\gamma}x & \gamma\in\RPP \\
                                             x-P_{\overline{\dom A}}x+P_{\overline{\dom B}}(2P_{\overline{\dom B}}x-x)& \gamma=0,\\
                                           \end{cases}
\end{equation*}
is continuous on $X\times \RP$ and locally Lipschitz continuous on compact subsets of $X\times\RPP$.
\end{corollary}
\begin{proof}
Since $T_{\gamma}=\Id-J_{\gamma A}+J_{\gamma B}(2J_{\gamma A}-\Id)$, the result follows from Proposition~\ref{p:resnice}.
\end{proof}

The results proven in this section, in particular, Lemma~\ref{l:bijection}, Proposition~\ref{p:Q} and Theorem~\ref{t:DRbijection}, motivate the abstract framework we develop in Section~\ref{s:abstract-framework}. The operator $Q_{\beta\gets \alpha}$ defined in Proposition~\ref{p:Q} will provide the first example of what we will soon call a \Qname~ (Definition~\ref{d:Q-transport}).


