The following result establishes a parametric generalisation of Fact~\ref{f:demi}.
\begin{theorem}[Parametric demiclosedness principle] \label{t:edemi}
    Let $D \subseteq X$ be a nonempty weakly sequentially closed set,  $\Gamma\subseteq\RR$ be a nonempty closed set, and let $(T_{\gamma})_{\gamma\in\Gamma}$ be a family of nonexpansive operators from $D$ to $X$, such that $(\forall x \in D)\; \gamma \mapsto T_{\gamma}x$ is (strongly) continuous. Then the operator
    \begin{align*}
        D \times \Gamma &\to X\colon(x,\gamma)\mapsto (\Id-T_{\gamma})x
    \end{align*} %$(x,\gamma) \in D \times \Gamma \mapsto (\Id-T_{\gamma})(x)$
    is parametrically demiclosed.
    \end{theorem}
\begin{proof}
    Let $(x_n, \gamma_n)_\nnn$ be a sequence in $D\times \Gamma$ such that $x_n \weakly x \in D$, $\gamma_n \to \overline{\gamma}\in\Gamma$, and $x_n - T_{\gamma_n}x_n =(\Id -T_{\gamma_n})x_n\to u$. We shall prove that $(\Id -T_{\overline{\gamma}})x =u$. Indeed, the continuity of $\gamma \mapsto T_{\gamma}x$ yields $T_{\overline{\gamma}}x - T_{\gamma_n}x\to0$. Thus, using the nonexpansiveness of $T_{\gamma_n}$ and the reverse triangle inequality, we have
    \begin{align*}
    \liminf_{n\to\infty} \|x_n - x\| & \geq \liminf_{n\to\infty} \|T_{\gamma_n}x_n - T_{\gamma_n}x\| \\
    & =  \liminf_{n\to\infty} \| (x_n - T_{\overline{\gamma}}x - u) + (u + T_{\gamma_n}x_n - x_n) + (T_{\overline{\gamma}}x - T_{\gamma_n}x) \| \\
    & \geq  \liminf_{n\to\infty} \| x_n - T_{\overline{\gamma}}x -u \| - \| u + T_{\gamma_n}x_n - x_n \| - \|T_{\overline{\gamma}}x - T_{\gamma_n}x \|  \\
    & =  \liminf_{n\to\infty} \| x_n - T_{\overline{\gamma}}x -u \| - \lim_{n\to\infty}\| u + T_{\gamma_n}x_n - x_n \| - \lim_{n\to\infty} \|T_{\overline{\gamma}}x - T_{\gamma_n}x \| \\
    & =  \liminf_{n\to\infty} \| x_n - T_{\overline{\gamma}}x -u \|.
    \end{align*}
    In view of \cite[Lemma 1]{MR211301}, we must have $x =T_{\overline{\gamma}}x +u$, or equivalently, $(\Id -T_{\overline{\gamma}})x =u$, which completes the proof.
\end{proof}    
