\begin{definition}[Fixed-point relocator] \label{d:Q-transport}
Let $\Gamma \subseteq \RPP$ be a nonempty set, and let $(T_\gamma)_{\gamma \in \Gamma}$ be a family of operators from $X$ to $X$. We say that the family of operators $(Q_{\delta\gets \gamma})_{\gamma,\delta \in \Gamma}$ on $X$ defines  \emph{\Qname{s}} for $(T_\gamma)_{\gamma \in \Gamma}$ with Lipschitz constants $(\Lip_{\delta\gets \gamma})_{\gamma,\delta \in \Gamma}$ in $[1,+\infty[$ if the following hold.
\begin{enumerate}
\item\label{a:trans_bijection}
$(\forall \gamma, \delta \in \Gamma)$ %$Q_{\delta\gets \gamma}$ is a bijection with inverse $Q_{\gamma\gets \delta}$, 
$Q_{\delta\gets \gamma}|_{\Fix T_\gamma}$ is a bijection from $\Fix T_\gamma$ to $\Fix T_\delta$.
\item \label{a:trans_cont} $(\forall \gamma \in \Gamma)(\forall x\in\Fix T_\gamma)$ $\Gamma\to X\colon \delta\mapsto Q_{\delta\gets \gamma}x$ is continuous. 
\item\label{a:trans_semigroup}%\todo{we only this to hold at fixed points}
%\textbf{(semigroup property)}
$(\forall \gamma, \delta, \varepsilon \in \Gamma)(\forall x \in \fix T_{\gamma})$ $Q_{\varepsilon\gets \delta}Q_{\delta\gets \gamma}x = Q_{\varepsilon\gets \gamma}x$.
\item\label{a:trans_nonex-type}
$(\forall \gamma, \delta \in \Gamma)$  $Q_{\delta\gets \gamma}$ is $\Lip_{\delta\gets \gamma}$-Lipschitz continuous.
%$(\forall \gamma, \delta \in \Gamma)$
%$Q_{\delta\gets \gamma}$ is $\max\{1, \frac{\delta}{\gamma}\}$-Lipschitz continuous.
%\todo[inline]{FA: we can change this condition in the following way to treat both cases $N=2$ and $N>2$:

