%or

%$(\exists M: \RR \times \RR \to \RPP)(\forall \gamma, \delta \subseteq \Gamma)$  $Q_{\delta\gets \gamma}$ is $M(\gamma,\delta)$-Lipschitz continuous.
%}
\end{enumerate}
\end{definition}

\begin{remark}[Fixed-point relocators outside the fixed-point set] \label{r:FPR} Given  \Qname{s} $(Q_{\delta\gets \gamma})_{\gamma,\delta\in\RPP}$ for $(T_\gamma)_{\gamma\in\RPP}$, observe that Definition~\ref{d:Q-transport}\ref{a:trans_bijection}--\ref{a:trans_semigroup} only need to hold on $\Fix T_\gamma$. Therefore, a \Qname~does not have to be unique. In fact, any Lipschitz operator $\tilde{Q}_{\delta\gets \gamma}$  such that $Q_{\delta\gets \gamma}|_{\Fix T_\gamma} = \tilde{Q}_{\delta\gets \gamma}|_{\Fix T_\gamma}$ also defines a \Qname~for $(T_\gamma)_{\gamma\in\RPP}$. We give an example of a such a case in Proposition~\ref{p:Qname-MT}.
\end{remark}




