\begin{lemma}[Fixed-point relocator for Douglas--Rachford] \label{l:example-Qname-DR}
Given a nonempty set $\Gamma \subseteq \RPP$ and the family of DR operators $(T_{\gamma})_{\gamma \in \Gamma}$ from on $X$ defined in \eqref{e:0222d}, $(\forall\gamma,\delta \in \Gamma)$ the operator  $Q_{\delta\gets \gamma}: X \to X$, such that
\begin{equation*}
   Q_{\delta\gets \gamma} := \tfrac{\delta}{\gamma}\Id 
  +\big(1-\tfrac{\delta}{\gamma}\big)J_{\gamma A},
\end{equation*} defines a \Qname~for $T_{\gamma}$ with Lipschitz constant $\Lip_{\delta\gets \gamma} = \max\{1, \frac{\delta}{\gamma}\}$.   
\end{lemma}

\begin{proof}
    Assertions \ref{a:trans_bijection} and \ref{a:trans_cont} from Definition~\ref{d:Q-transport} directly follow from Theorem~\ref{t:DRbijection} and Proposition~\ref{p:resnice}, respectively. For Assertion~\ref{a:trans_semigroup} , let $\gamma,\delta,\varepsilon\in\RPP$. Then, using \eqref{e:0222a} from Lemma~\ref{l:bijection}, we obtain 
\begin{align*}
Q_{\varepsilon\gets \delta}Q_{\delta\gets \gamma}
&= \Big(\tfrac{\varepsilon}{\delta}\Id +
\big(1-\tfrac{\varepsilon}{\delta}\big)J_{\delta A}\Big)
\Big(\tfrac{\delta}{\gamma}\Id +
\big(1-\tfrac{\delta}{\gamma}\big)J_{\gamma A}\Big)\\
&= 
\tfrac{\varepsilon}{\gamma}\Id +
\big(\tfrac{\varepsilon}{\delta}
-\tfrac{\varepsilon}{\gamma}\big)J_{\gamma A} 
+\big(1-\tfrac{\varepsilon}{\delta}\big)J_{\delta A}%
\Big(\tfrac{\delta}{\gamma}\Id +
\big(1-\tfrac{\delta}{\gamma}\big)J_{\gamma A}\Big)\\
&= 
\tfrac{\varepsilon}{\gamma}\Id +
\big(\tfrac{\varepsilon}{\delta}
-\tfrac{\varepsilon}{\gamma}\big)J_{\gamma A} 
+ \big(1-\tfrac{\varepsilon}{\delta}\big)J_{\gamma A}
= 
\tfrac{\varepsilon}{\gamma}\Id +
\big(1-\tfrac{\varepsilon}{\gamma}\big)J_{\gamma A}\\
&= Q_{\varepsilon\gets \gamma}.
\end{align*}
Finally, assertion~\ref{a:trans_nonex-type} holds due to Proposition~\ref{p:Q}.
%Assertions \ref{a:trans_semigroup} and \ref{a:trans_nonex-type} from Definition~\ref{d:Q-transport} follow similarly as proven in Lemma~\ref{l:example-Qname-J}.  %. with $\Lip_{\delta\gets \gamma} = \max\{1, \frac{\delta}{\gamma}\}$.    
\end{proof}

