In the next result, we show that the iteration scheme in \eqref{eq:RDR} and Algorithm~\ref{a:DR-2} are equivalent.

\begin{proposition}[Equivalence between relocated fixed-point iteration and efficient implementation of DR] \label{p:DR-reformulation}
    Given $x_0 \in X$, the sequences $(x_n)_\nnn, (w_n)_\nnn, (y_n)_\nnn , (z_n)_\nnn \subseteq X $ are generated by Algorithm~\ref{a:DR-N} if and only if $(x_n)_\nnn$ and $(w_n)_\nnn$ conform to \eqref{eq:RDR} and $(\forall \nnn)$ $y_n = J_{\gamma_n B}R_{\gamma_n A}x_n$ and $z_n = J_{\gamma_{n-1}A}w_{n-1}$.
\end{proposition}

\begin{proof}

It follows directly that \eqref{DR:variable-stepsize-2} is equivalent to the second identity in \eqref{eq:RDR}. To conclude, it suffices to show that $2z_n - x_n = R_{\gamma_n}x_n$.  From \eqref{e:0222a} and \eqref{DR:variable-stepsize-2}, it holds that $z_{n+1} = J_{\gamma_n A}w_{n} = J_{\gamma_{n+1} A}x_{n+1}$. The claim follows now from the definition of the reflectent.\end{proof}

In the following, we prove a technical result which defines the conditions on the stepsizes that guarantee convergence of Algorithm~\ref{a:DR-2}.

 \begin{lemma} \label{l:stepsize-condition}
Let $\Gamma \subseteq \RPP$ be nonempty and $(\gamma_n)_\nnn$ be a sequence such that
 \begin{equation}
\label{a:stepsize-series-2}
      \gamma_{\text{low}}:= \inf_\nnn \gamma_n > 0 \text{~and~}\sum_\nnn (\gamma_{n+1}-\gamma_n)_+ < \pinf.
\end{equation}  Then, the sequence $(\varepsilon_n)_\nnn$ defined by $(\forall\nnn) \; \varepsilon_n :=  \max\left\{0, \frac{\gamma_{n+1}}{\gamma_n} - 1\right\}$ satisfies $ \sum_\nnn \varepsilon_n < \pinf.$

 \end{lemma}

 \begin{proof}
    From the assumption, there exists $\gamma_{\text{low}} \in\RPP$ such that $(\forall\nnn) \; \gamma_{\text{low}} \leq \gamma_n $. Then $0\leq \varepsilon_n  \leq  \tfrac{(\gamma_{n+1} - \gamma_n)_+}{\gamma_{\text{low}}},$
and hence \eqref{a:stepsize-series-2} implies $ \sum_\nnn \varepsilon_n < \pinf.$
 \end{proof}

 \begin{remark}[On the stepsizes assumptions] \label{r:stepsize-cond} In the following, we comment on assumption \eqref{a:stepsize-series-2}. 

\begin{enumerate}
    \item The assumption $\sum_\nnn (\gamma_{n+1}-\gamma_n)_+ < \pinf$ is not enough to guarantee convergence of $(\gamma_n)_\nnn$. Indeed, let \begin{equation} \label{e:an}(\forall \nnn) \; a_n 
:= \gamma_{n+1} - \gamma_n.\end{equation} Then, $(\forall \nnn) \;\gamma_{n+1} = \gamma_1 +\sum_{i=1}^n a_i .$ Define %\begin{equation*}
   $ a_n = 
 (\tfrac{1}{2})^n \text{~if~} n \text{~is odd}$ and $ a_n =
 -1  \text{~otherwise.}$ 
%\end{equation*} 
Then %\begin{equation*}
   $(\forall \nnn) \; (a_n)_+ =(\tfrac{1}{2})^n \text{~if~} n \text{~is odd} $ and $ (a_n)_+ =
 0 \text{~~otherwise,}$ 
%\end{equation*} 
and $\sum_\nnn (a_n)_+ < \pinf$, but $(\gamma_n)_\nnn$ does not converge. 


\item \label{r:stepsize-equiv-cond} 
Assumption \eqref{a:stepsize-series-2} is equivalent to the stepsize condition in \cite[Theorem 3.2]{Lorenz-Tran-Dinh}, namely, \begin{equation} \label{a:alt-stepsize-cond}
    (\exists \gamma_{\text{low}}, \gamma_{\text{up}} \in \RPP ) \; \gamma_{\text{low}} \leq \gamma_n \leq \gamma_{\text{up}} \text{~~and~} \sum_\nnn|\gamma_{n+1}-\gamma_n| < \pinf.
\end{equation} In fact, let \eqref{a:alt-stepsize-cond} hold. Clearly $\sum_\nnn (\gamma_{n+1}-\gamma_n)_+ \leq \sum_\nnn |\gamma_{n+1}-\gamma_n|$. Since \eqref{a:alt-stepsize-cond} implies  $(\gamma_n)_\nnn$ is a Cauchy sequence, then the limit $\overline{\gamma}$ is bounded below by $\gamma_{\text{low}}\in\RPP$, and thus \eqref{a:stepsize-series-2} holds. Conversely, suppose \eqref{a:stepsize-series-2}  holds. Let $(a_n)_\nnn$ be as in \eqref{e:an}. Note that $(\forall \nnn)$ $(a_n)_+ = \frac{a_n + |a_n|}{2}$ and $\sum_{k=0}^n a_k = \gamma_{n+1} - \gamma_0$. Then $2 \sum_{k=0}^n (a_k)_+ = \gamma_{n+1} - \gamma_0 + \sum_{k=0}^n |a_k|$. In view of \eqref{a:stepsize-series-2}, $\gamma_{\text{low}} \leq \gamma_{n+1} = \gamma_0 + 2 \sum_{k=0}^n (a_k)_+ - \sum_{k=0}^n |a_k| $, which in turn implies $\sum_{k=0}^n |a_k| \leq \gamma_0 - \gamma_{\text{low}} + 2 \sum_{k=0}^n (a_k)_+$. Taking the limit as $n \to \pinf$, \eqref{a:stepsize-series-2} implies $\sum_{\nnn} |\gamma_{n+1} - \gamma_n| = \sum_{\nnn}|a_n| \leq \gamma_0 - \gamma_{\text{low}} + 2 \sum_{\nnn} (\gamma_{n+1} - \gamma_n)_+ < \pinf$. Therefore $(\gamma_n)_\nnn$ converges and $\gamma_{\text{up}} := \sup_\nnn \gamma < \pinf$, yielding \eqref{a:alt-stepsize-cond}. %Convergence of $(\gamma_n)_\nnn$ to $\overline{\gamma}\in\RPP$ implies the existence of the bounds $\gamma_{low},\gamma_{up}\in\RPP$ in \eqref{a:alt-stepsize-cond}. Let $(a_n)_\nnn$ be defined as in \eqref{e:an}. Suppose now, by way of a contradiction, that $\sum_\nnn|a_n|$ diverges. Since $\gamma_{n+1} = \sum_{i=1}^n a_i + \gamma_1$ defines a convergent sequence, then $\sum_\nnn a_n$ is conditionally convergent. Hence, $\sum_\nnn (a_n)_+$ diverges, a contradiction. Therefore, $\sum_\nnn a_n$ converges absolutely, yielding \eqref{a:alt-stepsize-cond}.


\item \label{r:stepsize-cond-3}
A sequence $(\gamma_n)_\nnn$ satisfying \eqref{a:stepsize-series-2} can be easily found, for instance, any bounded decreasing sequence of positive real numbers. Furthermore, the construction in \eqref{e:an} reveals that increasing sequences of stepsizes $(\gamma_n)_\nnn$ can also be included in our analysis, as long as %the corresponding sequence $(a_n)_\nnn$ is nonnegative, such that the series 
$\sum_\nnn a_n$ converges. Another example is due to~\ref{r:stepsize-equiv-cond}, as it allows to use the stepsize rules defined in \cite[Section 4]{Lorenz-Tran-Dinh}. A similar stepsize rule is used in \cite{lorenz2025degenerate}.
\end{enumerate}

\end{remark}


The following corollary is our main result regarding convergence of the relocated DR algorithm (Algorithm~\ref{a:DR-2}).
\begin{corollary}[Convergence of relocated DR algorithm] \label{c:variable-2-DR}
Let $\Gamma \subseteq \RPP$. Suppose $A, B$ are  maximally monotone operators on $X$ 
such that $Z := \zer(A+B)\neq\varnothing$. Let  \begin{equation*}
%\label{a:stepsize-series-3}
    (\gamma_n)_\nnn \text{~in~} \Gamma \text{~be a sequence that 
converges to~} \overline{\gamma}\in \Gamma %\setminus \{0\}, 
\text{~and~}  \sum_\nnn (\gamma_{n+1}-\gamma_n)_+ < \pinf . 
\end{equation*} 
Given $x_0  \in X$, generate the sequences $(x_n)_\nnn, (w_n)_\nnn, (y_n)_\nnn, (z_n)_\nnn $ with Algorithm~\ref{a:DR-2}. Then, $(x_n)_\nnn$ and $(w_n)_\nnn$ 
converge weakly to some $x \in \Fix T_{\overline{\gamma}}$, where $T_{\gamma}$ is the DR operator in \eqref{e:0222d}, and 
 $(z_{n})_\nnn$ and $(y_{n})_\nnn$ converge weakly to $J_{\overline{\gamma} A}x\in Z$.
\end{corollary}

\begin{proof}
   First, $\Fix T_\gamma \neq \varnothing$ from \eqref{e:Fix}. Since $T_\gamma$ is firmly nonexpansive, Assumption~\ref{a:trans}\ref{a:trans_avg} holds with $\alpha=\tfrac{1}{2}$. Assumption~\ref{a:trans}\ref{a:trans_bicont} follows from Corollary~\ref{c:DR-op-bicont}. In view of Proposition~\ref{p:DR-reformulation}, \eqref{eq:RFP} holds for the \Qname{s} of $(T_\gamma)_{\gamma\in\Gamma}$ given in Lemma~\ref{l:example-Qname-DR}. Due to Lemma~\ref{l:stepsize-condition}, the Lipschitz constants of the \Qname{s} satisfy \eqref{a:stepsize-series}. Hence, from Theorem~\ref{t:abstractconv}, since $w_n = T_{\gamma_n}x_n$, then $x_n - w_n \to 0$, and $(x_n)_\nnn$ and $(w_n)_\nnn$ 
converge weakly to some $x \in \Fix T_{\overline{\gamma}}$

    Turning to the other sequences, we have $z_n = J_{\gamma_n A}x_n$, $y_n =  J_{\gamma_n B}(2 z_n - x_n)$ and $w_n =x_n -z_n +y_n$. Then $\frac{x_n - z_n}{\gamma_n} \in A z_n$ and $y_n \in B^{-1}(\frac{z_n - w_n}{\gamma_n})$. With this notation, $y_n -z_n = w_n - x_n \to 0$. %, and thus $(w_n)_\nnn$ converges weakly to $x$. 
    Moreover, rearranging terms, we have 
\begin{equation*}
    \begin{pmatrix}
        \frac{x_n - w_n}{\gamma_n} \\ w_n - x_n
    \end{pmatrix} \in \left( \begin{bmatrix}
        A \\ B^{-1}
    \end{bmatrix} + \begin{bmatrix}
        0 & \Id \\ -\Id & 0
    \end{bmatrix}\right)\begin{pmatrix}
        z_n \\ \frac{z_n - w_n}{\gamma_n}
    \end{pmatrix}.
\end{equation*}
Note that the operator above is maximally monotone (Fact~\ref{f:sum-monotone}), and hence demiclosed in view of Fact~\ref{f:maximal-demiclosed}. %\cite[Lemma 1]{csetnek2019shadow}\todo{should we put this in the prelim?}. 
Since $(x_n)_\nnn$ is bounded, so is $(z_n)_\nnn$ due to Proposition~\ref{p:resnice}. Given a weak cluster point $z$ of $(z_n)_\nnn$ and $z_{k_n}\weakly z$, then taking the limits $x_{k_n} \weakly x$, $w_{k_n} \weakly x$ and $\gamma_{k_n} \to \overline{\gamma}$ in the relation above yields
\begin{equation*}
    \begin{pmatrix}
        0 \\ 0
    \end{pmatrix} \in \begin{bmatrix}
        A \\ B^{-1}
    \end{bmatrix}\begin{pmatrix}
        z \\ \frac{z - x}{\overline{\gamma}}
    \end{pmatrix} + \begin{pmatrix}
        \frac{z - x}{\overline{\gamma}} \\ -z
    \end{pmatrix}.
\end{equation*} 
Hence $x -z\in \overline{\gamma} A (z)$ and $z - x \in \overline{\gamma}B(z) $, so that $z \in Z$ and $z = J_{\overline{\gamma} A}(x)$. In other words, all cluster points of $(z_n)_\nnn$ coincide and $z_n \weakly J_{\overline{\gamma} A}x$. As $y_n -z_n\to 0$, we also have that $y_n \weakly J_{\overline{\gamma} A}x$.
\end{proof}

\begin{remark}[Relationship with non-stationary DR] \label{r:non-stat-DR} The non-stationary DR algorithm in  \cite[Eq. (12)]{Lorenz-Tran-Dinh}  is a particular case of Algorithm~\ref{a:DR-2}. Indeed, given $w_0 \in X$ and $\gamma_0 \in \RPP$, consider the sequences generated by \cite[Eq. (12)]{Lorenz-Tran-Dinh}: $(\forall\nnn)\;z_n = J_{\gamma_{n-1}A}w_{n-1}$, $\kappa_n = \tfrac{\|z_n\|}{\|z_n - w_{n-1}\|}$, $\gamma_n = \kappa_n \gamma_{n-1}$, $y_n = J_{\gamma_nB}((1+\kappa_n)z_n - \kappa_n w_{n-1})$, and $w_n = y_n + \kappa_n( w_{n-1} - z_n)$. By setting $x_n = \kappa_nw_{n-1} + (1 - \kappa_n)z_n$, then \eqref{DR:variable-stepsize-2} holds. Furthermore, since $x_{n} - z_{n} = \tfrac{\gamma_{n}}{\gamma_{n-1}}(w_{n-1} - z_{n})$, then $w_n = y_n + x_n - z_n$, and $y_n = J_{\gamma_n B}(z_n + \kappa_n(z_n - w_{n-1})) = J_{\gamma_n B}(2z_n - x_n)$, and thus \eqref{DR:variable-stepsize-1} holds, recovering Algorithm~\ref{a:DR-2}. Hence, in view of Remark~\ref{r:stepsize-cond}\ref{r:stepsize-equiv-cond}, Corollary~\ref{c:variable-2-DR} recovers the convergence results in \cite[Theorem 3.2]{Lorenz-Tran-Dinh}.
\end{remark}


\begin{remark}[Disjoint fixed-point sets]
\label{r:disjoint} 
Let us stress that Theorem~\ref{t:abstractconv}---and thus also Corollary~\ref{c:NDR-convergence}---can lead to cases 
where all fixed-point sets $\Fix T_\gamma$ are pairwise disjoint.
Indeed, suppose that $X=\RR$ and consider the optimization problem 
of minimizing $f(x)+g(x)$, where 
$f = \iota_{\{1\}}$ and $g=-\ln$ (with $\dom g= \RPP$). 
This problem has only 
one feasible point, $z:=1$, which is also the minimizer of $f+g$. 
Set $A=\partial f = N_{\{1\}}$ and $B=\partial g$. 
Then $Z=\zer(A+B)=\{1\}$. 
Now let $\gamma\in\RPP$. 
First, $J_{\gamma A}= P_{\{1\}}$ is a constant operator  
while 
\begin{equation*}
J_{\gamma B}x = \frac{x+\sqrt{x^2+4\gamma}}{2}
\end{equation*}
by, e.g., \cite[Example~24.40]{BC2017}. 
Now $R_{\gamma A}x = 2z-x=2-x$ and so the Douglas--Rachford operator
$T_\gamma$ satisfies 
\begin{equation*} 
T_{\gamma}x = x - 1 + \frac{(2-x)+\sqrt{(2-x)^2+4\gamma}}{2}
= \frac{x+\sqrt{(2-x)^2+4\gamma}}{2}
\;\;\text{and so}\;\; \Fix T_\gamma = \{1+\gamma\}. 
\end{equation*}
This motivates the need for the proposed notion of an Opial sequence  with respect to a sequence of sets that may be pairwise disjoint.
