\end{remark}


\section{Resolvent splitting methods with variable stepsize} \label{sec:resolvent-splitting}



%In the next section, we apply Corollary~\ref{c:RPPP-convergence} to obtain convergent variants of resolvent splitting methods with variable stepsizes. In particular, we propose a variant of the Malitski--Tam resolvent splitting method by identifying an appropriate \Qname. As a result, we also establish convergence of Algorithm~\ref{a:DR-2}.


%$\Fix \hat{T}_\gamma = \zer(\mA_\gamma)$ and $\C^* \Fix \hat{T}_\gamma = \Fix T_\gamma$





In this section, we generalize our analysis in Section~\ref{s:variable-2-DR}, and develop a variable stepsize resolvent splitting framework to solve (maximally) monotone inclusions of the form
\begin{equation} \label{e:N-inclusion}
   \text{find~~} x \in X \text{~~such that~~} 0 \in \sum_{i=1}^N A_i (x),
\end{equation} for $N \geq 2$, based upon the \emph{graph-based DR} framework introduced in \cite{bredies2024graph}. We show that the relocated fixed-point iteration associated with the graph-based DR method converges weakly to a fixed-point of the underlying nonexpansive operator---in the sense of Theorem~\ref{t:abstractconv}---and then leverage this result to deduce variable stepsize extensions of some known resolvent splitting algorithms. %, including the \todo{change} Douglas--Rachford algorithm to solve \eqref{e:N-inclusion} for $N=2$. 


\subsection{Graph-based DR with variable stepsize}


The resolvent splitting methods we analyze in this section are constructed using directed graphs, in which each node belongs to one of the operators in \eqref{e:N-inclusion}, and the arcs determine the order of evaluation of the resolvents  of each operator.  We follow \cite{bredies2024graph} to define the setting.

Let $N \geq 2$ and $G = (\mN, \mE)$ be a connected directed graph such that \begin{equation} \label{e:diG-a1}
    \mN := \{1, \dots, N\}\text{~~and~~} (i,j) \in \mE \implies i <j.
\end{equation} For $i \in \mN$, $d_i$ denotes the \emph{degree} of node $i$ which is the cardinality of the set of nodes \emph{adjacent} to $i$: %\begin{equation*}
    $d_i := |\{j \in \mN: (i,j) \in \mE \text{~~or~~} (j,i) \in \mE\}|.$ 
%\end{equation*} 
Similarly, $d_i^+$ denotes the \emph{in-degree} of $i$:
%\begin{equation*}
    $d_i^+ := |\{j \in \mN:  (j,i) \in \mE\}|$, and  
%\end{equation*}
$d_i^-$ denotes the \emph{out-degree} of $i$:
%\begin{equation*}
    $d_i^- := |\{j \in \mN:  (i,j) \in \mE\}|.$ Clearly, $d_i = d_i^+ + d_i^-$. 
Let $G^\prime = (\mN, \mE^\prime)$ be a connected subgraph of $G$ with the same set of nodes. The topology of $G^\prime$ defines an iteration operator, which we proceed to describe following \cite[Section 3]{bredies2024graph}. First, recall that the \emph{Laplacian} of $G^\prime$ is the matrix $L \in \RR^{N\times N}$  given by
\begin{equation*}
    (\forall i,j \in \mN)\; L_{ij} := \begin{cases} 
                    d_i & \text{~~if~~} i=j \\
                    -1 & \text{~~if~~} (i,j) \in \mE^\prime \text{~~or~~} (j,i) \in \mE^\prime \\
                    0 & \text{otherwise.}
                  \end{cases}.
\end{equation*} Let $Z \in \RR^{N \times (N-1)}$ define a so-called \emph{onto decomposition} of $L$, which is possible due to \cite[Proposition 2.1]{bredies2024graph}. That is, $Z^*$ is a surjective matrix such that $L = ZZ^*$. Further, it also holds that $\ker(Z^*) = \Span\{\bone\}$ \cite[Eq. (2.9)]{bredies2022degenerate}, where $\bone := (1,\dots,1)\in\mathbb{R}^N$. Given $k \geq 1$, denote by $I_k$ the identity map on $X^{k}$, and set $\mZ^* := Z^* \otimes I_{1}$ where $\otimes$ denotes the Kronecker product.  We also adopt the notation $\bx \in X^{N-1}$ and  $\bz \in X^{N}$ with $\bx = (x_1,\dots, x_{N-1})$ and $\bz = (z_1,\dots, z_{N})$. In view of \cite[eq. (12)]{tam2024frugal}, \begin{equation} \label{e:Ker-Im}
    \ker(\mZ^*) = \{ \bx \in X^{N-1}: x_1 = \dots = x_{N-1}\} \text{~~and Im} (\mZ) = \{ \bz \in X^N: \sum_{i=1}^N z_i = 0\}.
\end{equation}

Define the operators $\C: X^{N-1} \to X^{2N-1}$ and $\mM: X^{2N-1} \to X^{2N-1}$ by
\begin{equation} \label{e:graph-DR-M}
     \C^* := [\mZ^* \quad I_{N-1}], \text{~~and~~}\mM := \begin{bmatrix}
        \mL & \mZ\\ \mZ^* & I_{N-1}
    \end{bmatrix},
\end{equation}
where $\mathcal{L}:=L\otimes I_{1}$. By construction, we have $\mM =\C\C^*$. Moreover, let $(\forall i \in \mN)\; \overline{d}_i$ denote the degree of $i$ in the graph $(\mN, \mE \setminus \mE^\prime)$ and define the matrices $R, P \in \RR^{N\times N}$ as follows \begin{equation*}
    (\forall i,j \in \mN)\; R_{ij} := \begin{cases} 
                    0 & \text{~~if~~} i=j \\
                    L_{ij} & \text{~~if~~} i >j \\
                    -L_{ij} & \text{otherwise}
                  \end{cases} \text{~~and~~} P_{ij} := \begin{cases} 
                    \overline{d}_{i} & \text{~~if~~} i=j \\
                    -2 & \text{~~if~~} (j,i) \in \mE \setminus \mE^\prime \\
                    0 & \text{otherwise}
                  \end{cases}.
\end{equation*}
By denoting $\mR := R \otimes I_1$ and $\mP := P \otimes I_1$, set \begin{equation*}
    (\forall \gamma \in \RPP)\; \mA_{L,\gamma} := \gamma \text{diag}(A_1, \dots, A_N) + \mR + \mP,
\end{equation*} where $\text{diag}(A_1, \dots, A_N): (x_1, \dots, x_N) \mapsto (A_1x_1, \dots, A_Nx_N)$ is the \emph{diagonal operator}, and \begin{equation*}
    \mA_{\gamma} := \begin{bmatrix}
        \mA_{L,\gamma} & - \mZ\\ \mZ^* & 0_{N-1}
    \end{bmatrix}
\end{equation*} with $0_{N-1}$ being the zero operator in $X^{N-1}$. The operator $\mA_{\gamma}$ is maximally monotone \cite[Theorem 3.1]{bredies2024graph}.

In this manner, given $\theta\in\left]0,2\right[$ and $\gamma \in \RPP $, the iteration operator $T_{\gamma}: X^{N-1} \to X^{N-1}$ for the graph-based DR method is given by \begin{equation} \label{e:graph-DR-T-1}
    (\forall \bx \in X^{N-1})\;T_\gamma\bx := (1-\theta)\bx+\theta J_{\C^*\vartriangleright \mA_\gamma}\bx \text{~~where~~} \C^*\vartriangleright \mA_\gamma := (\C^* \mA^{-1}_\gamma \C)^{-1}.
\end{equation}
Note that $J_{\C^*\vartriangleright \mA_\gamma}$ is well-defined as $\C^*\vartriangleright \mA_\gamma$ is maximally monotone due to \cite[Lemma 2.3]{bredies2022degenerate}.
% Likewise, given $\theta\in ,\gamma \in \RPP$, we define the operator $T_{\theta,\gamma}: X^{N-1} \to X^{N-1}$ as follows: \begin{equation*}
%     (\forall \bx \in X^{N-1})\;T_{\theta,\gamma}\bx = \bx + \theta (T_\gamma\bx - \bx).
% \end{equation*} Clearly, $(\forall \theta,\gamma \in \RPP)\; T_\gamma = T_{1,\gamma}$ and $\Fix T_\gamma = \Fix T_{\theta,\gamma}$. Furthermore, 
In view of \cite[Eqs. (3.9)--(3.10) \& Step 5 of Algorithm 3.1]{bredies2024graph}, it holds
\begin{equation} \label{e:graph-DR-T}
    (\forall \bx \in X^{N-1})\; T_{\gamma}\bx = \bx - \theta\mZ^*\bz,
\end{equation} 
where \begin{equation} \label{e:graph-DR-z}
    (\forall i = 1, \dots, N)\; z_i := J_{\frac{\gamma}{d_i}A_i}\left(\tfrac{2}{d_i} \sum_{(h,i)\in\mathcal{E}}z_h + \tfrac{1}{d_i}\sum_{j=1}^{N-1} Z_{ij}x_j\right).
\end{equation}
