    \begin{enumerate}
        \item \label{f:graph-DR-degree}
        $d_1 = 1$, $\sum_{i=2}^N d_i^+ = \sum_{i=1}^{N-1} d_i^- = |\mE| $ and $\sum_{i=1}^N d_i = 2|\mE|$.

