    \begin{proposition}[Fixed-point relocator for graph-based DR] \label{p:Qname-graph-DR}
    Let $\gamma, \delta \in \RPP$. Consider the operator $Q_{\delta\gets \gamma}: X^{N-1} \to X^{N-1}$ given by\begin{equation*}
         (\forall \bx \in X^{N-1}) \; Q_{\delta\gets \gamma}\bx = \tfrac{\delta}{\gamma}\bx +  \left(1 - \tfrac{\delta}{\gamma} \right)\mZ^{\dagger}\be(\bx),
    \end{equation*} where $\be(\bx)$ is defined in \eqref{eq:def-e} and $\mZ^{\dagger}$ denotes the pseudo-inverse of $\mZ = Z \otimes I_1$. %, is   a \Qname~for $\{T_{\gamma}\}_{\gamma>0}$ given by \eqref{e:graph-DR-T}--\eqref{e:graph-DR-z}. Let $\tilde{Q}_{\delta\gets \gamma}: X^{N-1} \to X^{N-1}$ be the operator defined as \begin{equation*} (\forall \bx \in X^{N-1}) \; \tilde{Q}_{\delta\gets \gamma}(\bx) = Q_{\delta\gets \gamma}(\bx) + \frac{1}{N}\left(1 - \tfrac{\delta}{\gamma} \right)\mZ^{-1}\left(\left(d_1z_1 + \sum_{i=2}^N(d_i-2d_i^+)z_i\right)\bone\right),\end{equation*} wher $\bz = (z_1,\dots, z_N)$ is given in \eqref{e:graph-DR-z}.   
    Then %both 
    $(Q_{\delta\gets \gamma})_{\gamma, \delta \in \RPP}$ %and $\{\tilde{Q}_{\delta\gets \gamma}\}$
    defines  \Qname{s} for the graph-based DR operators $(T_{\gamma})_{\gamma\in\RPP}$ given by \eqref{e:graph-DR-T}-\eqref{e:graph-DR-z} with is Lipschitz constant \begin{equation} \label{e:graphDR-Lip}
        (\forall \gamma,\delta \in \RPP)\; \Lip_{\delta\gets \gamma}\leq \tfrac{\delta}{\gamma} + \left|1-\tfrac{\delta}{\gamma}\right|\|\mZ^{\dagger}\|\sqrt{\sum_{i=1}^N \tfrac{(d_i - 2d_i^+)^2}{d_i^2}L_i^2}.
        \end{equation}
    \end{proposition}

