%is firmly nonexpansive from Fact~\ref{f:CdA-mm}\ref{f:CdA-mm-1}.

%In order to apply the theory for relocated fixed-point iterations, we need to identity a nontrivial \Qname~for the Malitsky--Tam operator. 
In view of Proposition~\ref{p:Qname-graph-DR}, finding an appropriate \Qname~for the iteration operator defined in \eqref{e:graph-DR-T}--\eqref{e:graph-DR-z} amounts to solving the system of equations \eqref{e:system-Q}. In the following, we define a \Qname for this operator  by employing  Remark~\ref{r:FPR}. %These \Qname s correspond to a natural extension of the \Qname~for the classical DR operator presented in Lemma~\ref{l:example-Qname-DR}.


\begin{proposition}[Fixed-point relocator for Malitsky--Tam operator] \label{p:Qname-MT}
For $\gamma, \delta \in \RPP$, consider the operator %s $Q_{\delta\gets \gamma} = (Q_{\delta\gets \gamma}^1,\dots, Q_{\delta\gets \gamma}^{N-1}): X^{N-1} \to X^{N-1}$ and 
$\tilde{Q}_{\delta\gets \gamma} = (\tilde{Q}_{\delta\gets \gamma}^1,\dots, \tilde{Q}_{\delta\gets \gamma}^{N-1}): X^{N-1} \to X^{N-1}$ defined $(\forall \bx = (x_1,\dots,x_{N-1}) \in X^{N-1})$ as \begin{equation} \label{tQ:N-op}
\left\{\begin{aligned}
 \tilde{Q}_{\delta\gets \gamma}^1(\bx) & = \left(\tfrac{\delta}{\gamma}\Id 
  +\big(1-\tfrac{\delta}{\gamma}\big)J_{\gamma A_1}\right)(x_1)  \\
\tilde{Q}_{\delta\gets \gamma}^i(\bx) & = \tfrac{\delta}{\gamma}(x_i -x_1) 
  +\tilde{Q}_{\delta\gets \gamma}^{1}(\bx), \text{~~for~~} i=2,\dots,N-1.\\
\end{aligned}\right.
\end{equation}  Then,  %$\{Q_{\delta\gets \gamma}\}_{\gamma , \delta >0}$ and 
$(\tilde{Q}_{\delta\gets \gamma})_{\gamma , \delta \in \RPP}$ defines  \Qname{s} for $(T_{\gamma})_{\gamma\in\RPP}$ given by \eqref{e:n-it-op-T}--\eqref{e:n-it-op-z}, with Lipschitz constant \begin{equation} \label{e:Lip-tQ}
    \tilde{\Lip}_{\delta\gets \gamma} = \max\{1,\tfrac{\delta}{\gamma}\} + (N-2)|1-\tfrac{\delta}{\gamma}|.
\end{equation}
\end{proposition}

\begin{proof}

Using the change of variables \eqref{e:change-of-var}, $(Q_{\delta\gets \gamma})_{\gamma,\delta \in\RPP}$ defined $(\forall \bx \in X^{N-1})$ by\begin{equation} \label{Q:N-op}
\left\{\begin{aligned}
 Q_{\delta\gets \gamma}^1(\bx) & = \left(\tfrac{\delta}{\gamma}\Id 
  +\big(1-\tfrac{\delta}{\gamma}\big)J_{\gamma A_1}\right)(x_1) - \tfrac{1}{N}\big(1-\tfrac{\delta}{\gamma}\big)( J_{\gamma A_1}(x_1) - z_N ) )  \\
Q_{\delta\gets \gamma}^i(\bx) & = \tfrac{\delta}{\gamma}(x_i -x_{i-1}) + Q_{\delta\gets \gamma}^{i-1}(\bx)
 - \tfrac{1}{N}\big(1-\tfrac{\delta}{\gamma}\big)( J_{\gamma A_1}(x_1) - z_N ), \text{~~for~~} i=2,\dots,N-1.\\
\end{aligned}\right.
\end{equation} where $z_N$ is given in \eqref{e:n-it-op-z}, %$\{Q_{\delta\gets \gamma}\}_{\gamma,\delta >0}$ 
are \Qname{s} for $(T_{\gamma})_{\gamma\in\RPP}$ in view of Proposition~\ref{p:Qname-graph-DR} and \eqref{e:MT-incidence}. %Indeed, given $\bx \in X^{N-1}$ and $\gamma,\delta \in \RPP$, $\by = Q_{\delta\gets \gamma}\bx$ if and only if \eqref{e:system-Q} holds, which in turn is equivalent to \begin{equation*}
    %\left\{\begin{aligned}
      %   y_1 & = \tfrac{\delta}{\gamma}x_1 + \left(1-\tfrac{\delta}{\gamma}\right)\left(z_1 - \tfrac{1}{N}(z_1 - z_N)\right) \\
   % y_i & = y_{i-1} + \tfrac{\delta}{\gamma}(x_i - x_{i-1})  -\tfrac{1}{N} \left(1-\tfrac{\delta}{\gamma}\right) (z_1 - z_N)\text{~~for~~} i=2,\dots, N-1,
   % \end{aligned}\right.
%\end{equation*} where $z_1 = J_{\gamma A_1}(x_1)$. Rearranging terms yields \eqref{Q:N-op}. 
Furthermore, from  \eqref{tQ:N-op}, it holds that \begin{equation} \label{e:Q-induction}
            (\forall i=2,\dots,N-1)\; \tilde{Q}_{\delta\gets \gamma}^i(x_1,\dots,x_{N-1}) = \tfrac{\delta}{\gamma}(x_i-x_{i-1}) + \tilde{Q}_{\delta\gets \gamma}^{i-1}(x_1,\dots,x_{N-1}),
        \end{equation} which implies $Q_{\delta\gets \gamma}|_{\Fix T_\gamma} = \tilde{Q}_{\delta\gets \gamma}|_{\Fix T_\gamma}$. To see this, take $x \in \Fix T_\gamma$, so that from \eqref{e:n-it-op-T}, $z_1 = z_N$. Then $Q_{\delta\gets \gamma}^1(\bx) = \tilde{Q}_{\delta\gets \gamma}^1(\bx)$, and from \eqref{e:Q-induction}, $(\forall i = 2, \dots, N-1)$ 
 $Q_{\beta\gets \alpha}^i(\bx) - Q_{\beta\gets \alpha}^{i-1}(\bx) = \tilde{Q}_{\beta\gets \alpha}^i(\bx) - \tilde{Q}_{\beta\gets \alpha}^{i-1}(\bx)$. In turn, by induction, it follows that $Q_{\delta\gets \gamma}^i(\bx) = \tilde{Q}_{\delta\gets \gamma}^i(\bx)$, which proves the claim. We next show $\tilde{Q}_{\delta\gets \gamma}$ is Lipschitz continuous. Take $\bx, \bw \in X^{N-1}$. It follows from Proposition~\ref{p:Q} that \begin{equation*}
    \|\tilde{Q}_{\delta\gets \gamma}^1(\bx) - \tilde{Q}_{\delta\gets \gamma}^1(\bw)\| \leq \max\left\{1,\tfrac{\delta}{\gamma}\right\}\|x_1 - w_1\|.
\end{equation*} Furthermore, for $i = 2, \dots, N-1$, \eqref{tQ:N-op} and Fact~\ref{f:resolvents}\ref{f:resolvents-nonexpansive} yield \begin{align*}
    \|\tilde{Q}_{\delta\gets \gamma}^i(\bx) - \tilde{Q}_{\delta\gets \gamma}^i(\bw) \| & = \left\| \tfrac{\delta}{\gamma}(x_i - w_i) + \left( 1 - \tfrac{\delta}{\gamma}\right)(J_{\gamma A_1}x_1 - J_{\gamma A_1}w_1) \right\| \\
    & \leq \tfrac{\delta}{\gamma} \|x_i - w_i\| + \left| 1 - \tfrac{\delta}{\gamma}\right| \|x_1 - w_1\|.
\end{align*} Hence, \begin{equation*}
    \|\tilde{Q}_{\delta\gets \gamma}(\bx) - \tilde{Q}_{\delta\gets \gamma}(\bw) \| \leq \left( \max\left\{1,\tfrac{\delta}{\gamma}\right\} + (N-2)\left| 1 - \tfrac{\delta}{\gamma}\right| \right)\| x_1 - w_1 \| + \tfrac{\delta}{\gamma} \sum_{i=2}^{N-1}\|x_i - w_i\|.
\end{equation*} Therefore, $\tilde{Q}_{\delta\gets \gamma}$ is Lipschitz continuous with constant \eqref{e:Lip-tQ}. The conclusion now follows from Remark~\ref{r:FPR}.
\end{proof}

%Different fixed-point relocators naturally yield different variable stepsize variants of the method with different features. 
In Algorithm~\ref{a:DR-N}, we introduce a variable stepsize resolvent splitting algorithm for finding a zero of $\sum_{i=1}^N A_i$, a variant of the Malitsky--Tam method \cite{MT23}, stemming from the relocated fixed-point iteration associated with the \Qname~  introduced in Proposition~\ref{p:Qname-MT}. This \Qname~produces an algorithm that only requires one resolvent evaluation per maximally monotone operator in each iteration, just as its original form, i.e. the method with constant stepsize. Although using the \Qname{s} $({Q}_{\delta\gets \gamma})_{\gamma, \delta\in\RPP}$ in \eqref{Q:N-op} gives a convergent variable stepsize variant of the Malitsky-Tam algorithm, it result in a method that needs more resolvent evaluations than the original algorithm.


\begin{algorithm}[!ht]
\caption{Variable stepsize resolvent splitting  for finding a zero of $\sum_{i=1}^NA_i$, $N\geq 2$. \label{a:DR-N}}
\SetKwInOut{Input}{Input}
\Input{Choose $ x_{0}^1, \dots, x_{0}^{N-1} \in X$ and $\theta \in\zeroun$.}

Define $z_{0}^1 = J_{\gamma_1 A_1}(x_{0}^1)$.

\For{$n=0,1,\dots$}{
Step 1. Intermediate step. Compute \begin{equation} \label{e:intermediate-N}
    \bw_n = \bx_n + \theta \begin{pmatrix}
        z_{n}^2 - z_{n}^1\\ \vdots \\ z_{n}^N - z_{n}^{N-1}
    \end{pmatrix}
\end{equation} where $z_{n}^1, \dots, z_{n}^N \in X$ are given by \begin{equation*} 
     \left\{\begin{aligned}
         z_{n}^i &= J_{\gamma_n A_i}(x_{n}^i + z_{n}^{i-1} - x_{n}^{i-1}) & \text{~for~} i = 2, \dots, N-1\\
         z_{n}^N &= J_{\gamma_n A_N}(z_{n}^1 + z_{n}^{N-1} - x_{n}^{N-1}).&
     \end{aligned}\right.
\end{equation*}

Step 2. Next iterate. Compute
\begin{equation} \label{DR:variable-stepsize-N} 
    \begin{cases}
    z_{n+1}^1  = J_{\gamma_n A_1}w_{n}^1\\
    x_{n+1}^1  = \dfrac{\gamma_{n+1}}{\gamma_n} w_{n}^1 + \left( 1 - \dfrac{\gamma_{n+1}}{\gamma_n}\right) z_{n+1}^1
    \end{cases}
\end{equation}

For $i = 2, \dots, N-2$, 
\begin{equation} \label{DR:variable-stepsize-N-b} 
    %\begin{cases}
    %z_{n}^{i+1}  = J_{\gamma_n A_{i+1}}(x_{i+1,n} + z_{n}^i - x_{n}^i)\\
    %w_{n}^i   = x_{n}^i + \tau ( z_{n}^{i+1} - z_{n}^i )\\
    x_{n+1}^i  = \dfrac{\gamma_{n+1}}{\gamma_n} (w_{n}^i - w_{n}^1) + x_{n+1}^1.
    %\end{cases}
\end{equation}

}
\end{algorithm}

In the following, we formalize the idea that Algorithm~\ref{a:DR-N} can be reformulated as a relocated fixed-point iteration of the operator defined in \eqref{e:n-it-op-T}--\eqref{e:n-it-op-z} for the \Qname~in Proposition~\ref{p:Qname-MT}. Then, we show convergence of Algorithm~\ref{a:DR-N}  using Corollary~\ref{c:graph-DR-convergence}. %In order to do that, we first define its \Qname.

\begin{proposition}[Equivalence between relocated fixed-point iteration and efficient implementation] \label{p:DR-N-reformulation}
    Given $\bx_0  \in X^{N-1}$ and $\theta \in \zeroun$, the sequences $(\bx_n)_\nnn, (\bw_n)_\nnn \subseteq X^{N-1}$ and $ (\bz_n)_\nnn \subseteq X^{N}$ are generated by Algorithm~\ref{a:DR-N} if and only if $(\bz_n)_\nnn$ conforms to \eqref{e:n-it-op-z} and \begin{equation*}
 \left\{\begin{aligned}
    \bw_n     &= T_{\gamma_n}\bx_n \\
    \bx_{n+1} &= \tilde{Q}_{\gamma_{n+1}\gets \gamma_n}\bw_n \\
   \end{aligned}\right. 
\end{equation*} where the operators $(T_{\gamma})_{\gamma \in \RPP}$ are defined in \eqref{e:n-it-op-T}--\eqref{e:n-it-op-z} and $(\tilde{Q}_{\delta\gets \gamma})_{\gamma,\delta \in \RPP}$  in \eqref{tQ:N-op}.
\end{proposition}


\begin{proof}


From \eqref{e:0222a} and \eqref{DR:variable-stepsize-N}, it follows that $ z_{n+1}^1 = J_{\gamma_n A_1}(w_{n}^1) = J_{\gamma_{n+1} A_1}(x_{n+1}^1).$
Therefore \eqref{e:n-it-op-z} holds for $(\bz_n)_\nnn$. In this manner, \eqref{e:n-it-op-z} %\eqref{a:z-N-DR} 
and \eqref{e:intermediate-N} yield $\bw_n     = T_{\gamma_n}\bx_n$. Moreover, \eqref{DR:variable-stepsize-N}  implies $x_{n+1}^1 = \tilde{Q}^1_{\gamma_{n+1}\gets \gamma_n}(\bw_{n})$, and \eqref{DR:variable-stepsize-N-b} yields $(\forall i = 2, \dots, N)$ $x_{n+1}^i  = \tilde{Q}^i_{\gamma_{n+1}\gets \gamma_n}(\bw_{n})$.

\end{proof}

