   %      z_{n}^i &= J_{\gamma_n A_i}(x_{n}^i + z_{n}^{i-1} - x_{n}^{i-1}) & \text{~for~} i = 2, \dots, N-1\\
    %     z_{n}^N &= J_{\gamma_n A_N}(z_{n}^1 + z_{n}^{N-1} - x_{n}^{N-1}).&
    % \end{aligned}\right.
%\end{equation}







%In view of Proposition~\ref{p:DR-N-reformulation} and Lemma~\ref{l:stepsize-condition}, the convergence of Algorithm~\ref{a:DR-N} is a consequence of Corollary~\ref{c:graph-DR-convergence}.


\begin{corollary}[Convergence of variable stepsize Malitsky--Tam resolvent splitting] \label{c:NDR-convergence}
Given $N\geq 2$, suppose that $A_1, \dots, A_N$ are $N$ maximally monotone operators on $X$ 
such that $\zer(\sum_{i=1}^N A_i)\neq\varnothing$.  Let $\Gamma\subseteq \RPP$ be nonemtpy, $\theta\in\zeroun$ and %\begin{equation}
%\label{a:stepsize-series-N}
    $(\gamma_n)_\nnn \text{~in~} \Gamma \text{~be a sequence that 
converges to~} \overline{\gamma}\in \Gamma 
\text{~and~}  \sum_\nnn (\gamma_{n+1}-\gamma_n)_+ < \pinf .$ 
%\end{equation} 
Given $\bx_0 \in X^{N-1}$, consider the sequences $(\bx_n)_\nnn, (\bw_n)_\nnn \subseteq X^{N-1}$ and $ (\bz_n)_\nnn \subseteq X^{N}$ generated by Algorithm~\ref{a:DR-N}. Then, 
both sequences $(\bx_n)_\nnn$ and $(\bw_n)_\nnn$ 
converge weakly to some point $\bx \in \Fix T_{\overline{\gamma}}$, where $T_{\gamma}$ is the iteration operator defined in \eqref{e:n-it-op-T}--\eqref{e:n-it-op-z}, and
$(\forall i \in \mN)$ $(z_{n}^i)_\nnn$ converges weakly to $J_{\overline{\gamma} A_1}x_1\in Z$.
\end{corollary}

\begin{proof}
     First, $(\bx_n)_\nnn$ is a relocated fixed-point iteration (Proposition~\ref{p:DR-N-reformulation}) of the operator $T_{\gamma}$ with \Qname~given in \eqref{tQ:N-op}. Moreover, from Remark~\ref{r:stepsize-cond}\ref{r:stepsize-equiv-cond}, there exists  $\gamma_{low} \in\RPP$ such that $(\forall\nnn) \; \gamma_{low} \leq \gamma_n$. Thus, from \eqref{e:Lip-tQ},
   \begin{align*}
\tilde{\Lip}_{\gamma_{n+1}\gets \gamma_n} -1 & = \max\left\{0, \frac{\gamma_{n+1}}{\gamma_n} - 1\right\} + (N-2)\left|1-\frac{\gamma_{n+1}}{\gamma_n}\right| \\
       &=  \max\left\{0, \frac{\gamma_{n+1}}{\gamma_n} - 1\right\} + \frac{N-2}{\gamma_{low}}|\gamma_n-\gamma_{n+1}|.
   \end{align*} The first term in the last line defines a convergent series in view of Lemma~\ref{l:stepsize-condition}, while the second term conforms a finite series due to Remark~\ref{r:stepsize-cond}\ref{r:stepsize-equiv-cond}, therefore $\sum_{\nnn}(\Lip_{\gamma_{n+1}\gets \gamma_n} -1) < \pinf$. From Corollary~\ref{c:graph-DR-convergence}, $(\bx_n)_\nnn$ converges weakly to some $\bx \in \Fix T_{\overline{\gamma}}$ and   $(\forall i = 1, \dots , N)$ $(z_{n}^i)_\nnn$ converges weakly to $z\in \zer(\sum_{i=1}^N A_i)$ given in \eqref{e:tilde-zeta}. In particular, it holds that $z = z_1 =J_{\overline{\gamma} A_1}x_1$. %Observe that the definition of the set $\Omega_{\overline{\gamma}}$ implies that $z = J_{\gamma A_1}(x_1)$. Finally, convergence of $(\bw_n)_\nnn$ to $\bx$ follows from Theorem~\ref{t:abstractconv}\ref{t:abstractconv1} and Proposition~\ref{p:DR-N-reformulation}.
\end{proof}



