\subsubsection{Variable stepsize resolvent splitting method for $N=3$ operators}

In \cite{ryu2020uniqueness}, the author introduces a three-operator resolvent splitting method, an extension of the Douglas-Rachford algorithm different from \cite{MT23}. In this section, we propose a variable stepsize extension of Ryu's resolvent splitting method. First, the method  also corresponds to an instance of the graph-based DR algorithm \cite[Section 3.1]{bredies2024graph} by taking\begin{equation*}
    \mE^\prime = \{(1,3), (2,3)\} \text{~~and~~} \mE = \{(1,2)\} \cup \mE^\prime.
\end{equation*} In particular,  $(\forall i =1,2,3)\; d_i = 2$ and $d_i^+ = i-1$. In this case, the incidence matrix of the underlying tree $G^\prime$ is given by 
\begin{equation} \label{e:Ryu-incidence}
    Z = \begin{bmatrix}
        1 & 0  \\
        0 & 1 \\
        -1 & -1 \\
    \end{bmatrix},
\end{equation} which also defines an onto decomposition of the corresponding Laplacian, as in Section~\ref{s:MT}. In this manner, for $\theta \in \zeroun$ and $\gamma \in \RPP$, Ryu's iteration operator $T_{\theta,\gamma}: X^{N-1} \to X^{N-1}$ is given by 
\begin{equation} \label{e:Ryu-it-op-T}
  (\forall \bx \in X^{2})\;  T_{\theta,\gamma}(\bx) := \bx + \theta \begin{pmatrix}
        z_2 - z_1\\  z_3 - z_1
    \end{pmatrix},
\end{equation} where 
\begin{equation} \label{e:Ryu-it-op-z}
     \left\{\begin{aligned}
         z_1 &= J_{\gamma A_1}(x_1)& \\
         z_2 &= J_{\gamma A_2}(z_1 + x_2) \\
         z_3 &= J_{\gamma A_3}(z_1 - x_1 + z_2 - x_2).&
     \end{aligned}\right.
\end{equation} The expression for this operator is deduced from \eqref{e:graph-DR-T}--\eqref{e:graph-DR-z}, using \eqref{e:Ryu-incidence} and the change of variables $\gamma \leftarrow \tfrac{\gamma}{2}$ and $\bx \leftarrow \tfrac{1}{2}\bx$. Next, we obtain a \Qname for this operator.

\todo[inline]{write in general, but explain why only 3 operators is efficient}
\begin{proposition}[Fixed-point relocator for Ryu's iteration operator] \label{p:Ryu-FPR}
For $\gamma,\delta \in \RPP$, consider the operator $\tQ_{\delta\gets \gamma} = (\tQ_{\delta\gets \gamma}^1, \tQ_{\delta\gets \gamma}^{2}): X^{2} \to X^{2}$ defined by \begin{equation} \label{Q:3-op}
\left\{\begin{aligned}
 \tQ_{\delta\gets \gamma}^1(x_1,x_2) & = \left(\tfrac{\delta}{\gamma}\Id 
  +\big(1-\tfrac{\delta}{\gamma}\big)J_{\gamma A_1}\right)x_1  \\
\tQ_{\delta\gets \gamma}^2(x_1,x_2) & = \tfrac{\delta}{\gamma}x_2.\\
\end{aligned}\right.
\end{equation} Then, the family of operators $\{\tQ_{\delta\gets \gamma}\}_{\gamma, \delta \in \RPP}$ defines a \Qname~for  $\{T_{\theta,\gamma}\}_{\gamma\in\RPP}$ given by \eqref{e:Ryu-it-op-T}--\eqref{e:Ryu-it-op-z}.
\end{proposition}

\begin{proof}

In view of Proposition~\ref{p:Qname-graph-DR} and \eqref{e:system-Q}, $\{Q_{\delta\gets \gamma}\}_{\gamma, \delta \in \RPP}$ therein defines a \Qname, where for $\gamma,\delta \in \RPP$ and $\bx \in X^2$, $\by = Q_{\delta\gets \gamma}\bx$ solves the following system of equations: \begin{equation*}
    \left\{\begin{array}{rl}
         y_1 & = \tfrac{\delta}{\gamma}x_1 + \left(1-\tfrac{\delta}{\gamma}\right)\left(2z_1 - \tfrac{1}{3}(2z_1 - 2z_3)\right) \\
    y_2 & =  \tfrac{\delta}{\gamma}x_2 - \tfrac{1}{3}\left(1-\tfrac{\delta}{\gamma}\right)(2z_1 - 2z_3),
    \end{array}\right.
\end{equation*} with $z_1$ and $z_3$ given in \eqref{e:Ryu-it-op-z}. Since $(\forall \bx \in \Fix T_{\theta,\gamma})\; \tfrac{1}{3}(2z_1 - 2z_3) = \tfrac{1}{3}(d_1z_1 + \sum_{i=2}^3(d_i - 2d_i^+)z_i =0$ in view of Lemma~\ref{l:system-FPR}\ref{l:system-FPR-2} and Fact~\ref{f:graph-DR}\ref{f:graph-DR-degree}, using the aforementioned change of variables $\bx \leftarrow \tfrac{1}{2}\bx$, and $\by \leftarrow \tfrac{1}{2}\by$ yields $\by = \tQ_{\delta\gets \gamma}\bx$, and from Remark~\ref{r:FPR}, $\{\tQ_{\delta\gets \gamma}\}_{\gamma,\delta\in \RPP}$ satisfies Definition~\ref{d:Q-transport}\ref{a:trans_bijection}--\ref{a:trans_semigroup}. Moreover, $\tQ_{\delta\gets \gamma}$ is Lipschitz continuous. Indeed, $(\forall \bx,\bw \in X^{2})$ it follows from Proposition~\ref{p:Q} that \begin{equation*}
    \|\tQ_{\delta\gets \gamma}^1\bx - \tQ_{\delta\gets \gamma}^1\bw \| \leq \max\left\{1,\tfrac{\delta}{\gamma}\right\}\|x_1 - w_1\|.
\end{equation*} Furthermore, it directly follows that \begin{align*}
    \|\tQ_{\delta\gets \gamma}^2\bx - \tQ_{\delta\gets \gamma}^2\bw \| & \leq \tfrac{\delta}{\gamma} \|x_2 - w_2\| .
\end{align*} Hence, $\tQ_{\delta\gets \gamma}$ is Lipschitz continuous with constant \begin{equation} \label{e:Ryu-Lip}
    \tilde{\mL}_{\delta\gets \gamma} = \max\{1,\frac{\delta}{\gamma}\},
\end{equation} which concludes the proof.
 \end{proof}

Having defined a  \Qname~for Ryu's splitting method, we next present Algorithm~\ref{a:DR-3}, an efficient implementation of the relocated fixed-point iteration associated with the \Qname~in Proposition~\ref{p:Ryu-FPR} for Ryu's iteration operator \eqref{e:Ryu-it-op-T}-\eqref{e:Ryu-it-op-z}. The equivalence between the two can be proven similarly to Proposition~\ref{p:DR-N-reformulation}, and here we state the result for completeness. 


\begin{algorithm}[!ht]
\caption{Variable stepsize resolvent splitting  for finding a zero of $A_1+A_2+A_3$. \label{a:DR-3}}
\SetKwInOut{Input}{Input}
\Input{Choose $ x_{1,0}, x_{2,0} \in X$ and $\theta \in \zeroun$.}

Define $z_{1,0} = J_{\gamma_1 A_1}(x_{1,0})$.

\For{$n=0,1,\dots$}{
Step 1. Intermediate step. Compute \begin{equation*} %\label{e:intermediate-3}
    \bw_n = \bx_n + \theta \begin{pmatrix}
        z_{n}^2 - z_{n}^1\\  z_{3,n} - z_{n}^1
    \end{pmatrix}
\end{equation*} where $z_{n}^2, z_{3,n} \in X$ are given by \begin{equation*} 
     \left\{\begin{aligned}
         z_{n}^2 &= J_{\gamma_n A_2}(z_{n}^1 +  x_{2,n}) \\
         z_{3,n} &= J_{\gamma_n A_3}(z_{n}^1 - x_{1,n} + z_{n}^2 - x_{2,n}).&
     \end{aligned}\right.
\end{equation*}

Step 2. Next iterate. Compute
\begin{equation*} %\label{DR:variable-stepsize-3} 
    \begin{cases}
    z_{n+1}^1 & = J_{\gamma_n A_1}w_{n}^1 \\
    x_{n+1}^1 & = \dfrac{\gamma_{n+1}}{\gamma_n} w_{n}^1 + \left(1 - \dfrac{\gamma_{n+1}}{\gamma_n} \right) z_{n+1}^1\\
    x_{2,n+1} & = \dfrac{\gamma_{n+1}}{\gamma_n} w_{2,n}.
    \end{cases}
\end{equation*}
}
\end{algorithm}


\begin{proposition} \label{p:DR-3-reformulation}
    Given $\bx_0 =(x_{1,0}, x_{2,0}) \in X^2$, $\theta \in \zeroun$ and $(\gamma_n)_\nnn \subseteq \RPP$, the sequences $(\bx_n)_\nnn, (\bw_n)_\nnn \subseteq X^{2}$ and $ (\bz_n)_\nnn \subseteq X^{3}$ are generated by Algorithm~\ref{a:DR-3} if and only if $(\forall \nnn)$\begin{equation*} %\label{a:z-3-DR}
    \left\{\begin{aligned}
         z_{n}^1 &= J_{\gamma_n A_1}(x_{1,n})\\
         z_{n}^2 &= J_{\gamma_n A_2}(z_{n}^1 + x_{2,n}) \\
         z_{3,n} &= J_{\gamma_n A_3}(z_{n}^1 - x_{1,n} + z_{n}^2 - x_{2,n}).
     \end{aligned}\right.
\end{equation*} and \begin{equation*}
 \left\{\begin{aligned}
    \bw_n     &= T_{\theta,\gamma_n}\bx_n \\
    \bx_{n+1} &= \tQ_{\gamma_{n+1}\gets \gamma_n}\bw_n \\
   \end{aligned}\right. 
\end{equation*} where the operator $T_{\theta,\gamma}$ is defined in \eqref{e:Ryu-it-op-T}--\eqref{e:Ryu-it-op-z}, and $\tQ_{\beta\gets \alpha}: X^{2} \to X^{2}$ is defined in \eqref{Q:3-op}.
\end{proposition}



The convergence of Algorithm~\ref{a:DR-3}, stated in the following result, follows from Corollary~\ref{c:graph-DR-convergence}, \eqref{e:Ryu-Lip} and Lemma~\ref{l:stepsize-condition}.
%its interpretation as a fixed-point relocation iteration. 

\begin{corollary}[Convergence of variable stepsize Ryu's three-operator resolvent splitting algorithm]
Suppose that $A_1, A_2, A_3$ are  maximally monotone operators on $X$ 
such that $Z := \zer(A_1+A_2+A_3)\neq\varnothing$. Let  $\theta \in \zeroun$ and \begin{equation*}
%\label{a:stepsize-series-3}
    (\gamma_n)_\nnn \subseteq \Gamma \text{~be a sequence that 
converges to~} \overline{\gamma}\in \Gamma %\setminus \{0\}, 
\text{~and~}  \sum_\nnn (\gamma_{n+1}-\gamma_n)_+ < \pinf .
\end{equation*} 
Given $\bx_0  \in X^2$, generate the sequences $(\bx_n)_\nnn, (\bw_n)_\nnn \subseteq X^{2}$ and $ (\bz_n)_\nnn \subseteq X^{3}$ with Algorithm~\ref{a:DR-3}. Then, $(\bx_n)_\nnn$ 
converges weakly to some point $\bx \in \Fix T_{\theta,\overline{\gamma}}$, where $T_{\theta,\gamma}$ is the iteration operator defined in \eqref{e:Ryu-it-op-T}--\eqref{e:Ryu-it-op-z}, and 
$(\forall i = 1, 2,3)$ $(z_{in})_\nnn$ converges weakly to $J_{\overline{\gamma} A_1}x_1\in Z$.
\end{corollary}

}


