\section{Refined eigenvalue estimates  on product domains}
\hskip\parindent In this section, we prove refined eigenvalue estimates on product domains, Theorem \ref{pertubation-product-1d}  and its corollary,  Corollary \ref{first-k-dirichlet-1d}.
Recall that, if an open domain $\Omega$ is in the real line, then its eigenvalues have explicit lower bounds, which satisfy for $k\ge 1$
$$\lambda_k(\Omega)\ge \frac{\pi^2}{|\Omega|^2}k^2.$$
This allows us to show the following estimate for the Riesz means.
\begin{lem}\label{lem-riesz-dirichlet-n1}
 Let $\Omega\subset\rr$ be bounded. It holds that
\begin{align}\label{riesz-dirichlet-n1}
\sum_{k:\,\lambda_k(\Omega)<\lambda}(\lambda-\lambda_k)&\le
\frac{2|\Omega|}{3\pi} \lambda^{3/2} \min\left\{ \left(1 - \frac{3\pi}{16|\Omega|\sqrt\lambda} \right)_+,\,\left(1 - \left(\frac{\lfloor\frac{|\Omega|\sqrt{\lambda}}{\pi}\rfloor}{\frac{|\Omega|\sqrt{\lambda}}{\pi}}\right)^2\frac{3\pi}{4|\Omega|\sqrt\lambda} \right)\right\},
\end{align}
and for  $\lambda>\frac{\pi^2}{|\Omega|^2}$,
\begin{align}\label{riesz-dirichlet-n2}
\sum_{k:\,\lambda_k(\Omega)<\lambda}(\lambda-\lambda_k)^{1/2}&\le \frac{|\Omega|}{4}\lambda- \frac { \sqrt{\lambda}}{2 }+
  \frac{\sqrt 6\pi}{9|\Omega|} \sqrt{\lfloor\frac{|\Omega|}{\pi}\sqrt{\lambda}\rfloor+\frac 12}\le
 \frac {|\Omega|}{4} \lambda\left(1-\frac{2}{3} \frac{1}{|\Omega|\sqrt\lambda}\right).
 \end{align}
 Moreover, if $\Omega$ is a connected open interval, it holds for $\lambda>\lambda_1(\Omega)=\frac{\pi^2}{|\Omega|^2}$ that
 \begin{align}\label{riesz-dirichlet-n2-lower}
\sum_{k:\,\lambda_k(\Omega)<\lambda}(\lambda-\lambda_k)^{1/2}&\ge
 \frac{|\Omega|}{4}\lambda \left(1-\frac{2\pi}{|\Omega|\sqrt\lambda}+\frac{\pi^2}{|\Omega|^2\lambda}\right).
 \end{align}
\end{lem}
\begin{proof} Let us first prove \eqref{riesz-dirichlet-n1}.
If $\lambda\le \frac{\pi^2}{|\Omega|^2}$, then $\sum_{k:\,\lambda_k(\Omega)<\lambda}(\lambda-\lambda_k)=0$. Suppose $\lambda>\frac{\pi^2}{|\Omega|^2}$ and set $k_\lambda=\lfloor\frac{|\Omega|}{\pi}\sqrt{\lambda}\rfloor$. Then we have
\begin{align*}
\sum_{k:\,\lambda_k(\Omega)<\lambda}(\lambda-\lambda_k)&=\sum_{1\le k\le k_\lambda}(\lambda-\lambda_k)\le \sum_{1\le k\le k_\lambda}(\lambda-\frac{\pi^2}{|\Omega|^2}k^2)\\
&= \lambda k_\lambda - \frac{\pi^2}{|\Omega|^2}\frac 16 k_\lambda \left(k_\lambda+1\right) \left(2k_\lambda+1\right) \\
&= \lambda k_\lambda- \frac{\pi^2}{3|\Omega|^2} k_\lambda^3 - \frac{\pi^2}{2|\Omega|^2}k_\lambda^2
-\frac{\pi^2}{6|\Omega|^2}k_\lambda.
\end{align*}
Since
\begin{align*}
\lambda k_\lambda- \frac{\pi^2}{3|\Omega|^2} k_\lambda^3\le  \frac{2|\Omega|}{3\pi}\lambda^3,
\end{align*}
we see that
\begin{align*}
\sum_{k:\,\lambda_k(\Omega)<\lambda}(\lambda-\lambda_k)&<  \frac{2|\Omega|}{3\pi}\lambda^3- \frac{\pi^2}{2|\Omega|^2}\left(\frac{k_\lambda }{\frac{|\Omega|}{\pi}\sqrt{\lambda}}\right)^2  \frac{|\Omega|^2}{\pi^2}\lambda
= \frac{2|\Omega|}{3\pi}\lambda^3- \left(\frac{k_\lambda}{\frac{|\Omega|}{\pi}\sqrt{\lambda}}\right)^2 \frac{\lambda}{2}.
\end{align*}
For $\lambda>\frac{\pi^2}{|\Omega|^2}$, $\frac{k_\lambda}{\frac{|\Omega|}{\pi}\sqrt{\lambda}}\ge 1/2$, so we also have
\begin{align*}
\sum_{k:\,\lambda_k(\Omega)<\lambda}(\lambda-\lambda_k)&< \frac{2|\Omega|}{3\pi}\lambda^3-  \frac{\lambda}{8}.
\end{align*}


Let us prove \eqref{riesz-dirichlet-n2}. Again we only need to consider $\lambda>\frac{\pi^2}{|\Omega|^2}$. Set $k_\lambda=\lfloor\frac{|\Omega|}{\pi}\sqrt{\lambda}\rfloor$. Note that
\begin{align*}
\sum_{k:\,\lambda_k(\Omega)<\lambda}(\lambda-\lambda_k)^{1/2}&\le \sum_{1\le k\le k_\lambda}(\lambda-\frac{\pi^2}{|\Omega|^2}k^2)^{1/2}=\frac{\pi}{|\Omega|}\sum_{1\le k\le k_\lambda}(\frac{|\Omega|^2}{\pi^2}\lambda-k^2)^{1/2}.
\end{align*}
Let us consider the ball $B(0,\frac{|\Omega|}{\pi}\sqrt{\lambda})$ in the first quadrant in $\rr^2$.
For each $1\le k\le k_\lambda=\lfloor\frac{|\Omega|}{\pi}\sqrt{\lambda}\rfloor$, $(\frac{|\Omega|^2}{\pi^2}\lambda-k^2)^{1/2}$
equals the area of the rectangle $[k-1,k]\times [0, (\frac{|\Omega|^2}{\pi^2}\lambda-k^2)^{1/2}]$, which is contained in $B(0,\frac{|\Omega|}{\pi}\sqrt{\lambda})$ in the first quadrant in $\rr^2$.
Moreover, for each $k$, there is at least a triangle with vertices at $(k-1, (\frac{|\Omega|^2}{\pi^2}\lambda-(k-1)^2)^{1/2})$,
$(k-1, (\frac{|\Omega|^2}{\pi^2}\lambda-k^2)^{1/2})$ and $(k, (\frac{|\Omega|^2}{\pi^2}\lambda-k^2)^{1/2})$
contained in the ball. Moreover, if $k_\lambda\neq\frac{|\Omega|}{\pi}\sqrt{\lambda} $, there is another triangle insider the 1/4 ball
with vertices at  $(k_\lambda, (\frac{|\Omega|^2}{\pi^2}\lambda-k_\lambda^2)^{1/2})$,
$(k_\lambda, (\frac{|\Omega|^2}{\pi^2}\lambda-k_\lambda^2)^{1/2})$ and $(\frac{|\Omega|}{\pi}\sqrt{\lambda},0)$. See Figure \ref{fig2}\footnote[1]{Picture drawn by Xinyi Jiang.}.
\begin{figure}[htbp]
\centering
\includegraphics[scale=0.2]{rect-triangle.jpg}
\caption{The 1/2 sum is controlled by the 1/4 ball}
\label{fig2}
\end{figure}
We therefore see that
\begin{align*}
\frac {\pi}{4}\frac{|\Omega|^2}{\pi^2}\lambda&> \sum_{1\le k\le k_\lambda}(\frac{|\Omega|^2}{\pi^2}\lambda-k^2)^{1/2}+\frac 12\sum_{1\le k\le k_\lambda} 1\times \left((\frac{|\Omega|^2}{\pi^2}\lambda-(k-1)^2)^{1/2}-(\frac{|\Omega|^2}{\pi^2}\lambda-k^2)^{1/2}\right)\\
&\quad+ \frac 12 \left(\frac{|\Omega|}{\pi}\sqrt{\lambda}-k_\lambda\right)\times (\frac{|\Omega|^2}{\pi^2}\lambda-k_\lambda^2)^{1/2}\\
&=\sum_{1\le k\le k_\lambda}(\frac{|\Omega|^2}{\pi^2}\lambda-k^2)^{1/2}+\frac 12 \left((\frac{|\Omega|^2}{\pi^2}\lambda)^{1/2}-(\frac{|\Omega|^2}{\pi^2}\lambda-k_\lambda^2)^{1/2}+\left(\frac{|\Omega|}{\pi}\sqrt{\lambda}-k_\lambda\right)\times (\frac{|\Omega|^2}{\pi^2}\lambda-k_\lambda^2)^{1/2}\right).
\end{align*}
For $x\in [0,1)$, let us consider the function
$$g(x):=k_\lambda+x- \left((k_\lambda+x)^2-k_\lambda^2\right)^{1/2}(1-x).$$
A calculation shows that for $k_\lambda\in\cn$, it holds
\begin{align*}
g(x)&= k_\lambda+x -\left(2k_\lambda x+x^2\right)^{1/2}(1-x)\\
&\ge k_\lambda+x-\sqrt{2k_\lambda+1}\sqrt{x}(1-x)\\
&\ge k_\lambda+x-\frac{2\sqrt 3}{9} \sqrt{2k_\lambda+1}\\
&\ge k_\lambda+x-\frac{2}{3}k_\lambda\\
&\ge \frac{k_\lambda+x}{3}.
\end{align*}
This implies that
\begin{align*}
\frac {\pi}{4}\frac{|\Omega|^2}{\pi^2}\lambda&> \sum_{1\le k\le k_\lambda}(\frac{|\Omega|^2}{\pi^2}\lambda-k^2)^{1/2}+
\frac{1}{2}\frac{|\Omega|}{\pi}\sqrt{\lambda}-\frac{\sqrt 6}{9} \sqrt{\lfloor\frac{|\Omega|}{\pi}\sqrt{\lambda}\rfloor+\frac 12}\\
&\ge  \sum_{1\le k\le k_\lambda}(\frac{|\Omega|^2}{\pi^2}\lambda-k^2)^{1/2} +\frac{1}{6}\frac{|\Omega|}{\pi}\sqrt{\lambda},
\end{align*}
i.e.,
\begin{align*}
 \frac{\pi}{|\Omega|}\sum_{1\le k\le k_\lambda}(\frac{|\Omega|^2}{\pi^2}\lambda-k^2)^{1/2}< \frac{|\Omega|}{4}\lambda- \frac { \sqrt{\lambda}}{2 }+
  \frac{\sqrt 6\pi}{9|\Omega|} \sqrt{\lfloor\frac{|\Omega|}{\pi}\sqrt{\lambda}\rfloor+\frac 12}=
 \frac {|\Omega|}{4} \lambda\left(1-\frac{2}{3} \frac{1}{|\Omega|\sqrt\lambda}\right).
\end{align*}

Let us prove \eqref{riesz-dirichlet-n2-lower}. Since $\Omega$ is connected, we have
$$\lambda_k(\Omega)=\frac{k^2\pi^2}{|\Omega|^2},\,\forall \ k\in\cn. $$
Set again $k_\lambda=\lfloor\frac{|\Omega|}{\pi}\sqrt{\lambda}\rfloor$. For $\lambda>\frac{\pi^2}{|\Omega|^2}$, we have
\begin{align*}
\sum_{k:\,\lambda_k(\Omega)<\lambda}(\lambda-\lambda_k)^{1/2}&= \sum_{1\le k\le k_\lambda}(\lambda-\frac{\pi^2}{|\Omega|^2}k^2)^{1/2}=\frac{\pi}{|\Omega|}\sum_{1\le k\le k_\lambda}(\frac{|\Omega|^2}{\pi^2}\lambda-k^2)^{1/2}.
\end{align*}
Note that the union of the rectangles $[k-1,k]\times [0, (\frac{|\Omega|^2}{\pi^2}\lambda-k^2)^{1/2}]$, $1\le k\le k_\lambda$, contains the ball
$B(0,\sqrt{\frac{|\Omega|^2}{\pi^2}\lambda-2\sqrt{\frac{|\Omega|^2}{\pi^2}\lambda}+1}) $ intersecting the first quadrant, since
\begin{align*}
\sqrt{(k-1)^2+ (\frac{|\Omega|^2}{\pi^2}\lambda-k^2)}&=\sqrt{\frac{|\Omega|^2}{\pi^2}\lambda-2k+1}\ge \sqrt{\frac{|\Omega|^2}{\pi^2}\lambda-2k_\lambda+1}\\
&\ge  \sqrt{\frac{|\Omega|^2}{\pi^2}\lambda-2\sqrt{\frac{|\Omega|^2}{\pi^2}\lambda}+1}.
\end{align*}
We therefore deduce that
\begin{align*}
\sum_{k:\,\lambda_k(\Omega)<\lambda}(\lambda-\lambda_k)^{1/2}&\ge \frac{\pi}{4}\frac{\pi}{|\Omega|} \left(\frac{|\Omega|^2}{\pi^2}\lambda-2\sqrt{\frac{|\Omega|^2}{\pi^2}\lambda}+1\right)\\
&= \frac{|\Omega|}{4}\lambda \left(1-\frac{2\pi}{|\Omega|\sqrt\lambda}+\frac{\pi^2}{|\Omega|^2\lambda}\right).
\end{align*}
The proof is complete.
\end{proof}


\begin{lem}\label{lem-1d}
Let $\Omega\subset\rr$ be an open bounded set. Then for $p>1$ and $\lambda>\lambda_1=\lambda_1(\Omega)$, it holds that
\begin{align*}
\sum_{k:\,\lambda_k<\lambda } (\lambda-\lambda_k)^{p}
&\le  \frac{2|\Omega|}{3\pi\mathscr{B}(p-1,2)}  \lambda^{p+\frac{1}{2}} \mathscr{B}(p-1,5/2)- C_3(p)\lambda^p,
\end{align*}
where
\begin{align}\label{defn-c3n}
C_3(p)=
\begin{cases}
\frac 18,& p=1,\\
\frac 19, & 1<p\le 2,\\
\frac{1}{8 }\left(\frac{247}{256}\right)^{p-1}, & p>2.
\end{cases}
\end{align}
\end{lem}
\begin{proof}
By the semigroup type property of the Riesz means and \eqref{riesz-dirichlet-n1}, we have
\begin{align}
\sum_{k:\,\lambda_k<\lambda } (\lambda-\lambda_k)^{p}
&\le \mathscr{B}(p-1,2)^{-1} \sum_{k}  \int_0^\infty v^{p-2}(\lambda-\lambda_k-v)_+\,dv \nonumber\\
&\le  \frac{2|\Omega|}{3\pi\mathscr{B}(p-1,2)} \int_0^\infty v^{p-2} (\lambda-v)_+^{3/2}\left(1 - \frac{3\pi}{16|\Omega|\sqrt{(\lambda-v)_+}} \right)_+\,dv\nonumber\\
&\le \frac{2|\Omega|}{3\pi\mathscr{B}(p-1,2)}  \lambda^{p+\frac{1}{2}} \mathscr{B}(p-1,5/2)- \frac{1}{8\mathscr{B}(p-1,2)}    \int_0^{\lambda-\frac{9\pi^2}{256|\Omega|^2}} v^{p-2} (\lambda-v)_+\,dv.
\end{align}
Noticing  that
$\lambda_1(\Omega)\ge \frac{\pi^2}{|\Omega|^2},$
so for $\lambda>\lambda_1(\Omega)$,
$$\lambda-\frac{9\pi^2}{256|\Omega|^2}\ge \frac{247}{256}\lambda.$$
For $1<p\le 2$,
\begin{align}
\frac{1}{8\mathscr{B}(p-1,2)}  \int_0^{\lambda-\frac{9\pi^2}{256|\Omega|^2}} v^{p-2} (\lambda-v)_+\,dv\ge \frac{\lambda^p}{8\mathscr{B}(p-1,2)}  \frac{249}{256} \mathscr{B}(p-1,2)\ge  \frac{\lambda^p}{9}.
\end{align}
For $p>2$, we have
\begin{align*}
  \int_{\lambda-\frac{9\pi^2}{256|\Omega|^2}}^\lambda v^{p-2} (\lambda-v)_+\,dv &= \frac{\lambda^p}{p-1}- \frac{\lambda^p}{p}-\left(\frac{\lambda (\lambda-\frac{9\pi^2}{256|\Omega|^2})^{p-1}}{p-1}-\frac{(\lambda-\frac{9\pi^2}{256|\Omega|^2})^p}{p} \right)\\
&=\frac{\lambda^p}{p(p-1)}- \left(\lambda-\frac{9\pi^2}{256|\Omega|^2}\right)^{p-1} \left(\frac{\lambda}{p-1}-\frac{(\lambda-\frac{9\pi^2}{256|\Omega|^2})}{p} \right)\\
&\le \frac{\lambda^p}{p(p-1)} -\left(\lambda-\frac{9\pi^2}{256|\Omega|^2}\right)^{p-1} \frac{\lambda }{p(p-1)}
\end{align*}
and therefore
\begin{align*}
&\frac{1}{8\mathscr{B}(p-1,2)}    \int_0^{\lambda-\frac{9\pi^2}{256|\Omega|^2}} v^{p-2} (\lambda-v)_+\,dv\\
&= \frac{1}{8\mathscr{B}(p-1,2)}   \left( \int_0^{\lambda} v^{p-2} (\lambda-v)_+\,dv- \int_{\lambda-\frac{9\pi^2}{256|\Omega|^2}}^\lambda v^{p-2} (\lambda-v)_+\,dv\right)\\
&\ge \frac{1}{8\mathscr{B}(p-1,2)} \left(\lambda-\frac{9\pi^2}{256|\Omega|^2}\right)^{p-1} \frac{\lambda }{p(p-1)}\\
&\ge \frac{\lambda^p}{8 }\left(\frac{247}{256}\right)^{p-1}.
\end{align*}
Combining the above estimates yields the desired conclusion.
\end{proof}


In view of Laptev's beautiful theory on product domains \cite{La97} (which has been further employed in Laptev-Weidl \cite{LW00} for Schr\"odinger operator), the Aizenman-Lieb principle \cite{AiLi78},
we have the following
refined  eigenvalue estimates on product domains if one domain satisfies P\'olya's conjecture. Note that any bounded domain $\Omega\subset\rr$ satisfies P\'olya's conjecture, i.e.,
$\lambda_k(\Omega)\ge \frac{\pi^2}{|\Omega|^2}k^2$ for each $k\in\cn$.
\begin{thm}\label{pertubation-product-1d}
Let $\Omega_1\subset\rr^{n_1}$ and $\Omega_2\subset\rr$ be bounded open domains, $n_1\ge 1$ and $n=n_1+1$. Suppose that
P\'olya's conjecture holds on $\Omega_1$. Then it holds for $\lambda>0$ that
\begin{align*}
\mathcal{N}^D_{\Omega_1\times\Omega_2}(\lambda)&\le  \frac{|\Omega_1||\Omega_2|\omega(n)}{(2\pi)^n}\lambda^{n/2}\left(1- \frac{C_1(n_1)}{|\Omega_2|\sqrt{\lambda}}\right)_+,
\end{align*}
where $C_1(n_1)$ is as in \eqref{defn-c1n},
\begin{align}
C_1(n_1)=\begin{cases}
\frac 23 & n_1=1,\\
\frac{3\pi}{16} & n_1=2,\\
\frac{\pi\mathscr{B}(\frac{n_1}{2}-1,2)}{6\mathscr{B}(\frac{n_1}{2}-1,5/2)} & n_1=3,4,\\
\frac{3\pi\mathscr{B}(\frac{n_1 }{2}-1,2)}{16 \mathscr{B}(\frac{n_1 }{2}-1,5/2)}\left(\frac{247}{256}\right)^{\frac{n_1-2}{2}}  &  n_1\ge 5.
\end{cases}
\end{align}
\end{thm}
\begin{proof}
 Suppose that it holds that
$$\mathcal{N}^D_{\Omega_1}(\lambda)=\#\{\lambda_k(\Omega_1):\,\lambda_k(\Omega_1)<\lambda\}\le \frac{|\Omega_1|\omega(n_1)}{(2\pi)^{n_1}} \lambda^{n/2}.$$
Then for all $\lambda>\lambda_1(\Omega)$, where
\begin{align}
\lambda_1(\Omega)=\lambda_1(\Omega_1)+\lambda_1(\Omega_2)\ge  \frac{(2\pi)^2}{|\Omega_1|^{2/n}\omega(n_1)^{2/n_1}}+ \frac{\pi^2}{|\Omega_2|^{2}},
\end{align}
we have
\begin{align*}
\mathcal{N}^D_{\Omega}(\lambda)&=\sum_{j:\,\lambda_j(\Omega_2)<\lambda }\#\left\{k:\,\lambda_k(\Omega_1)+\lambda_j(\Omega_2)<\lambda\right\}
=\sum_{j:\,\lambda_j(\Omega_2)<\lambda } \#\left\{k:\,\lambda_k(\Omega_1)<(\lambda -\lambda_j(\Omega_2))_+\right\}\\
&\le \sum_{j:\,\lambda_j(\Omega_2)<\lambda } \frac{|\Omega_1|\omega(n_1)}{(2\pi)^{n_1}} (\lambda-\lambda_j(\Omega_2))^{n_1/2}.
\end{align*}
If $n_1=1$, then by \eqref{riesz-dirichlet-n2}, we have
\begin{align*}
\mathcal{N}^D_{\Omega}(\lambda)&\le \sum_{j:\,\lambda_j(\Omega_2)<\lambda } \frac{|\Omega_1|}{\pi} (\lambda-\lambda_j(\Omega_2))^{1/2}\le  \frac{|\Omega_1||\Omega_2|}{4\pi} \lambda  \left(1- \frac{2}{3|\Omega_2|\sqrt\lambda}\right)_+.
\end{align*}
If $n_1=2$, then by \eqref{riesz-dirichlet-n1} we have
\begin{align*}
\mathcal{N}^D_{\Omega}(\lambda)&\le \sum_{j:\,\lambda_j(\Omega_2)<\lambda } \frac{|\Omega_1|\omega(2)}{(2\pi)^{2}} (\lambda-\lambda_j(\Omega_2))\le \frac{|\Omega_1|\omega(2)}{(2\pi)^{2}}\frac{2|\Omega_2|}{3\pi}\lambda^{3/2}\left(1 - \frac{3\pi}{16|\Omega_2|\sqrt\lambda} \right)_+\\
&=\frac{|\Omega|\omega(3)}{(2\pi)^{3}}\lambda^{3/2}\left(1 - \frac{3\pi}{16|\Omega_2|\sqrt\lambda} \right)_+.
\end{align*}
For  $n_1\ge 3$,  by Lemma \ref{lem-1d}, we see that
\begin{align*}
\mathcal{N}^D_{\Omega}(\lambda)&\le \sum_{j:\,\lambda_j(\Omega_2)<\lambda } \frac{|\Omega_1|\omega(n_1)}{(2\pi)^{n_1}} (\lambda-\lambda_j(\Omega_2))^{n_1/2}\\
&\le \frac{|\Omega_1|\omega(n_1)}{(2\pi)^{n_1}}\left(\frac{2|\Omega_2|}{3\pi\mathscr{B}(\frac{n_1}{2}-1,2)}  \lambda^{\frac{n_1}2+\frac{1}{2}} \mathscr{B}(\frac{n_1}{2}-1,5/2)- C_3(\frac{n_1}{2})\lambda^{\frac{n_1}{2}}\right)_+\\
&=\frac{|\Omega_1||\Omega_2|\omega(n)}{(2\pi)^{n_1+1}} \lambda^{\frac{n_1}{2}+1}\left(1-\frac{3\pi\mathscr{B}(\frac{n_1}{2}-1,2)}{2\mathscr{B}(\frac{n_1}{2}-1,5/2)}\frac{C_3(\frac{n_1}{2})}{|\Omega_2| \sqrt\lambda}\right)_+\\
&=\frac{|\Omega_1||\Omega_2|\omega(n)}{(2\pi)^{n_1+1}} \lambda^{\frac{n_1}{2}+1}\left(1-\frac{C_1(n_1)}{|\Omega_2| \sqrt\lambda}\right)_+.
 \end{align*}
The proof is complete.
\end{proof}

As a corollary,  we have the following result.
\begin{cor}\label{first-k-dirichlet-1d}
Let $\Omega_1\subset\rr^{n_1}$ and $\Omega_2\subset\rr$ be bounded open domains, $n_1\ge 1$ and $n=n_1+1$. Suppose that
P\'olya's conjecture holds on $\Omega_1$. Let $\Omega$ be an open set contained in $\Omega_1\times\Omega_2$, and
$$k_0=\left\lfloor\frac{|\Omega|\omega(n)}{(2\pi)^n}\left[\left(1-\frac{|\Omega|}{|\Omega_1||\Omega_2|}\right)^{-1}\frac{C_1(n_1)}{|\Omega_2|}\right]^{n}\right\rfloor.$$
Then for each $1\le k\le k_0$,  the P\'olya conjecture holds on $\Omega$ for $\lambda_k(\Omega)$, i.e.,
$$k\le \frac{|\Omega|\omega(n)}{(2\pi)^n}\lambda_{k}(\Omega)^{n/2}.$$
\end{cor}
\begin{proof}
Since $\Omega\subset\Omega_1\times\Omega_2$, we may assume that $|\Omega|<|\Omega_1||\Omega_2|$, otherwise $|\Omega|=|\Omega_1||\Omega_2|$ and the P\'olya conjecture holds
for all Dirichlet eigenvalues of $\Omega$.
Fix $\lambda_0>0$ such that
$$|\Omega|= |\Omega_1||\Omega_2| \left(1-\frac{C_1(n_1)}{|\Omega_2| \sqrt\lambda_0}\right).$$
By the monotonicity of Dirichlet eigenvalues, for $\lambda<\lambda_0$ we have
\begin{align}\label{3.11}
\mathcal{N}^D_{\Omega}(\lambda)&\le \mathcal{N}^D_{\Omega_1\times\Omega_2}(\lambda)\le \frac{|\Omega_1||\Omega_2|\omega(n)}{(2\pi)^n}\lambda^{n/2}\left(1-\frac{C_1(n_1)}{|\Omega_2| \sqrt\lambda}\right)\nonumber\\
&\le \frac{|\Omega|\omega(n)}{(2\pi)^n}\lambda^{n/2}.
\end{align}


Recall that
$$k_0=\left\lfloor\frac{|\Omega|\omega(n)}{(2\pi)^n}\left[\left(1-\frac{|\Omega|}{|\Omega_1||\Omega_2|}\right)^{-1}\frac{C_1(n_1)}{|\Omega_2|}\right]^{n}\right\rfloor\le \frac{|\Omega|\omega(n)}{(2\pi)^n}\lambda_0^{n/2}.$$
Let $1\le k\le k_0$. If $\lambda_{k}(\Omega)<\lambda_0$, then \eqref{3.11} gives that for small enough $\epsilon>0$ such that $\lambda_{k}(\Omega)+\epsilon<\lambda_0$
\begin{align*}
k\le \mathcal{N}^D_{\Omega}(\lambda_{k}(\Omega)+\epsilon)&\le \frac{|\Omega|\omega(n)}{(2\pi)^n}(\lambda_{k}(\Omega)+\epsilon)^{n/2}.
\end{align*}
Letting $\epsilon\to 0$ gives that
\begin{align*}
k\le \frac{|\Omega|\omega(n)}{(2\pi)^n}\lambda_{k}(\Omega)^{n/2}.
\end{align*}
If $\lambda_{k}(\Omega)\ge \lambda_0$, then by the choose of $k_0$, we see that
\begin{align*}
k\le k_0\le \frac{|\Omega|\omega(n)}{(2\pi)^n}\lambda_0^{n/2}\le \frac{|\Omega|\omega(n)}{(2\pi)^n}\lambda_k(\Omega)^{n/2}.
\end{align*}
 The proof is complete.
 \end{proof}

Let us consider $\Omega_1\subset\rr^2$, with $|\Omega_1|=100$, $\Omega_2\subset\rr$ with $|\Omega_2|=1$.
Suppose that P\'olya's conjecture holds on $\Omega_1$ for the Dirichlet eigenvalues.
In this case, $C_1(2)=3\pi/16$,
\begin{align*}
\frac{|\Omega|\omega(n)}{(2\pi)^n}\left[\left(1-\frac{|\Omega|}{|\Omega_1||\Omega_2|}\right)^{-1}\frac{C_1(n_1)}{|\Omega_2|}\right]^{n}\ge \frac{|\Omega| 9\pi}{2^{13}} \left(1-\frac{|\Omega|}{100}\right)^{-3}.
\end{align*}
For any $\Omega\subset \Omega_1\times\Omega_2$, if $|\Omega|\ge 95$, then
$$\frac{|\Omega| 9\pi}{2^{13}} \left(1-\frac{|\Omega|}{100}\right)^{-3}\ge 2623,$$
and at least the first 2623 Dirichlet eigenvalues of $\Omega$ satisfy P\'olya's conjecture. If $|\Omega|\ge 99$ (resp. $|\Omega|\ge 80$), then at least the first 341694 (resp. 34) Dirichlet eigenvalues satisfy P\'olya's conjecture.



