\section{P\'olya's conjecture on a class of domains}\hskip\parindent
Let us start with proving the  qualitative result regarding removing general piecewise smooth set.

\begin{thm}\label{qualitative-polya}
Suppose that $\Omega_1\subset\rr^{n-1}$ satisfies P\'olya's conjecture, $n\ge 2$, $\Omega_2$ is an interval in $\rr$ and
$\Omega_3$ is a piecewise smooth domain contained in $\Omega_1\times\Omega_2$.
There exists $C_P=C(\Omega_3,n)$ such that if $|\Omega_1|\ge C_P$ then the P\'olya conjecture holds on $\Omega_1\times\Omega_2\setminus\overline{\Omega_3}$.
\end{thm}
\begin{proof}
Let $\Omega=\Omega_1\times\Omega_2\setminus\overline{\Omega_3}$.
Up to a scaling, we may assume that $|\Omega_3|=1$. It follows from Seeley \cite{Seeley78,Seeley80} (see also \cite[Corollary 17.5.11 \& (17.5.16)']{Hormander3}) that
for some $\Lambda>0$, it holds for $\lambda>\Lambda$ that
\begin{align}\label{seeley}
\left|\mathcal{N}^D_{\Omega_3}(\lambda)- \frac{|\Omega_3|\omega(n)}{(2\pi)^{n}} \lambda^{n/2}\right|\le C(\Omega_3)\lambda^{\frac{n-1}{2}}.
\end{align}
We assume that
$$|\Omega_1|> \max\left\{\frac{C(\Omega_3)(2\pi)^n}{\omega(n)C_1(n-1)},\frac{\sqrt{2\Lambda}}{C_1(n-1)}\right\}. $$


By Corollary \ref{first-k-dirichlet-1d}, P\'olya's conjecture holds for the first $k_0$ Dirichlet eigenvalues, where
$$k_0=\left\lfloor \frac{|\Omega|\omega(n)}{(2\pi)^n}\left[\left(1-\frac{|\Omega|}{|\Omega_1||\Omega_2|}\right)^{-1}\frac{C_1(n-1)}{|\Omega_2|}\right]^{n}\right\rfloor=
\left\lfloor \frac{|\Omega|\omega(n)}{(2\pi)^n}(C_1(n-1)|\Omega_1|)^{n}\right\rfloor.$$
It holds
$$\lambda_{k_0}(\Omega)^{n/2}\ge \frac{(2\pi)^n} {|\Omega|\omega(n)}\left\lfloor \frac{|\Omega|\omega(n)}{(2\pi)^n}(C_1(n-1)|\Omega_1|)^{n}\right\rfloor\ge \frac 12 (C_1(n-1)|\Omega_1|)^{n},$$
and hence,
$$\lambda_{k_0}(\Omega)\ge  \frac 12 (C_1(n-1)|\Omega_1|)^{2}. $$

Since $|\Omega_1|>\sqrt{2\Lambda}/C_1(n-1)$, it holds that
$$\lambda_{k_0}(\Omega)>\Lambda. $$
By \eqref{seeley} and $|\Omega_3|=1$, we see that for any $\lambda_k(\Omega)\ge \lambda_{k_0}(\Omega)$,
\begin{align*}
\mathcal{N}^D_{\Omega_3}(\lambda_k(\Omega))\ge  \frac{\omega(n)}{(2\pi)^{n}} \lambda_k(\Omega)^{n/2}- C(\Omega_3)\lambda_k(\Omega)^{\frac{n-1}{2}}.
\end{align*}
This implies on $\Omega_3$, there are   $\mathcal{N}^D_{\Omega_3}(\lambda_k(\Omega))$ eigenvalues smaller than $\lambda_k(\Omega)$. Since $\Omega$ and $\Omega_3$ are disjoint,
$\lambda_k(\Omega)$ corresponds to some $\lambda_{k+\tilde k}(\Omega\cup\Omega_3)$ for some
$$\tilde k\ge \mathcal{N}^D_{\Omega_3}(\lambda_k(\Omega))\ge \frac{ \omega(n)}{(2\pi)^{n}} \lambda_k(\Omega)^{n/2}- C(\Omega_3)\lambda_k(\Omega)^{\frac{n-1}{2}}.$$

Since $\Omega\cup\Omega_3\subset\Omega_1\times\Omega_2$ and $|\Omega\cup\Omega_3|=|\Omega_1\times\Omega_2|$, the monotonicity of Dirichlet eigenvalues together with
Theorem \ref{pertubation-product-1d} implies that
\begin{align*}
\mathcal{N}^D_{\Omega\cup \Omega_3}(\lambda)\le \mathcal{N}^D_{\Omega_1\times\Omega_2}(\lambda)&\le  \frac{|\Omega_1||\Omega_2|\omega(n)}{(2\pi)^n}\lambda^{n/2}\left(1- \frac{C_1(n-1)}{|\Omega_2|\sqrt{\lambda}}\right)_+,
\end{align*}
and therefore
\begin{align*}
 \frac{|\Omega_1||\Omega_2|\omega(n)}{(2\pi)^n}\lambda_k(\Omega)^{n/2}& =\frac{|\Omega_1||\Omega_2|\omega(n)}{(2\pi)^n}\lambda_{k+\tilde k}(\Omega\cup\Omega_3)^{n/2}\\
 &\ge k+\tilde k+ \frac{C_1(n-1)}{|\Omega_2|\sqrt{\lambda}}  \frac{|\Omega_1||\Omega_2|\omega(n)}{(2\pi)^n}\lambda_k(\Omega)^{\frac{n-1}{2}}\\
 &\ge k+\frac{ \omega(n)}{(2\pi)^{n}} \lambda_k(\Omega)^{n/2}- C(\Omega_3)\lambda_k(\Omega)^{\frac{n-1}{2}}+  \frac{C_1(n-1)|\Omega_1|\omega(n)}{(2\pi)^n}\lambda_k(\Omega)^{\frac{n-1}{2}}.
\end{align*}
Since $|\Omega_1|\ge \frac{C(\Omega_3)(2\pi)^n}{\omega(n)C_1(n-1)}$, we finally see that
\begin{align*}
 \frac{|\Omega|\omega(n)}{(2\pi)^n}\lambda_k(\Omega)^{n/2}& =\frac{|\Omega_1||\Omega_2|\omega(n)}{(2\pi)^n}\lambda_k(\Omega)^{n/2}-\frac{\omega(n)}{(2\pi)^n}\lambda_k(\Omega)^{n/2} \\
 &\ge k+  \lambda_k(\Omega)^{\frac{n-1}{2}}\left(\frac{C_1(n-1)|\Omega_1|\omega(n)}{(2\pi)^n}- C(\Omega_3)\right)\\
 &\ge k.
\end{align*}
The proof is complete.
\end{proof}



We next prove the concrete examples of domains obtained by removing cubes, Theorem \ref{polya-rectangle-minus}.
Let us start with the two dimensional case.

\subsection{The case of two dimension}
\hskip\parindent
Let $Q\subset\rr^n$ be an open unit cube, $n=2$.  Then the Dirichlet eigenvalues of $Q$ has the form
$$\left\{\lambda_k:\, \lambda_k=\pi^2(a^2+b^2),\,a,b\in\mathbb{N}\right\}.$$
Note that for a given $\lambda_k$,
$\mathcal{N}_Q^D(\lambda_k)$ is dominated by the number of unit cubes contained in the first quadrant intersecting the ball
$B(0, \sqrt{\lambda_k/\pi})$.


So it is readily to see that for all $k\in\cn$ that
$ \lambda_k \ge 4\pi k.$
In fact Theorem \ref{pertubation-product-1d} gives a better result.
We however shall need the opposite estimates.

\begin{lem}\label{opposite-cube}
 Let $Q\subset\rr^2$ be a cube with side length $\ell(Q)$ in $\rr^2$.

(i) For any $\lambda>2\pi^2/\ell(Q)^2$, it holds that
$$\mathcal{N}_Q^D(\lambda)\ge    \frac{\ell(Q)^2}{4\pi}\lambda- \frac{\omega(2)2^{3/2}\pi\ell(Q)}{(2\pi)^2}\sqrt\lambda +\frac{\pi}{2}.$$

(ii) For any $\lambda>0$,  it holds that
$$\mathcal{N}_Q^D(\lambda)\ge    \frac{\ell(Q)^2}{4\pi}\lambda- \frac{\omega(2)2^{3/2}\pi\ell(Q)}{(2\pi)^2}\sqrt\lambda.$$
 \end{lem}
\begin{proof}
We have
\begin{align*}
\mathcal{N}_Q^D(\lambda)&=\#\left\{\lambda_k<\lambda:\, \lambda_k=\frac{\pi^2}{\ell(Q)^2}(a^2+b^2),\,a,b\in\mathbb{N}\right\}.
\end{align*}
So the number $\mathcal{N}_Q^D(\lambda)$ is not less than the number of the unit cubes contained
in the first quadrant intersecting the ball
$B(0, \ell(Q)\sqrt{\lambda}/\pi-\sqrt 2)$, where $\sqrt 2$ is the diameter of the unit cube.
This implies that for any $\lambda>2\pi^2/\ell(Q)^2$,
\begin{align*}
\mathcal{N}_Q^D(\lambda)&\ge \frac 14 |B(0,\ell(Q)\sqrt{\lambda}/\pi-\sqrt 2 )| =\frac{\pi}{4} \left(\ell(Q)\sqrt{\lambda}/\pi-\sqrt 2 \right)^2\\
&\ge \frac{\ell(Q)^2}{4\pi}\lambda- \frac{\sqrt 2\ell(Q)}{2}\sqrt\lambda +\frac{\pi}{2}.
\end{align*}

Note that for $\lambda\le 2\pi^2/\ell(Q)^2$,
$$\frac{\ell(Q)^2}{4\pi}\lambda- \frac{\sqrt 2\ell(Q)}{2}\sqrt\lambda<0<\mathcal{N}_Q^D(\lambda),$$
the conclusion is obvious. The proof is complete.
\end{proof}
\begin{rem}\label{rect-cuboid}\rm
Using \eqref{riesz-dirichlet-n2-lower} one can give a lower bound for $\mathcal{N}^D_{\mathcal{R}}(\lambda)$ for any rectangle $\mathcal{R}$ in $\rr^2$.
Inductively, a lower bound for the eigenvalue counting function can be explicitly given on any cuboid in higher dimension.
\end{rem}


