Let us prove the planer case from Theorem \ref{polya-rectangle-minus}.
\begin{proof}[Proof of the case $n=2$ in Theorem \ref{polya-rectangle-minus}]
Denote by $\Omega_0=\Omega_1\times\Omega_2$ and $\Omega=\Omega_1\times\Omega_2\setminus\overline{\cup_{k=1}^\infty Q_{k}}$.
Let
 $$\mathscr{V}_Q:=\left|\cup_{k=1}^\infty Q_{k}\right|=\sum_{k=1}^\infty \ell(Q_k)^n.$$
 Then
 $$\mathscr{V}_Q\le \mathscr{S}_Q<\infty.$$




By Theorem \ref{pertubation-product-1d} we have for $\lambda>0$ that
\begin{align*}
\mathcal{N}^D_{\Omega_0}(\lambda)&\le  \frac{|\Omega_1||\Omega_2| }{4\pi}\lambda \left(1- \frac{{2}}{3|\Omega_2|\sqrt{\lambda}}\right)_+.
\end{align*}
by Corollary \ref{first-k-dirichlet-1d} we have for
$$k_0=\left\lfloor\frac{|\Omega| }{4\pi}\left[\left(1-\frac{|\Omega|}{|\Omega_1||\Omega_2|}\right)^{-1}\frac{2}{3|\Omega_2|}\right]^{2}\right\rfloor= \left\lfloor\frac{|\Omega|}{4\pi}\left[ \frac{2|\Omega_1|}{3\mathscr{V}_Q}\right]^{2}\right\rfloor,$$
the first $k_0$ Dirichlet eigenvalues of $\Omega$ satisfy P\'olya's conjecture, that is, for $1\le i\le k_0$,
$$\frac{|\Omega|\omega(2)}{(2\pi)^2}\lambda_i(\Omega)\ge i.$$
In particular, since $|\Omega_1|\ge 2\sqrt 2 \pi \mathscr{S}_Q\ge 2\sqrt 2 \pi \mathscr{V}_Q $,
$$|\Omega|=|\Omega_1||\Omega_2|-\mathscr{V}_Q\ge  (2\sqrt 2 \pi-1) \mathscr{V}_Q\ge (2\sqrt 2 \pi-1), $$
we find that
$$\lambda_{k_0}(\Omega)\ge \frac{4\pi}{|\Omega|}\left(\frac{|\Omega|}{4\pi}\left[ \frac{2|\Omega_1|}{3\mathscr{V}_Q}\right]^{2}-1\right)>33. $$



Recall that  Lemma \ref{riesz-dirichlet-n1} implies that for $\lambda>\pi^2/|\Omega_1|^2+\pi^2/|\Omega_2|^2$,
\begin{align*}
 \mathcal{N}^D_{\Omega_1\times\Omega_2}(\lambda)&\le \sum_{j:\,\lambda_j(\Omega_2)<\lambda } \frac{|\Omega_1|}{\pi} (\lambda-\lambda_j(\Omega_2))^{1/2}\nonumber\\
&\le  \frac{|\Omega_1||\Omega_2|}{4\pi}\lambda\left(1- \frac{2}{|\Omega_2| \sqrt{\lambda}}+
  \frac{4\sqrt 6\pi}{9|\Omega_2|^2\lambda} \sqrt{\lfloor\frac{|\Omega_2|}{\pi}\sqrt{\lambda}\rfloor+\frac 12}\right).
\end{align*}
In particular, for $\lambda>33$, it holds that
\begin{align}\label{improved-2d-product}
 \mathcal{N}^D_{\Omega_1\times\Omega_2}(\lambda)&\le  \frac{|\Omega_1||\Omega_2|}{4\pi}\lambda\left(1- \frac{2}{|\Omega_2| \sqrt{\lambda}}+
  \frac{4\sqrt 6\pi}{9|\Omega_2|^2\lambda} \sqrt{\frac 32 \frac{|\Omega_2|}{\pi}\sqrt{\lambda}}\right)\nonumber\\
  &\le  \frac{|\Omega_1||\Omega_2|}{4\pi}\lambda\left(1- \frac{1}{|\Omega_2| \sqrt{\lambda}}\right).
\end{align}



Now consider the union of open sets $\Omega$, $Q_{k}$, $k\in\cn$,  which are disjoint and contained in $\Omega_1\times\Omega_2$, but
satisfy
$$|\Omega_1\times\Omega_2|=|\Omega\cup\cup_{k\in\cn} Q_{k}|.$$
So by monotonicity of Dirichlet eigenvalues, P\'olya's conjecture holds on $\Omega\cup\cup_{1\le k<\infty}Q_{k}$,
\begin{align*}
\mathcal{N}^D_{\Omega\cup\cup_{k\in\cn}Q_{k}}(\lambda)\le \mathcal{N}^D_{\Omega_0}(\lambda).
\end{align*}
Moreover, by Lemma \ref{opposite-cube} [(ii)], we see that for $\lambda\ge \lambda_{k_0}(\Omega)$,
\begin{align*}
\mathcal{N}^D_{\Omega\cup\cup_{k\in\cn}  Q_{k}}(\lambda)&= \mathcal{N}^D_{\Omega}(\lambda)+\sum_{k\in\cn}  \mathcal{N}_{Q_{k}}(\lambda)\\
&\ge \mathcal{N}^D_{\Omega}(\lambda)+\sum_{k\in\cn} \left( \frac{\ell(Q_k)^2}{4\pi}\lambda- \frac{\sqrt 2 \ell(Q_k)}{2}\sqrt\lambda\right).
\end{align*}
Combining the above two estimates, we deduce that for $\lambda\ge \lambda_{k_0}(\Omega)>33$,
\begin{align*}
\mathcal{N}^D_{\Omega}(\lambda)&\le  \frac{|\Omega_1||\Omega_2| }{4\pi}\lambda \left(1- \frac{{1}}{|\Omega_2|\sqrt{\lambda}}\right)-\sum_{k\in\cn} \left( \frac{\ell(Q_k)^2}{4\pi}\lambda- \frac{\sqrt 2 \ell(Q_k)}{2}\sqrt\lambda\right)\\
&=\frac{|\Omega_1||\Omega_2|-\mathscr{V}_Q }{4\pi}\lambda  -\sqrt{\lambda} \left(\frac{|\Omega_1|}{4\pi}-\frac{\sqrt 2}{2}\mathscr{S}_Q\right)\\
&=\frac{|\Omega| }{4\pi}\lambda -\sqrt{\lambda} \left(\frac{|\Omega_1|}{4\pi}-\frac{\sqrt 2}{2}\mathscr{S}_Q\right).
\end{align*}
Since $|\Omega_1|\ge 2\sqrt 2 \pi \mathscr{S}_Q $, we see that
\begin{align*}
\mathcal{N}^D_{\Omega}(\lambda)&\le \frac{|\Omega| }{4\pi}\lambda,
\end{align*}
which completes the proof.
\end{proof}
\begin{rem}\rm
Note that in Theorem \ref{polya-rectangle-minus}, for $n\ge 4$,
$$C_2(n-1)=\frac{n^{3/2}\pi}{C_1(n-1)},$$
while for $n=2,3$
$$
\frac{n^{3/2}\pi}{C_1(n-1)}>C_2(n-1)
=\begin{cases}
2\sqrt2 \pi, &n=2,\\
9\sqrt 3, & n=3.
\end{cases}
$$
This is because in the proof of two and three dimensional case, we use Corollary \ref{first-k-dirichlet-1d}, which allows us
to reduce the problem for large eigenvalues, in which cases by using Lemma \ref{lem-riesz-dirichlet-n1} we have a better estimate than
the uniform estimate from Theorem \ref{pertubation-product-1d}, see \eqref{improved-2d-product} and \eqref{stronger-3d-dirichlet}.
\end{rem}
\subsection{Three and higher dimensions}
\hskip\parindent
We next provide the proof for $n\ge 3$.
Let $Q\subset\rr^n$ be a unit cube. Similar to Lemma \eqref{opposite-cube}, we have
\begin{lem}\label{opposite-cube-hign}
Let $Q\subset\rr^n$ be a  cube.

(i)  For $n=3$, for any $\lambda>3\pi^2/\ell(Q)^2$, it holds that
$$\mathcal{N}_Q^D(\lambda)\ge  \frac{\ell(Q)^3}{6\pi^2}\lambda^{3/2} - \frac{\omega(3)3^{3/2}\pi \ell(Q)^{2}}{(2\pi)^3}\lambda+1,$$
and for all $\lambda>0$ that
$$\mathcal{N}_Q^D(\lambda)\ge  \frac{\ell(Q)^3}{6\pi^2}\lambda^{3/2} -\frac{\omega(3)3^{3/2}\pi \ell(Q)^{2}}{(2\pi)^3}\lambda.$$

(ii) For $n\ge 4$, for any $\lambda>n^3\pi^2/\ell(Q)^2$, it holds that
$$\mathcal{N}_Q^D(\lambda)\ge  \frac{\omega(n)\ell(Q)^n}{(2\pi)^n} \lambda^{n/2} -  \frac{\omega(n)n^{3/2}\pi \ell(Q)^{n-1}}{(2\pi)^n}\lambda^{\frac{n-1}{2}}+2^n\pi^{n/2},$$
and for all $\lambda>0$ that
$$\mathcal{N}_Q^D(\lambda)\ge  \frac{\omega(n)\ell(Q)^n}{(2\pi)^n} \lambda^{n/2} -  \frac{\omega(n)n^{3/2}\pi \ell(Q)^{n-1}}{(2\pi)^n}\lambda^{\frac{n-1}{2}}.$$
\end{lem}
\begin{proof}
(i) For $n=3$, we have
\begin{align*}
\mathcal{N}_Q^D(\lambda)&=\#\left\{\lambda_k<\lambda:\, \lambda_k=\frac{\pi^2}{\ell(Q)^2}(a^2+b^2+c^2),\,a,b,c\in\mathbb{N}\right\}.
\end{align*}
So the number $\mathcal{N}_Q^D(\lambda)$ is not less than the number of the unit cubes contained
in the first quadrant intersecting the ball
$B(0, \ell(Q)\sqrt{\lambda}/\pi-\sqrt 3)$, where $\sqrt 3$ is the diameter of the unit cube.
We therefore deduce that
\begin{align*}
\mathcal{N}_Q^D(\lambda)&\ge \frac 18 |B(0,\ell(Q)\sqrt{\lambda}/\pi-\sqrt 3 )| =\frac{\pi}{6}\left(\ell(Q)\sqrt{\lambda}/\pi-\sqrt 3 \right)^3\\
&\ge \frac{\ell(Q)^3}{6\pi^2}\lambda^{3/2} -\frac{3\sqrt 3 \pi\ell(Q)^2}{6} \frac{\lambda}{\pi^2}+\frac{9\pi}{6} \frac{\ell(Q)\sqrt\lambda}{\pi} -\frac{3\sqrt 3\pi}{6}\\
&>\frac{\ell(Q)^3}{6\pi^2}\lambda^{3/2} -\frac{3\sqrt 3 \ell(Q)^2}{6} \frac{\lambda}{\pi}+1,
\end{align*}
since $\sqrt\lambda>\pi\sqrt 3/\ell(Q)$. For $\sqrt\lambda\le \pi\sqrt 3/\ell(Q)$, note that
$$\frac{\ell(Q)^3}{6\pi^2}\lambda^{3/2} -\frac{3\sqrt 3 \ell(Q)^2}{6} \frac{\lambda}{\pi}\le 0\le \mathcal{N}_Q^D(\lambda),$$
which completes the proof.

(ii) For $n\ge 4$, we also have
\begin{align*}
\mathcal{N}_Q^D(\lambda)&=\#\left\{\lambda_k<\lambda:\, \lambda_k=\frac{\pi^2}{\ell(Q)^2} \sum_{i=1}^n a_i^2,\,a_i \in\mathbb{N}\right\}.
\end{align*}
So the number $\mathcal{N}_Q^D(\lambda)$ is not less than the number of the unit cubes contained
in the first quadrant intersecting the ball
$B(0, \ell(Q)\sqrt{\lambda}/\pi-\sqrt n)$, where $\sqrt n$ is the diameter of the unit cube.
We therefore deduce that
\begin{align*}
\mathcal{N}_Q^D(\lambda)&\ge \frac 1{2^n} |B(0,\ell(Q)\sqrt{\lambda}/\pi-\sqrt n)| =2^{-n}\omega(n) \left(\ell(Q)\sqrt{\lambda}/\pi-\sqrt n \right)^n\\
&\ge 2^{-n}\omega(n) \sum_{i=0}^n C_n^i(\ell(Q)\lambda^{1/2}\pi^{-1})^{n-i}(-\sqrt n)^i\\
&>\frac{\omega(n)\ell(Q)^n}{(2\pi)^n} \lambda^{n/2} -  \frac{\omega(n)n^{3/2}\pi \ell(Q)^{n-1}}{(2\pi)^n}\lambda^{\frac{n-1}{2}}+2^{-n}\omega(n) \sum_{i=2}^n C_n^i(\ell(Q)\lambda^{1/2}\pi^{-1})^{n-i}(-\sqrt n)^i,
\end{align*}
where $C_n^i$ denotes the combinatoric number.
So if
$$\ell(Q)\lambda^{1/2}\pi^{-1} \ge n^{3/2},$$
then we have
\begin{align*}
\mathcal{N}_Q^D(\lambda)&\ge \frac{\omega(n)\ell(Q)^n}{(2\pi)^n} \lambda^{n/2} -  \frac{\omega(n)n^{3/2}\pi \ell(Q)^{n-1}}{(2\pi)^n}\lambda^{\frac{n-1}{2}}+\frac{\omega(n) n^2(n-1)}{3\times 2^n} (\ell(Q)\lambda^{1/2}\pi^{-1})^{n-2} n^2.
\end{align*}
Since
$$\Gamma(1+\frac{n}{2}) \le \left(\frac{n+2}{2}\right)^{n/2},$$
we deduce that
$$\frac{\omega(n)}{2^{n}} \frac{n^4(n-1)}{3} (\ell(Q)\lambda^{1/2}\pi^{-1})^{n-2}\ge \frac{(\pi)^{n/2}}{2^{n} } \left(\frac{2}{n+2}\right)^{n/2}n^{\frac{3n}{2}+1}\ge 2^n\pi^{n/2},$$
and hence,
\begin{align*}
\mathcal{N}_Q^D(\lambda)&\ge \frac{\omega(n)\ell(Q)^n}{(2\pi)^n} \lambda^{n/2} -  \frac{\omega(n)n^{3/2}\pi \ell(Q)^{n-1}}{(2\pi)^n}\lambda^{\frac{n-1}{2}}+2^n\pi^{n/2}.
\end{align*}

For $\ell(Q)\lambda^{1/2}\pi^{-1} < n^{3/2},$ it holds that
$$\frac{\omega(n)\ell(Q)^n}{(2\pi)^n} \lambda^{n/2} -  \frac{\omega(n)n^{3/2}\pi \ell(Q)^{n-1}}{(2\pi)^n}\lambda^{\frac{n-1}{2}}<0\le \mathcal{N}_Q^D(\lambda),$$
which completes the proof.
\end{proof}

Recall that by \eqref{defn-c1n} and \eqref{defn-c3n}, it holds for $n\ge 4$ that
\begin{align}
C_1(n-1) =
\frac{3\pi\mathscr{B}(\frac{n-1 }{2}-1,2)}{2\mathscr{B}(\frac{n-1 }{2}-1,5/2)}C_3(\frac{n-1}{2})=\frac{3\pi\mathscr{B}(\frac{n-3 }{2},2)}{2\mathscr{B}(\frac{n-3 }{2},5/2)}C_3(\frac{n-1}{2}),
\end{align}
where
\begin{align*}
C_3(p)=
\begin{cases}
\frac 19, & 1<p\le 2,\\
\frac{1}{8 }\left(\frac{247}{256}\right)^{p-1}, & p>2.
\end{cases}
\end{align*}


\begin{thm}\label{3hd-polya}
Let $n\ge 3$ and suppose that $\Omega_1\subset\rr^{n-1}$ satisfies P\'olya's conjecture (e.g. ball, tiling domain, or our example in $\rr^{n-1}$), $\Omega_2$ is an interval in $\rr$.
 Let  $\{Q_{k}\}_{k\in\cn}$ be of {\em Admissible class} in $\rn$ that is contained in $\Omega_1\times\Omega_2$.
If $|\Omega_1|\ge  C_2(n-1)\mathscr{S}_Q$, then P\'olya's conjecture holds on $(\Omega_1\times\Omega_2)\setminus \overline{\cup_{k\in\cn}Q_{k}}$,
where $C_2(n-1)$ is as in \eqref{defn-c2n},
\begin{align*}
C_2(n)=\begin{cases}
9\sqrt 3, & n=2,\\
\frac{6(n+1)^{3/2}\mathscr{B}(\frac{n}{2}-1,5/2)}{\mathscr{B}(\frac{n}{2}-1,2)} & n=3,4,\\
\frac{16(n+1)^{3/2} \mathscr{B}(\frac{n }{2}-1,5/2)}{3\mathscr{B}(\frac{n }{2}-1,2)}\left(\frac{256}{247}\right)^{\frac{n-2}{2}}  &  n\ge 5.
\end{cases}
\end{align*}
\end{thm}
\begin{proof} Denote by $\Omega_0=\Omega_1\times\Omega_2$,
 $\Omega_3$  the union  ${\cup_{k\in\cn} Q_{k}}$, and $\Omega=\Omega_0\setminus \overline{\Omega_3}$.
Let
 $$\mathscr{V}_Q:=\left|\cup_{k=1}^\infty Q_{k }\right|=\sum_{k=1}^\infty \ell(Q_k)^n.$$
 Then
 $$\mathscr{V}_Q\le \mathscr{S}_Q<\infty.$$



{\bf Step 1}.
Let us first consider the case $n=3$.
 By Theorem \ref{pertubation-product-1d} we have for $\lambda>0$ that
\begin{align*}
\mathcal{N}^D_{\Omega_0}(\lambda)&\le  \frac{|\Omega_1||\Omega_2|\omega(3)}{(2\pi)^3}\lambda^{3/2}\left(1- \frac{{3\pi}}{16|\Omega_2|\sqrt{\lambda}}\right)_+.
\end{align*}


For $\Omega$ we have by Corollary \ref{first-k-dirichlet-1d}, for $k_0$
being the largest integer satisfying
$$k_0\le \frac{|\Omega|\omega(3)}{(2\pi)^n}\left[\left(\frac{\mathscr{V}_Q}{|\Omega_1||\Omega_2|}\right)^{-1}\frac{3\pi}{16|\Omega_2|}\right]^{3}=\frac{9\pi |\Omega_1|^3 |\Omega|}{2^{13}\mathscr{V}_Q^3},$$
it holds  for each $1\le k\le k_0$,  the P\'olya conjecture holds on $\Omega$ for $\lambda_k(\Omega)$, i.e.,
$$k\le \frac{|\Omega|\omega(3)}{(2\pi)^3}\lambda_{k}(\Omega)^{3/2}.$$
Since $|\Omega_1|\ge 9\sqrt 3 \mathscr{S}_Q\ge 9\sqrt 3\mathscr{V}_Q$ and $|\Omega_2|>1$, it holds that
$$\lambda_{k_0}(\Omega)\ge \left(6\pi^2 \frac{k_0}{|\Omega|}\right)^{2/3}>\left(6\pi^2 \frac{\frac{9\pi |\Omega_1|^3 |\Omega|}{2^{13}\mathscr{V}_Q^3}-1}{|\Omega|}\right)^{2/3}> \left(6\pi^2 \frac{\frac{8\pi |\Omega_1|^3 |\Omega|}{2^{13}\mathscr{V}_Q^3}}{|\Omega|}\right)^{2/3}>61>3\pi^2.  $$


Recall that  Lemma \ref{riesz-dirichlet-n1} implies that for $\lambda>\lambda_1(\Omega_2)$,
\begin{align}
 \mathcal{N}^D_{\Omega_1\times\Omega_2}(\lambda)&\le \sum_{j:\,\lambda_j(\Omega_2)<\lambda } \frac{|\Omega_1|\omega(2)}{(2\pi)^{2}} (\lambda-\lambda_j(\Omega_2))\nonumber\\
&\le  \frac{|\Omega_1||\Omega_2|\omega(3)}{(2\pi)^3}\lambda^{3/2}\left(1-  \left(\frac{\lfloor\frac{|\Omega_2|\sqrt{\lambda}}{\pi}\rfloor}{\frac{|\Omega_2|\sqrt{\lambda}}{\pi}}\right)^2\frac{3\pi}{4|\Omega_2|\sqrt\lambda}\right).
\end{align}
Since $\lambda_k(\Omega)>61$, $|\Omega_2|> 1$, we have   that
$$\left(\frac{\lfloor\frac{|\Omega_2|\sqrt{\lambda_k(\Omega)}}{\pi}\rfloor}{\frac{|\Omega_2|\sqrt{\lambda_k(\Omega)}}{\pi}}\right)^2\ge \frac 49,$$
and hence,
\begin{align}\label{stronger-3d-dirichlet}
\mathcal{N}^D_{\Omega_0}(\lambda)= \mathcal{N}^D_{\Omega_1\times\Omega_2}(\lambda)&\le  \frac{|\Omega_1||\Omega_2|\omega(3)}{(2\pi)^3}\lambda^{3/2}\left(1- \frac{\pi}{3|\Omega_2|\sqrt\lambda}\right).
\end{align}

For
$$\lambda\ge \lambda_{k_0}(\Omega)>61,$$
by the monotonicity of Dirichlet eigenvalues and the fact $|\Omega\cup\Omega_3|=|\Omega_0|$, we then have
\begin{align*}
\mathcal{N}^D_{\Omega\cup\Omega_3}(\lambda)\le \mathcal{N}^D_{\Omega_0}(\lambda)&\le  \frac{|\Omega_1||\Omega_2|\omega(3)}{(2\pi)^3}\lambda^{3/2}\left(1- \frac{{\pi}}{3|\Omega_2|\sqrt{\lambda}}\right).
\end{align*}

Note that by Lemma \ref{opposite-cube-hign} (i),
\begin{align*}
\mathcal{N}^D_{\Omega\cup\Omega_3}(\lambda)&= \mathcal{N}^D_{\Omega}(\lambda)+\sum_{j\in\cn}\mathcal{N}_{Q_{j}}(\lambda)\\
&\ge \mathcal{N}^D_{\Omega}(\lambda)+\sum_{j\in\cn}\left(\frac{\ell(Q_{j})^3}{6\pi^2}\lambda^{3/2} -\frac{\sqrt 3 \ell(Q_{j})^2}{2} \frac{\lambda}{\pi}\right)\\
&=\mathcal{N}^D_{\Omega}(\lambda)+\frac{\mathscr{V}_Q}{6\pi^2}\lambda^{3/2}-\frac{\sqrt 3 \mathscr{S}_Q}{2} \frac{\lambda}{\pi}.
\end{align*}
This together with \eqref{stronger-3d-dirichlet} implies that
\begin{align*}
\mathcal{N}^D_{\Omega}(\lambda)&\le \frac{|\Omega_1||\Omega_2|\omega(3)}{(2\pi)^3}\lambda^{3/2}\left(1- \frac{\pi}{3|\Omega_2|\sqrt\lambda}\right)-\frac{\mathscr{V}_Q}{6\pi^2}\lambda^{3/2}+\frac{\sqrt 3 \mathscr{S}_Q}{2} \frac{\lambda}{\pi}\\
&=  \frac{|\Omega_1||\Omega_2|-\mathscr{V}_Q}{(2\pi)^3}\omega(3)\lambda^{3/2}-\lambda\left(\frac{|\Omega_1|}{18\pi}  -\frac{\sqrt 3 \mathscr{S}_Q}{2\pi} \right)\\
&=\frac{|\Omega|}{(2\pi)^3}\omega(3)\lambda^{3/2}-\lambda\left(\frac{|\Omega_1|}{18\pi}  -\frac{\sqrt 3 \mathscr{S}_Q}{2\pi} \right).
\end{align*}
As $|\Omega_1|\ge 9\sqrt 3 \mathscr{S}_Q$, we see that
\begin{align*}
\mathcal{N}^D_{\Omega}(\lambda)&\le \frac{|\Omega|}{(2\pi)^3}\omega(3)\lambda^{3/2},
\end{align*}
which completes the case $n=3$.

