{\bf Step 2}. Let us consider the case $n\ge 4$. The proof is the same as above, we only need to verify some constants.

For $\Omega_0$, by Theorem \ref{pertubation-product-1d} we have for $\lambda>0$ that
\begin{align*}
\mathcal{N}^D_{\Omega_1\times\Omega_2}(\lambda)&\le  \frac{|\Omega_1||\Omega_2|\omega(n)}{(2\pi)^n}\lambda^{n/2}\left(1- \frac{C_1(n-1)}{|\Omega_2|\sqrt{\lambda}}\right)_+.
\end{align*}

Moreover, for $\Omega$, by Corollary \ref{first-k-dirichlet-1d}, we have for $k_0$ being the largest integer satisfying
\begin{align}
k_0 &\le \frac{|\Omega|\omega(n)}{(2\pi)^n}\left[\left(1-\frac{|\Omega|}{|\Omega_1||\Omega_2|}\right)^{-1}\frac{C_1(n-1)}{|\Omega_2|}\right]^{n}= \frac{|\Omega|\omega(n)}{(2\pi)^n}\left[\left(\frac{\mathscr{V}_Q}{|\Omega_1||\Omega_2|}\right)^{-1}\frac{C_1(n-1)}{|\Omega_2|}\right]^{n}\nonumber\\
&=\frac{|\Omega|\omega(n)}{(2\pi)^n}  \frac{(C_1(n-1)|\Omega_1|)^n}{\mathscr{V}_Q^n},
\end{align}
the P\'olya conjecture holds true for $1\le k\le k_0$ on $\Omega$, i.e.,
$$\frac{|\Omega|\omega(n)}{(2\pi)^n}\lambda_k(\Omega)^{n/2}\ge k. $$
So for $\lambda_{k_0}(\Omega)$, as $|\Omega_1|\ge n^{3/2}\pi \mathscr{S}_Q /C_1(n-1) \ge n^{3/2}\pi \mathscr{V}_Q /C_1(n-1)$, we have
\begin{align*}
\lambda_{k_0}(\Omega)&\ge \left(\frac{(2\pi)^n}{|\Omega|\omega(n)} k_0\right)^{2/n} \ge \left(\frac{(2\pi)^n}{2|\Omega|\omega(n)} \frac{|\Omega|\omega(n)}{(2\pi)^n} \frac{ (C_1(n-1)|\Omega_1|)^n }{\mathscr{V}_Q^n} \right)^{2/n} \\
&\ge \frac 12 \frac{ (C_1(n-1)|\Omega_1|)^2 }{\mathscr{V}_Q^2}>n^3\pi^2/2.
\end{align*}



For
$$\lambda\ge \lambda_{k_0}(\Omega),$$
by the monotonicity of Dirichlet eigenvalues and the fact $|\Omega\cup\Omega_3|=|\Omega_0|$, we then have
\begin{align*}
\mathcal{N}^D_{\Omega\cup\Omega_3}(\lambda)\le \mathcal{N}^D_{\Omega_0}(\lambda)&\le   \frac{|\Omega_1||\Omega_2|\omega(n)}{(2\pi)^n}\lambda^{n/2}\left(1- \frac{C_1(n-1)}{|\Omega_2|\sqrt{\lambda}}\right).
\end{align*}
By Lemma \ref{opposite-cube-hign} (ii),
\begin{align*}
\mathcal{N}^D_{\Omega\cup\Omega_3}(\lambda)&= \mathcal{N}^D_{\Omega}(\lambda)+\sum_{j\in\cn}\mathcal{N}_{Q_{j}}(\lambda)\\
&\ge \mathcal{N}^D_{\Omega}(\lambda)+\sum_{j\in\cn}\left(\frac{\omega(n)\ell(Q_{j})^n}{(2\pi)^n} \lambda^{n/2} -  \frac{\omega(n)n^{3/2}\pi \ell(Q_{j})^{n-1}}{(2\pi)^n}\lambda^{\frac{n-1}{2}}\right)\\
&=\mathcal{N}^D_{\Omega}(\lambda)+\frac{\omega(n)\mathscr{V}_Q}{(2\pi)^n} \lambda^{n/2}-\frac{\omega(n)n^{3/2}\pi \mathscr{S}_Q}{(2\pi)^n}\lambda^{\frac{n-1}{2}}.
\end{align*}
The above two inequalities  imply  that
\begin{align*}
\mathcal{N}^D_{\Omega}(\lambda)&\le \frac{|\Omega_1||\Omega_2|\omega(n)}{(2\pi)^n}\lambda^{n/2}\left(1- \frac{C_1(n-1)}{|\Omega_2|\sqrt{\lambda}}\right)-\left(\frac{\omega(n)\mathscr{V}_Q}{(2\pi)^n} \lambda^{n/2}-\frac{\omega(n)n^{3/2}\pi \mathscr{S}_Q}{(2\pi)^n}\lambda^{\frac{n-1}{2}}\right)\\
&=  \frac{|\Omega_1||\Omega_2|-\mathscr{V}_Q}{(2\pi)^n}\omega(n)\lambda^{n/2}-\frac{\lambda^{\frac{n-1}{2}}\omega(n)}{(2\pi)^n} \left(C_1(n-1)|\Omega_1|  -n^{3/2}\pi \mathscr{S}_Q  \right)\\
&= \frac{|\Omega|}{(2\pi)^n}\omega(n)\lambda^{n/2}-\frac{\lambda^{\frac{n-1}{2}}\omega(n)}{(2\pi)^n} \left(C_1(n-1)|\Omega_1|  -n^{3/2}\pi \mathscr{S}_Q  \right).
\end{align*}
As $|\Omega_1|\ge n^{3/2}\pi \mathscr{S}_Q /C_1(n-1)=C_2(n-1)\mathscr{S}_Q$, we see that
\begin{align*}
\mathcal{N}^D_{\Omega}(\lambda)&\le \frac{|\Omega|}{(2\pi)^n}\omega(n)\lambda^{n/2},
\end{align*}
which completes the proof.
\end{proof}
\begin{proof}[Proof of the case $n\ge 3$ in Theorem \ref{polya-rectangle-minus}]
The result follows from Theorem \ref{3hd-polya} immediately.
\end{proof}
\subsection{Some other class satisfying P\'olya's conjecture}
\hskip\parindent
We next provide some result regarding the case of general domains satisfying P\'olya's conjecture.
\begin{thm}\label{removing-domain-nonproduct}
Let $\Omega_1\subset\rr^{n}$,  $n\ge 2$. Suppose that
P\'olya's conjecture holds on $\Omega_1$, and $\{Q_j\}_{j\in\cn}$ is of Admissible class contained in $\Omega_1$.
Then it holds on  $\Omega=\Omega_1\setminus\overline{\cup_{j\in\cn}Q_j}$ that
\begin{align}
k\le \begin{cases}
\frac{|\Omega|\omega(n)}{(2\pi)^n}\lambda_k(\Omega)^{n/2},\, &\, k\le 2,\\
\frac{|\Omega|\omega(n)}{(2\pi)^n}\lambda_k(\Omega)^{n/2}+\frac{\omega(n)n^{3/2}\pi \mathscr{S}_Q}{(2\pi)^n}\lambda_k(\Omega)^{\frac{n-1}{2}},\,&\, k>2.
\end{cases}
\end{align}
\end{thm}
\begin{proof}
The required inequalities followed from the Rayleigh-Faber-Krahn inequality ($\lambda_1(\Omega)$) and   the Krahn-Szeg\"o inequality  ($\lambda_2(\Omega)$), see \cite{Henrot06}.

Note that $\Omega\cup \cup_{j}Q_j\subsetneq \Omega_1$, and $|\Omega\cup \cup_jQ_j|=|\Omega_1|$.
By Lemma \ref{opposite-cube-hign} and Lemma \ref{opposite-cube-hign} (ii), and the fact $\Omega$, $Q_j$ are mutually disjoint, we find that
\begin{align*}
\mathcal{N}^D_{ \Omega_1}(\lambda)&\ge \mathcal{N}^D_{\Omega\cup \cup_{j}Q_j}(\lambda)= \mathcal{N}^D_{\Omega}(\lambda)+\sum_{j\in\cn}\mathcal{N}_{Q_{j}}(\lambda)\\
&\ge \mathcal{N}^D_{\Omega}(\lambda)+\sum_{j\in\cn}\left(\frac{\omega(n)\ell(Q_{j})^n}{(2\pi)^n} \lambda^{n/2} -  \frac{\omega(n)n^{3/2}\pi \ell(Q_{j})^{n-1}}{(2\pi)^n}\lambda^{\frac{n-1}{2}}\right)\\
&=\mathcal{N}^D_{\Omega}(\lambda)+\frac{\omega(n)\mathscr{V}_Q}{(2\pi)^n} \lambda^{n/2}-\frac{\omega(n)n^{3/2}\pi \mathscr{S}_Q}{(2\pi)^n}\lambda^{\frac{n-1}{2}},
\end{align*}
where
$$\mathscr{V}_Q:=\left|\cup_{k=1}^\infty Q_{k }\right|=\sum_{k=1}^\infty \ell(Q_k)^n.$$
This together with the assumption that $\Omega_1$ satisfies P\'olya's conjecture implies that
\begin{align*}
\mathcal{N}^D_{\Omega}(\lambda)&\le \frac{|\Omega_1|\omega(n)}{(2\pi)^n}\lambda^{n/2}-\left(\frac{\omega(n)\mathscr{V}_Q}{(2\pi)^n} \lambda^{n/2}-\frac{\omega(n)n^{3/2}\pi \mathscr{S}_Q}{(2\pi)^n}\lambda^{\frac{n-1}{2}}\right)\\
&= \frac{|\Omega|\omega(n)}{(2\pi)^n}\lambda^{n/2}+\frac{\omega(n)n^{3/2}\pi \mathscr{S}_Q}{(2\pi)^n}\lambda^{\frac{n-1}{2}}.
\end{align*}
This is equivalent to that, for $k\ge 3$,
\begin{align}
k\le \frac{|\Omega|}{(2\pi)^n}\omega(n)\lambda_k^{n/2}+\frac{\omega(n)n^{3/2}\pi \mathscr{S}_Q}{(2\pi)^n}\lambda_k^{\frac{n-1}{2}},
\end{align}
which completes the proof.
\end{proof}
Inspired by \cite[Theorem 1.2]{HW24}, using Theorem \ref{removing-domain-nonproduct} we have another class of domains
satisfying P\'olya's conjecture.
\begin{cor}\label{cor-almost-polya}
Let $\Omega_1\subset\rr^{n}$, $n\ge 2$. Suppose that
P\'olya's conjecture holds on $\Omega_1$ (e.g., tiling domain, ball, or our example), and $\{Q_j\}_{j\in\cn}$ is of Admissible class contained in $\Omega_1$.
Then the P\'olya conjecture holds on  $\Omega=(\Omega_1\setminus\overline{\cup_{j\in\cn}Q_j})\times \Omega_2$, whenever
$\Omega_2\subset\rr$ satisfies
$$|\Omega_2|   \le
\begin{cases}
\frac{|\Omega_1\setminus\overline{\cup_{j\in\cn}Q_j}|}{4\sqrt 2 \pi \mathscr{S}_Q }, &\, n=2,\\
\frac{|\Omega_1\setminus\overline{\cup_{j\in\cn}Q_j}|}{ 2\times 3^{5/2} \mathscr{S}_Q }\left(\frac{247}{256}\right)^{\frac{n-2}{2}}, &\, n=3,\\
\frac{|\Omega_1\setminus\overline{\cup_{j\in\cn}Q_j}|}{3 \mathscr{S}_Q }\left(\frac{247}{256}\right)^{\frac{n-2}{2}} \frac{\mathscr{B}(\frac{n-3}{2},2)} {2 n^{3/2}\mathscr{B}(\frac{n-3}{2},5/2)}, &\, n\ge 4.
\end{cases}
$$
\end{cor}
\begin{proof}
The proof is similar to the proof of Theorem \ref{pertubation-product-1d}.
Let $\Omega_0=\Omega_1\setminus\overline{\cup_{j\in\cn}Q_j}$.
Then for all $\lambda>\lambda_1(\Omega)$, where
\begin{align}
\lambda_1(\Omega)=\lambda_1(\Omega_0)+\lambda_1(\Omega_2)\ge  \frac{(2\pi)^2}{|\Omega_0|^{2/n}\omega(n)^{2/n}}+ \frac{\pi}{|\Omega_2|^{2}},
\end{align}
we have via Theorem \ref{removing-domain-nonproduct} that
\begin{align*}
\mathcal{N}^D_{\Omega}(\lambda)&=\sum_{j:\,\lambda_j(\Omega_2)<\lambda }\#\left\{k:\,\lambda_k(\Omega_0)+\lambda_j(\Omega_2)<\lambda\right\}
=\sum_{j:\,\lambda_j(\Omega_2)<\lambda } \#\left\{k:\,\lambda_k(\Omega_0)<(\lambda -\lambda_j(\Omega_2))\right\}\\
&\le \sum_{j:\,\lambda_j(\Omega_2)<\lambda } \left[\frac{|\Omega_0|\omega(n)}{(2\pi)^{n}}  (\lambda -\lambda_j(\Omega_2))^{n/2}+  \frac{\omega(n)n^{3/2}\pi \mathscr{S}_Q}{(2\pi)^n}(\lambda -\lambda_j(\Omega_2))^{\frac{n-1}{2}}\right].
\end{align*}
For $n=2$, via Lemma \ref{lem-riesz-dirichlet-n1}  we find that
\begin{align*}
\mathcal{N}^D_{\Omega}(\lambda)&\le \sum_{j:\,\lambda_j(\Omega_2)<\lambda } \left[\frac{|\Omega_0|\omega(n)}{(2\pi)^{n}}  (\lambda -\lambda_j(\Omega_2))^{n/2}+  \frac{\omega(n)n^{3/2}\pi \mathscr{S}_Q}{(2\pi)^n}(\lambda -\lambda_j(\Omega_2))^{\frac{n-1}{2}}\right]\\
&\le \frac{|\Omega_0|\omega(n)}{(2\pi)^{n}}  \frac{2|\Omega_2|}{3\pi} \lambda^{3/2}  \left(1 - \frac{3\pi}{16|\Omega_2|\sqrt\lambda} \right) +\frac{\omega(n)n^{3/2}\pi \mathscr{S}_Q}{(2\pi)^n} \frac {|\Omega_2|}{4} \lambda\\
&= \frac{|\Omega_0||\Omega_2|}{6\pi^2}\lambda^{3/2}+\frac{ \omega(n)\lambda }{(2\pi)^{n}} \left({n^{3/2}\pi \mathscr{S}_Q} \frac {|\Omega_2|}{4}-\frac{|\Omega_0|}{8}\right).
\end{align*}
For
$$|\Omega_2|\le \frac{|\Omega_0|}{4\sqrt 2 \pi \mathscr{S}_Q },$$
we see that
\begin{align*}
\mathcal{N}^D_{\Omega}(\lambda)&\le  \frac{|\Omega_0||\Omega_2|}{6\pi^2}\lambda^{3/2}.
\end{align*}

For $n=3$, we via Lemma \ref{lem-riesz-dirichlet-n1}  and Lemma \ref{lem-1d} that
\begin{align*}
\mathcal{N}^D_{\Omega}(\lambda)&\le \sum_{j:\,\lambda_j(\Omega_2)<\lambda }\left[ \frac{|\Omega_0|\omega(n)}{(2\pi)^{n}}  (\lambda -\lambda_j(\Omega_3))^{n/2}+  \frac{\omega(n)n^{3/2}\pi  \mathscr{S}_Q}{(2\pi)^n} (\lambda -\lambda_j(\Omega_2))^{\frac{n-1}{2}}\right]\\
&\le \frac{|\Omega_0|\omega(n)}{(2\pi)^{n}} \left( \frac{2|\Omega_2|}{3\pi\mathscr{B}(\frac{n-2}{2},2)}  \lambda^{\frac{n+1}{2}} \mathscr{B}(\frac{n-2}{2},5/2)-\frac{1}{9}\left(\frac{247}{256}\right)^{\frac{n-2}{2}}  \lambda^{\frac{n}{2}}  \right)\\
&\quad+ \frac{\omega(n)n^{3/2}\pi  \mathscr{S}_Q}{(2\pi)^n} \frac{2|\Omega_2|}{3\pi} \lambda^{3/2}\\
&=\frac{|\Omega_0||\Omega_2|\omega(n+1)}{(2\pi)^{n+1}} \lambda^{\frac{n+1}{2}} +\frac{ \omega(n)\lambda^{\frac n2}}{(2\pi)^{n}}\left( \frac{2n^{3/2} \mathscr{S}_Q |\Omega_2|}{3} -
\frac{|\Omega_0|}{9}\left(\frac{247}{256}\right)^{\frac{n-2}{2}}  \right).
\end{align*}
The desired conclusion follows as soon as
$$ |\Omega_2| \le
\frac{|\Omega_0|}{ 2\times 3^{5/2} \mathscr{S}_Q }\left(\frac{247}{256}\right)^{\frac{n-2}{2}} .$$

For $n\ge 4$, we deduce via Lemma \ref{lem-1d} that
\begin{align*}
\mathcal{N}^D_{\Omega}(\lambda)&\le  \sum_{j:\,\lambda_j(\Omega_2)<\lambda }\left[ \frac{|\Omega_0|\omega(n)}{(2\pi)^{n}}  (\lambda -\lambda_j(\Omega_2))^{n/2}+  \frac{\omega(n)n^{3/2}\pi  \mathscr{S}_Q}{(2\pi)^n} (\lambda -\lambda_j(\Omega_2))^{\frac{n-1}{2}}\right]\\
&\le \frac{|\Omega_0|\omega(n)}{(2\pi)^{n}} \left( \frac{2|\Omega_2|}{3\pi\mathscr{B}(\frac{n-2}{2},2)}  \lambda^{\frac{n+1}{2}} \mathscr{B}(\frac{n-2}{2},5/2)-\frac{1}{9}\left(\frac{247}{256}\right)^{\frac{n-2}{2}}  \lambda^{\frac{n}{2}}  \right)\\
&\quad+ \frac{\omega(n)n^{3/2}\pi  \mathscr{S}_Q}{(2\pi)^n} \frac{2|\Omega_3|}{3\pi\mathscr{B}(\frac{n-3}{2},2)}  \lambda^{\frac{n}{2}} \mathscr{B}(\frac{n-3}{2},5/2)\\
&=\frac{|\Omega_0||\Omega_2|\omega(n+1)}{(2\pi)^{n+1}} \lambda^{\frac{n+1}{2}} +\frac{ \omega(n)\lambda^{\frac n2}}{(2\pi)^{n}}\left( \frac{2n^{3/2} \mathscr{S}_Q |\Omega_3|\mathscr{B}(\frac{n-3}{2},5/2)}{3\mathscr{B}(\frac{n-3}{2},2)} -
\frac{|\Omega_0|}{9}\left(\frac{247}{256}\right)^{\frac{n-2}{2}}  \right).
\end{align*}
Since
$$|\Omega_2|   \le
\frac{|\Omega_0|}{3}\left(\frac{247}{256}\right)^{\frac{n-2}{2}} \frac{\mathscr{B}(\frac{n-3}{2},2)} {2n^{3/2}  \mathscr{S}_Q \mathscr{B}(\frac{n-3}{2},5/2)},$$
we see that
 \begin{align*}
\mathcal{N}^D_{\Omega}(\lambda)&\le \frac{|\Omega_0||\Omega_2|\omega(n+1)}{(2\pi)^{n+1}} \lambda^{\frac{n+1}{2}},
\end{align*}
which completes the proof.
\end{proof}



\section{Proof of the main results}
\hskip\parindent In this section, we prove our main uniform estimates on Lipschitz domains.
Let us recall the Whitney decomposition, see \cite[Appendix J]{Grafakos08}.
\begin{prop}\label{whitney}
Let $\Omega$ be an open nonempty subset of $\rn$. Then there exists a family of dyadic cubes $\{Q_i\}_j$ such that

(a) $\cup_j Q_j=\Omega$ and the $Q_j's$ have disjoint interiors.

(b) $\sqrt n \ell(Q_j)\le \mathrm{dist}(Q_j,\Omega^c)\le 4\sqrt n\ell(Q_j).$

(c) If the boundaries of $Q_j$ and $Q_k$ touch, then
$$\frac 14\le \frac{\ell(Q_j)}{\ell(Q_k)}\le 4.$$

(d) For a given $Q_j$ there exist at most $12^n$ $Q_k$'s that touch it.
\end{prop}


We first provide the proof for the estimate on the remainder of Weyl's law.
\begin{proof}[Proof of Theorem  \ref{weyl-remainder-uniform}]
{\bf Step 1. Upper bound for Dirichlet eigenvalues}.
Let $\{Q_j\}_{j\in\cn}$ be a sequence of dyadic cubes that forms a Whitney decomposition of $\Omega$ by
Proposition \ref{whitney}. Suppose that $B(x_0,r_{in})$ is the largest inner ball contained in $\Omega$.

Let $Q_l$ be a cube from $\{Q_j\}_j$ such that $x_0\in \overline{Q_l}$.
Then it holds that
$$\sqrt n\ell(Q_l)\le \mathrm{dist}(Q_l,\Omega^c)\le r_{in}\le 5\sqrt n \ell(Q_l).$$
If there is some other $Q_i$, with $\ell(Q_i)>\ell(Q_l)$, then
$$\sqrt n \ell(Q_i)\le r_{in}\le 5\sqrt n \ell(Q_l).$$
Let $2^{-k_0}$ be the side length of the largest cube in $\{Q_j\}_j$. So it holds that
$$\frac{r_{in}}{5\sqrt n}\le 2^{-k_0}=\sup_{Q_j}\{\ell(Q_j)\}\le \frac{r_{in}}{\sqrt n}.$$



For $0<\epsilon<r_{in}$, let
$$\Omega_\epsilon=\{x\in\Omega:\,\mathrm{dist}(x,\partial\Omega)<\epsilon\}.$$
Let $k_\epsilon\in\mathbb{Z}$ be such that
$$5\sqrt n 2^{-k_\epsilon}\le \epsilon< 5\sqrt n 2^{-k_\epsilon+1}.$$
Then $k_\epsilon<k_0$.

By Lemma \ref{opposite-cube} and Lemma \ref{opposite-cube-hign}, we have for any $\lambda>0$,
\begin{align*}
\mathcal{N}_\Omega^D(\lambda)&\ge \sum_{\ell(Q_j)>2^{-k_\epsilon}} \mathcal{N}_{Q_j}^D(\lambda)\\
&=\sum_{m=k_0}^{k_\epsilon-1} \sum_{Q_j:\,\ell(Q_j)=2^{-m}} \mathcal{N}_{Q_j}^D(\lambda) \\
&\ge \sum_{m=k_0}^{k_\epsilon-1} \sum_{Q_j:\,\ell(Q_j)=2^{-m}}  \left( \frac{\omega(n)\ell(Q_j)^n}{(2\pi)^n} \lambda^{n/2} -  \frac{\omega(n)n^{3/2}\pi \ell(Q_j)^{n-1}}{(2\pi)^n}\lambda^{\frac{n-1}{2}}\right).
\end{align*}
Note that all the cubes $\{Q_j\}_j$ with side length smaller than $2^{-k_\epsilon+1}$ is contained in $\Omega_\epsilon$. Moreover,
 the number of cubes of side length $2^{-j}$, $j\ge k_0$, is smaller than
$$\frac{|\Omega_{5\sqrt n 2^{-j}}|}{2^{-jn}}\le \frac{C_{Lip}(\Omega) 5\sqrt n 2^{-j}|\partial\Omega| }{2^{-jn}}\le 5\sqrt n 2^{j(n-1)}C_{Lip}(\Omega) |\partial\Omega|,$$
where we used the fact that
$$|  \Omega_{5\sqrt n 2^{-j}} |=\left|\{x\in\Omega:\,\mathrm{dist}(x,\partial\Omega)<5\sqrt n 2^{-j}\}\right|\le 5\sqrt n 2^{-j} C_{Lip}(\Omega) |\partial\Omega|,$$
$C_{Lip}(\Omega)$ is defined as in  \eqref{constant-omega}.

We therefore deduce that
\begin{align*}
\mathcal{N}_\Omega^D(\lambda)&\ge   \frac{\omega(n)|\Omega\setminus \Omega_\epsilon|}{(2\pi)^n} \lambda^{n/2} -   \sum_{m=k_0}^{k_\epsilon-1}  5\sqrt n C_{Lip}(\Omega)|\partial\Omega| \frac{\omega(n)n^{3/2}\pi  }{(2\pi)^n}\lambda^{\frac{n-1}{2}}\nonumber \\
&\ge  \frac{\omega(n)|\Omega|}{(2\pi)^n} \lambda^{n/2}-  \frac{\omega(n)|\Omega_\epsilon|}{(2\pi)^n} \lambda^{n/2} -5\sqrt n (k_\epsilon-k_0)C_{Lip}(\Omega)|\partial\Omega| \frac{\omega(n)n^{3/2}\pi  }{(2\pi)^n}\lambda^{\frac{n-1}{2}}.
\end{align*}
Note that
$$|  \Omega_\epsilon|=\left|\{x\in\Omega:\,\mathrm{dist}(x,\partial\Omega)<\epsilon\}\right|\le C_{Lip}(\Omega)\epsilon |\partial\Omega|$$
and
$$2^{k_\epsilon-k_0}\le {\frac{10\sqrt n}{\epsilon}}{\frac{r_{in}}{\sqrt n }}\le \frac{10r_{in}}{\epsilon}.$$
We therefore have
\begin{align}\label{epsilon-lower-convex}
\mathcal{N}_\Omega^D(\lambda)&\ge
 \frac{\omega(n)|\Omega|}{(2\pi)^n} \lambda^{n/2}-  \frac{C_{Lip}(\Omega)\omega(n)|\partial\Omega|}{(2\pi)^n}\lambda^{\frac{n-1}{2}}\left(\epsilon \lambda^{1/2} +5n^{2}\pi\log_2\frac{10r_{in}}{\epsilon} \right).
\end{align}
Let $\mathscr{R}=\mathscr{R}_{n-1}\times I_{min}$ be the minimal rectangle for $\Omega$. Since
$$\lambda_1(\Omega)\ge \lambda_1(\mathscr{R})>\frac{\pi^2}{|I_{min}|^2},$$
we see that
$$\frac{\pi r_{in}}{|I_{min}|\sqrt{\lambda_1(\Omega)}}<  r_{in}. $$
So for each $k\in\cn$ we can let
$$\epsilon=\frac{\pi r_{in}}{|I_{min}|\sqrt{\lambda_k(\Omega)}}$$
and deduce that
\begin{align*}
k&\ge
 \frac{\omega(n)|\Omega|}{(2\pi)^n} \lambda_k(\Omega)^{n/2}-  \frac{C_{Lip}(\Omega)\omega(n)|\partial\Omega| }{(2\pi)^n}\lambda_k(\Omega)^{\frac{n-1}{2}}\left(\frac{\pi r_{in}}{|I_{min}|}+5n^{2}\pi\log_2\frac{10|I_{min}| \sqrt{\lambda_k(\Omega)}}{\pi } \right).
\end{align*}
The proof of {\bf Step 1} is complete.




{\bf Step 2. Lower bound for the Dirichlet eigenvalues}.
To prove the lower bound  for the Dirichlet eigenvalues of $\Omega$, let us set $\Omega_1=\mathscr{R}\setminus \overline{\Omega}$. Obviously, $\Omega_1$ is also a Lipschitz domain.
Moreover, it holds that
\begin{align}\label{constant-complement-omega}
\left|\{x\in \Omega_1:\,\mathrm{dist}(x,\partial \Omega_1)<\epsilon\}\right|
&\le \epsilon |\partial \mathscr{R}\cap\partial\Omega_1|+C_{Lip}(\Omega)\epsilon |\partial\Omega_1 \cap(\partial\Omega\setminus\partial\mathscr{R})|\nonumber\\
&\le C_{Lip}(\Omega) \epsilon|\partial\Omega_1|.
\end{align}
Recall also that $r_{in}(\Omega_1)$ denotes the inner radius of $\Omega_1$.


Since $\Omega\cup \Omega_1\subset\mathscr{R}=\mathscr{R}_{n-1}\times I_{min}$ and $|\Omega\cup \Omega_1|=|\mathscr{R}|$, we have via the monotonicity of Dirichlet eigenvalues  for any $\lambda>0$ that
\begin{align*}
\mathcal{N}_{\Omega\cup\Omega_1}^D(\lambda)=\mathcal{N}_{\Omega}^D(\lambda)+\mathcal{N}_{\Omega_1}^D(\lambda)\le \mathcal{N}_{\mathscr{R}}^D(\lambda).
\end{align*}
Applying {\bf Step 1} to $\Omega_1$, \eqref{constant-complement-omega} and Theorem \ref{pertubation-product-1d}, we find that
\begin{align*}
\mathcal{N}_{\Omega}^D(\lambda)&\le  \mathcal{N}_{\mathscr{R}}^D(\lambda)-\mathcal{N}_{\Omega_1}^D(\lambda)\\
& \le \frac{|\mathscr{R}_{n-1}||I_{min}|\omega(n)}{(2\pi)^n}\lambda^{n/2}\left(1- \frac{C_1(n-1)}{|I_{min}|\sqrt{\lambda}}\right)_+\\
&\quad - \frac{\omega(n)|\Omega_1|}{(2\pi)^n} \lambda^{n/2}+  \frac{C_{Lip}(\Omega)\omega(n)|\partial\Omega_1|}{(2\pi)^n}\lambda^{\frac{n-1}{2}}\left(\epsilon \lambda^{1/2} +5n^{2}\pi\log_2\frac{10r_{in}(\Omega_1) }{\epsilon} \right),
\end{align*}
for $0<\epsilon<r_{in}(\Omega_1)$.


Since
$$\lambda_1(\Omega)\ge \lambda_1(\mathscr{R})>\frac{\pi^2}{|I_{min}|^2},$$
we see that
$$\frac{\pi r_{in}(\Omega_1)}{|I_{min}|\sqrt{\lambda_1(\Omega)}}<  r_{in}(\Omega_1). $$
So for each $k\in\cn$ we can let
$$\epsilon=\frac{\pi r_{in}(\Omega_1)}{|I_{min}|\sqrt{\lambda_k(\Omega)}}$$
and get that
\begin{align*}
k&\le \frac{|\Omega|\omega(n)}{(2\pi)^n}\lambda_k(\Omega)^{n/2}\\
&\quad+  \frac{\omega(n)}{(2\pi)^n}\lambda_k(\Omega)^{\frac{n-1}{2}} \left(C_{Lip}(\Omega)|\partial\Omega_1| \left(\frac{\pi r_{in}(\Omega_1)}{|I_{min}|}+5n^{2}\pi\log_2\frac{10|I_{min}|\sqrt{\lambda_k(\Omega)}}{\pi} \right)-C_1(n-1)|\mathscr{R}_{n-1}|\right).
\end{align*}
The proof is complete.
\end{proof}


\begin{rem}\label{convex-better}\rm
If $\Omega\subset\rn$ is a convex domain, then obviously
$$|  \Omega_\epsilon|=\left|\{x\in\Omega:\,\mathrm{dist}(x,\partial\Omega)<\epsilon\}\right|\le \epsilon |\partial\Omega|,$$
i.e., $C_{Lip}(\Omega)=1$ in {\bf Step 1} above.

For {\bf Step 2}, when dealing with the complementary set $\mathscr{R}\setminus\overline{\Omega}$,
one can carry out a Whitney decomposition of the domain $\mathscr{R}\setminus \overline{\Omega}$, w.r.t. to the boundary
$\partial\Omega$, see Figure \ref{fig3}.
\begin{figure}[htbp]
\centering
\includegraphics[scale=0.5]{Whitney.jpg}
\caption{Whitney decomposition for the complementary of a convex set}
\label{fig3}
\end{figure}
The convexity of $\mathscr{R}$ and $\Omega$ would imply that
$$\left|\{x\in\mathscr{R}\setminus\overline{\Omega}:\,\mathrm{dist}(x,\partial\Omega)<\epsilon\}\right| \le
|\partial\mathscr{R}\setminus\partial\Omega|\epsilon.$$
Applying this estimate to {\bf Step 2} above gives that
\begin{align*}
k&\le \frac{|\Omega|\omega(n)}{(2\pi)^n}\lambda_k(\Omega)^{n/2}\\
&\quad+  \frac{\omega(n)}{(2\pi)^n}\lambda_k(\Omega)^{\frac{n-1}{2}} \left(|\partial\mathscr{R}\setminus\partial\Omega|\left(\frac{\pi r_{in}(\Omega_1)}{|I_{min}|}+5n^{2}\pi\log_2\frac{10|I_{min}|\sqrt{\lambda_k(\Omega)}}{\pi} \right)-C_1(n-1)|\mathscr{R}_{n-1}|\right).
\end{align*}
Obviously, $|\partial\mathscr{R}\setminus\partial\Omega|\le |\partial (\mathscr{R}\setminus\overline{\Omega})|$. The number $\Lambda(\epsilon,\Omega)$ from Theorem \ref{epsilon-loss-lip} can be taken smaller than \eqref{epsilon-constant} as
\begin{align*}
\frac{2n \mathrm{diam}(\Omega)^{n-1}}{|\Omega|\sqrt{\Lambda(\epsilon,\Omega)}} \left(\frac{\pi}{2}-\frac{C_1(n-1)}{2n}+5n^{2}\pi\log_2\frac{10\mathrm{width}(\Omega)\sqrt{\Lambda(\epsilon,\Omega)}}{\pi} \right)= \epsilon,
\end{align*}
where $C_1(n-1)$ is as in \eqref{defn-c1n}, see the following proof of Theorem \ref{epsilon-loss-lip}.
\end{rem}
We now prove the $\epsilon$-loss version of P\'olya's conjecture for large eigenvalues.
\begin{proof}[Proof of Theorem \ref{epsilon-loss-lip}]
Let $\Omega_1=\mathscr{R}\setminus\overline{\Omega}$. By Theorem \ref{weyl-remainder-uniform}, it holds for each $k\in\cn$ that
\begin{align*}
k&\le \frac{|\Omega|\omega(n)}{(2\pi)^n}\lambda_k(\Omega)^{n/2}\\
&\quad+  \frac{\omega(n)}{(2\pi)^n}\lambda_k(\Omega)^{\frac{n-1}{2}} \left(C_{Lip}(\Omega)|\partial (\mathscr{R}\setminus \Omega)| \left(\frac{\pi r_{in}(\mathscr{R}\setminus\Omega)}{|I_{min}|}+5n^{2}\pi\log_2\frac{10|I_{min}|\sqrt{\lambda_k(\Omega)}}{\pi} \right)-C_1(n-1)|\mathscr{R}_{n-1}|\right)\\
&\le  \frac{|\Omega|\omega(n)}{(2\pi)^n}\lambda_k(\Omega)^{n/2} \left(1+ \frac{C_{Lip}(\Omega)(2n\mathrm{diam}(\Omega)^{n-1}+|\partial\Omega|)}{\sqrt{\lambda_k}|\Omega|} \left(\frac{\pi }{2}+5n^{2}\pi\log_2\frac{10\mathrm{width}(\Omega)\sqrt{\lambda_k(\Omega)}}{\pi} \right)  \right).
\end{align*}
Taking derivative of the  function
$$f(\Lambda):= \frac{2n\mathrm{diam}(\Omega)^{n-1}+|\partial\Omega|}{\sqrt{\Lambda}|\Omega|} \left(\frac{\pi }{2}+5n^{2}\pi\log_2\frac{10\mathrm{width}(\Omega)\sqrt{\Lambda}}{\pi} \right), $$
we see that
\begin{align*}
f'(\Lambda)&=  -\frac{2n\mathrm{diam}(\Omega)^{n-1}+|\partial\Omega|}{2\Lambda^{3/2}|\Omega|} \left(\frac{\pi }{2}+5n^{2}\pi\log_2\frac{10\mathrm{width}(\Omega)\sqrt{\Lambda}}{\pi} \right)\\
&\quad\quad + \frac{2n\mathrm{diam}(\Omega)^{n-1}+|\partial\Omega|}{\sqrt{\Lambda}|\Omega|} \frac{5n^{2}\pi  \log_2e  }{2\Lambda}.
\end{align*}
We have for each $\Lambda\ge \frac{1}{\mathrm{width}(\Omega)^2}$ that
$$\frac{10\mathrm{width}(\Omega)\sqrt{\Lambda}}{\pi}\ge \frac{ 10}{\pi}>e,$$
and therefore $f(\Lambda)$ is monotone decreasing on $[\frac{1}{\mathrm{width}(\Omega)^2},\infty)$.

Note that for  $\Lambda=\frac{1}{\mathrm{width}(\Omega)^2}$,
$$f(\Lambda)=\frac{(2n \mathrm{diam}(\Omega)^{n-1}+|\partial\Omega|)\mathrm{width}(\Omega)}{|\Omega|} \left(\frac{\pi}{2}+5n^{2}\pi\log_2\frac{10}{\pi} \right)>2n,$$
$$\lim_{\Lambda\to\infty}f(\Lambda)=0,$$
and $C_{Lip}(\Omega)\ge 1$.
So for any $\epsilon\in (0,1)$, we can let $\Lambda> \frac{1}{\mathrm{width}(\Omega)^2}$ be such that
$$ C_{Lip}(\Omega)\frac{2n \mathrm{diam}(\Omega)^{n-1}+|\partial\Omega|}{|\Omega|\sqrt\Lambda} \left(\frac{\pi}{2}+5n^{2}\pi\log_2\frac{10\mathrm{width}(\Omega)\sqrt{\Lambda}}{\pi} \right)= \epsilon,$$
and deduce for any $\lambda_k(\Omega)\ge \Lambda$ that
\begin{align*}
k&\le (1+\epsilon)\frac{|\Omega|\omega(n)}{(2\pi)^n}\lambda_k(\Omega)^{n/2}.
\end{align*}
The proof is complete.
\end{proof}

For open sets, we also have a uniform estimate. Let us remark that, since the boundary of an open set may be complicate, in general
one can not have a uniform estimate in term of its boundary as in Theorem \ref{weyl-remainder-uniform}. Note that $C_1(n-1)$ is defined via \eqref{defn-c1n}.
\begin{thm}\label{almost-polya-openset-general-diam}
Let $\Omega\subset\rr^n$ be a bounded open domain, $n\ge 2$, let  $Q$ be a cube that contains $\Omega$.
For any  $0<\epsilon<\ell(Q)/2$, it holds for all $k\in\cn$ that
\begin{align}\label{open-uniform}
k\le \frac{|\Omega_\epsilon|\omega(n)}{(2\pi)^n}\lambda^{n/2}+\frac{\omega(n) \lambda^{\frac{n-1}{2}}}{(2\pi)^n} \left( 2n^{2}\pi \frac{|Q\setminus\Omega_\epsilon |}{\epsilon} -C_1(n-1)\ell(Q)^{n-1}\right).
\end{align}
where $\Omega_\epsilon=\{x\in Q:\, \mathrm{dist}(x,\Omega)<\epsilon\}$. In particular, one can take  $Q$ to be of side length $\mathrm{diam}(\Omega)$.
\end{thm}
\begin{proof}
Since $\epsilon<\ell(Q)/2$, we can  divide $\mathscr{R}$ into the union of cubes $Q_j$, which are cubes of side length $2^{-k}\ell(Q)$, where $k\in\mathbb{Z}_+$ is such that
\begin{align}\label{epsilon-k}
\epsilon/2< 2^{-k}\ell(Q)\sqrt n\le \epsilon.
\end{align}

Denote by $\tilde Q$ the union of all $Q_j$,  such that $Q_j$ entirely locates in $Q\setminus \overline{\Omega}$.
Then the number of $Q_j$ that composes $\tilde Q$ is controlled by
$$\#\{Q_j:\,Q_j\subset\tilde Q\}\le \frac{|Q\setminus \Omega|}{2^{-kn}\ell(Q)^n}.$$
On the other hand, $\Omega\subset \mathscr{R}\setminus \tilde Q$, which is further contained in
$$\{x\in Q:\, \mathrm{dist}(x,\Omega)<2^{-k}\ell(Q) \sqrt n\}\subset\Omega_\epsilon.$$

By Theorem \ref{pertubation-product-1d}, we have
\begin{align*}
\mathcal{N}^D_{Q}(\lambda)&\le  \frac{|Q|\omega(n)}{(2\pi)^n}\lambda^{n/2}\left(1- \frac{C_1(n-1)}{\ell(Q)\sqrt{\lambda}}\right)_+.
\end{align*}
This together with the monotonicity of Dirichlet eigenvalues implies that
\begin{align}\label{Q-openset}
 \frac{|Q|\omega(n)}{(2\pi)^n}\lambda^{n/2}\left(1- \frac{C_1(n-1)}{\ell(Q)\sqrt{\lambda}}\right)_+&\ge \mathcal{N}^D_{Q}(\lambda)
\ge \mathcal{N}^D_{Q\setminus\tilde Q}(\lambda)+ \mathcal{N}^D_{\tilde Q}(\lambda)\nonumber\\
&\ge \mathcal{N}^D_{\Omega}(\lambda)+ \frac{|Q\setminus \Omega_\epsilon|}{2^{-kn}\ell(Q)^n} \mathcal{N}^D_{Q_j}(\lambda).
\end{align}
Since for each $Q_j$, by Lemma \ref{opposite-cube} and Lemma \ref{opposite-cube-hign}, it holds that
$$\mathcal{N}^D_{ Q_j}(\lambda)\ge \frac{\omega(n)2^{-kn}\ell(Q)^n}{(2\pi)^n} \lambda^{n/2}-
\frac{n^{3/2}\pi \omega(n) 2^{-k(n-1)}\ell(Q)^{n-1}}{(2\pi)^n}\lambda^{\frac{n-1}{2}},$$
we see that
\begin{align*}
\frac{|Q\setminus \Omega_\epsilon |}{2^{-kn}|I_{min}|^n} \mathcal{N}^D_{ Q_j}(\lambda)&\ge \frac{\omega(n)|Q\setminus \Omega_\epsilon |}{(2\pi)^n} \lambda^{n/2} -\frac{\omega(n) \lambda^{\frac{n-1}{2}}}{(2\pi)^n} \frac{ n^{3/2}\pi |Q\setminus\Omega_\epsilon |}{2^{-k}|I_{min}|}.
\end{align*}
This, together with \eqref{epsilon-k}, \eqref{Q-openset}, implies that for
$$\lambda>\lambda_1(\Omega)\ge \lambda_1(Q),$$
it holds that
\begin{align*}
\mathcal{N}^D_{\Omega}(\lambda)&\le \frac{|Q|\omega(n)}{(2\pi)^n}\lambda^{n/2}\left(1- \frac{C_1(n-1)}{\ell(Q)\sqrt{\lambda}}\right)-\frac{\omega(n)|Q\setminus \Omega_\epsilon |}{(2\pi)^n} \lambda^{n/2} +\frac{\omega(n) \lambda^{\frac{n-1}{2}}}{(2\pi)^n} \frac{ n^{3/2}\pi |Q\setminus\Omega_\epsilon |}{2^{-k}\ell(Q)}\\
&=  \frac{|\Omega_\epsilon|\omega(n)}{(2\pi)^n}\lambda^{n/2}+\frac{\omega(n) \lambda^{\frac{n-1}{2}}}{(2\pi)^n} \left( 2n^{2}\pi \frac{|Q\setminus\Omega_\epsilon |}{\epsilon} -C_1(n-1)\ell(Q)^{n-1}\right).
\end{align*}
The proof is complete.
\end{proof}


