    \node at (0,0) {$\Ga_1$};
    \draw[fill,white] (6,0) circle(0.5);
    \draw[thin] (6,0) circle(0.5);
    \node at (6,0) {$\Ga_2$};    

\end{tikzpicture}
\end{center}
The subgraphs $\Ga_1$ and $\Ga_2$ are unbalanced graphs of genus one, and the cycle formed by $g$ and $h$ is balanced. Denote by $\tGa'_1\to\Ga'_1$ and $\tGa'_2\to\Ga'_2$ the double covers over the graphs $\Ga'_1=\Ga_1\cup\{f_1,g,h\}$ and $\Ga'_2=\Ga_2\cup\{f_2,g,h\}$. There are four domains of polynomiality. If $e\leq f_1+f_2$, then
\[
q(\tGa/\Ga)=p_2(e,f_1+f_2)(g+h)+12e^2gh,
\]
where we note that $g+h=w_0(\tGa'/\Ga')$, where $\tGa'\to \Ga'$ is the double cover over the graph $\Ga'$ obtained from $\Ga$ by removing either $\Ga_1$ or $\Ga_2$. For $f_1+f_2\leq e$ we instead have 
\[
q(\tGa/\Ga)=p_3(e-f_1-f_2,g,h)+
p_2(f_1,e)w_0(\tGa'_2/\Ga'_2)+p_2(f_2,e)w_0(\tGa'_1/\Ga'_1)+
\]
\[
+12(2e-f_1-f_2)\left[(f_1+f_2)gh+f_1f_2(g+h)\right].
\]


\subsubsection*{Two $FS_2$-sets, two $FS_3$-sets} The $FS_2$-sets are disjoint, while the remaining five pairwise intersections are distinct edges, therefore we can label the sets as $\{e_1,f_1\}$, $\{e_2,f_2\}$, $\{e_1,f_2,g\}$, and $\{e_2,f_1,g\}$. The graph $\Ga$ has the following form:
\begin{center}
\begin{tikzpicture}
    \draw[thin] (0,0) -- (2,1) -- (4,0);
    \draw[thin] (0,0) -- (2,-1) -- (4,0);
    \draw[thin] (2,1) -- (2,-1);
    \draw[fill,white] (0,0) circle(0.5);
    \draw[thin] (0,0) circle(0.5);
    \node at (0,0) {$\Ga_1$};
    \draw[fill,white] (4,0) circle(0.5);
    \draw[thin] (4,0) circle(0.5);
    \node at (4,0) {$\Ga_2$};
    \node[above] at (1,0.5) {$e_1$};
    \node[below] at (1,-0.5) {$f_1$};
    \node[above] at (3,0.5) {$e_2$};
    \node[below] at (3,-0.5) {$f_2$};
    \node[right] at (2,0) {$g$};
    \draw[fill] (2,1) circle(0.07);
    \draw[fill] (2,-1) circle(0.07);
\end{tikzpicture}
    \end{center}
The subgraphs $\Ga_1$ and $\Ga_2$ are unbalanced graphs of genus one. We denote by $\tGa'_1\to \Ga'_1$ and $\tGa'_2\to \Ga'_2$ the double covers over the subgraphs $\Ga'_1=\Ga_1\cup\{e_1,f_1,g\}$ and $\Ga'_2=\Ga_2\cup\{e_2,f_2,g\}$.

There are eight domains of polynomiality. On the cone $e_1\geq f_1$, $e_2\geq f_2$ we set
\[
q(\tGa/\Ga)=p_2(e_1,f_1)w_0(\tGa'_2/\Ga'_2)+p_2(e_2,f_2)w_0(\tGa'_1/\Ga'_1)+
\]
\[
+12g(e_1f_2^2+e_2f_1^2+2(e_1+e_2)f_1f_2-(f_1+f_2)f_1f_2)+24e_1e_2f_1f_2,
\]
while on the cone $f_1\geq e_1$, $f_2\geq e_2$ we exchange the $e$'s and the $f$'s. On the cone $e_1\geq f_1$, $f_2\geq e_2$ we set
\[
q(\tGa/\Ga)=p_2(e_1,f_1)w_0(\tGa'_2/\Ga'_2)+p_2(e_2,f_2)w_0(\tGa'_1/\Ga'_1)+p_3(e_1-f_1,f_2-e_2,g)+
\]
\[
+12g(-e_1e_2^2-f_1^2f_2+e_2^2f_1+e_2f_1^2+2e_1e_2f_2+2e_1f_1f_2)+24e_1e_2f_1f_2,
\]
and there are three domains of polynomiality, depending on which of the three quantities $e_1-f_1$, $f_2-e_2$, and $g$ is the smallest. Finally, on the cone $e_2\geq f_2$, $f_1\geq e_1$, the formula for $q(\tGa/\Ga)$ is obtained from the one above by exchanging the $e$'s and the $f$'s. 


\subsubsection*{Three $FS_3$-sets} The union of the $FS_2$-sets consists of three edges, therefore we denote the three sets by $\{e_1,e_2\}$, $\{e_1,e_3\}$, and $\{e_2,e_3\}$. The graph $\Ga$ has the following form:
\begin{center}
\begin{tikzpicture}
    \draw[thin] (-1,0) -- (1,0) -- (0,-1.7) -- (-1,0);
    \node[above] at (0,0) {$e_1$};
    \node at (0.7,-1) {$e_3$};
    \node at (-0.7,-1) {$e_2$};
    \draw[fill,white] (-1,0) circle(0.5);
    \draw[thin] (-1,0) circle(0.5);
    \node at (-1,0) {$\Ga_3$};
    \draw[fill,white] (1,0) circle(0.5);
    \draw[thin] (1,0) circle(0.5);
    \node at (1,0) {$\Ga_2$};
    \draw[fill,white] (0,-1.7) circle(0.5);
    \draw[thin] (0,-1.7) circle(0.5);
    \node at (0,-1.7) {$\Ga_1$};
\end{tikzpicture}
\end{center}
The three subgraphs $\Ga_1$, $\Ga_2$, and $\Ga_3$ are unbalanced. We denote by $\Ga'_1$, $\Ga'_2$, and $\Ga'_3$ the genus two subgraphs obtained by removing respectively $\{e_2,e_3\}$, $\{e_1,e_3\}$, and $\{e_1,e_2\}$ from $\Ga$, and $\tGa'_i\to \Ga'_i$ the associated double covers. Let 
\[
s_1=e_1+e_2+e_3,\quad s_2=e_1e_2+e_1e_3+e_2e_3,\quad s_3=e_1e_2e_3
\]
denote the elementary symmetric functions in the $e_i$, and we introduce the quantity
\[
S(e_1,e_2,e_3)=2s_1^4-16s_1^2s_2+32s_2^2+16s_1s_3.
\]
There are two possible choices of graphs for each $\Ga_i$, giving four (up to isomorphism) possible graphs $\Ga$, having 0, 1, 2, or 3 $FS_3$-sets. 




\subsubsection*{Three $FS_2$-sets, no $FS_3$-set} The graph $\Ga$ has the form
\begin{center}
\begin{tikzpicture}
    \draw[thin] (-1,0) -- (1,0) -- (0,-1.7) -- (-1,0);
    \node[above] at (0,0) {$e_1$};
    \node at (0.7,-1) {$e_3$};
    \node at (-0.7,-1) {$e_2$};
    \draw[fill] (-1,0) circle(0.07);
    \draw[fill] (1,0) circle(0.07);
    \draw[fill] (0,-1.7) circle(0.07);
    \draw[thin] (-1,0) -- (-2,0);
    \draw[thin] (1,0) -- (2,0);
    \draw[thin] (0,-1.7) -- (0,-2.7);
    \node[above] at (-1.5,0) {$f_3$};
    \node[above] at (1.5,0) {$f_2$};
    \node[right] at (0,-2.2) {$f_1$};
    \draw[fill] (-2,0) circle(0.07);
    \draw[fill] (2,0) circle(0.07);
    \draw[fill] (0,-2.7) circle(0.07);
    \draw[thin] (-2.3,0) circle(0.3);
    \draw[thin] (2.3,0) circle(0.3);
    \draw[thin] (0,-3) circle(0.3);
    \node[left] at (-2.6,0) {$g_3$};
    \node[right] at (2.6,0) {$g_2$};
    \node[right] at (0.3,-3) {$g_1$};
\end{tikzpicture}
\end{center}
The three loops $g_1,g_2,g_3$ are odd, while the remaining edges are even. There are four domains of polynomiality. On the cone $e_1\geq e_2+e_3$ we set 
\[
q(\tGa/\Ga)=p_2(e_2,e_1)w_0(\tGa'_3/\Ga'_3)+p_2(e_3,e_1)w_0(\tGa'_2/\Ga'_2)+
\]
\[
+12e_2e_3\left[(2e_1-e_2-e_3)(4f_1+g_1)+e_2(4f_2+g_2)+e_3(4f_3+g_3)\right].
\]
Cyclically permuting the indices, we obtain the formula for $q(\tGa/\Ga)$ on the cones $e_2\geq e_1+e_3$ and $e_3\geq e_1+e_2$. On the remaining central cone $e_1\leq e_2+e_3$, $e_2\leq e_1+e_3$, $e_3\leq e_1+e_2$ we set
\[
q(\tGa/\Ga)=S(e_1,e_2,e_3)+\sum_{i=1}^3p_2(e_i,s_1-e_i)(4f_i+g_i).
\]






\subsubsection*{Three $FS_2$-sets, one $FS_3$-set}  The graph $\Ga$ has the form
\begin{center}
    \begin{tikzpicture}
        \draw[thin] (0,0) -- (0,2) -- (2,2) -- (2,0);
        \draw[thin] (-1,2) -- (0,2);
        \draw[thin] (2,2) -- (3,2);
        \draw[thin] (-1.3,2) circle(0.3);
        \draw[thin] (3.3,2) circle(0.3);
        \draw[fill] (-1,2) circle(0.07);
        \draw[fill] (0,2) circle(0.07);
        \draw[fill] (2,2) circle(0.07);
        \draw[fill] (3,2) circle(0.07);
        \draw[fill] (0,0) circle(0.07);
        \draw[fill] (2,0) circle(0.07);
        \draw[thin] (0,0) .. controls (0.4,0.2) and (1.6,0.2) .. (2,0);
        \draw[thin] (0,0) .. controls (0.4,-0.2) and (1.6,-0.2) .. (2,0);
        \node[above] at (1,2) {$e_1$};
        \node[above] at (1,0.1) {$f_1$};
        \node[below] at (1,-0.1) {$g_1$};
        \node[left] at (0,1) {$e_2$};
        \node[right] at (2,1) {$e_3$};
        \node[above] at (-0.5,2) {$f_3$};
        \node[above] at (2.5,2) {$f_2$};
        \node[left] at (-1.6,2) {$g_3$};
        \node[right] at (3.6,2) {$g_2$};
    \end{tikzpicture}
\end{center}
The loops $g_2$ and $g_3$ and the cycle $f_1,g_1$ are odd, and the $FS_3$-set is $\{e_1,f_1,g_1\}$. There are six domains of polynomiality. On the cone $e_1\geq e_2+e_3$ we set
\[
q(\tGa/\Ga)=p_2(e_1,e_2)w_0(\tGa'_3/\Ga'_3)+p_2(e_3,e_1)w_0(\tGa'_2/\Ga'_2)+p_3(e_1-e_2-e_3,f_1,g_1)+
\]
\[
+12\left[
(2e_1-e_2-e_3)((e_2+e_3)f_1g_1+e_2e_3(f_1+g_1))+e_3^2e_2(4f_3+g_3)+e_3e_2^2(4f_2+g_2)
\right],
\]
and there are three domains of polynomiality, depending on which of the quantities $e_1-e_2-e_3$, $f_1$, and $g_1$ is the smallest. On the cone $e_2\geq e_1+e_3$ we set
\[
q(\tGa/\Ga)=p_2(e_1,e_2)w_0(\tGa'_2/\Ga'_2)+p_2(e_2,e_3)w_0(\tGa'_1/\Ga'_1)+
\]
\[
+12\left[e_1e_3(e_1(f_1+g_1)+(2e_2-e_1-e_3)(4f_2+g_2)-e_3(4f_3+g_3))+e_1^2f_1g_1\right].
\]
Exchanging 2 and 3, we obtain the formula for $q(\tGa/\Ga)$ on the cone $e_3\geq e_1+e_2$. Finally, on the central cone $e_1\leq e_2+e_3$, $e_2\leq e_1+e_3$, $e_3\leq e_1+e_2$ we set
\[
q(\tGa/\Ga)=S(e_1,e_2,e_3)+p_2(e_1,e_2+e_3)(f_1+g_1)+12e_1^2f_1g_1+\sum_{i=2}^3 p_2(e_i,s_1-e_i)(4f_i+g_i).
\]


\subsubsection*{Three $FS_2$-sets, two $FS_3$-sets} The graph $\Ga$ has the form
\begin{center}
    \begin{tikzpicture}
        \draw[thin] (0,0) -- (0,2);
        \draw[thin] (2,2) -- (3,1) -- (2,0);
        \draw[thin] (3,1) -- (4,1);
        \draw[thin] (0,0) .. controls (0.4,0.2) and (1.6,0.2) .. (2,0);
        \draw[thin] (0,0) .. controls (0.4,-0.2) and (1.6,-0.2) .. (2,0);
        \draw[thin] (0,2) .. controls (0.4,2.2) and (1.6,2.2) .. (2,2);
        \draw[thin] (0,2) .. controls (0.4,1.8) and (1.6,1.8) .. (2,2);
        \draw[fill] (0,0) circle(0.07);
        \draw[fill] (2,0) circle(0.07);
        \draw[fill] (0,2) circle(0.07);
        \draw[fill] (2,2) circle(0.07);
        \draw[fill] (3,1) circle(0.07);
