        \node[below] at (1,-0.1) {$g_1$};
        \node[right] at (2.4,0.4) {$e_2$};
        \node[above] at (1,2.1) {$f_2$};
        \node[below] at (1,1.9) {$g_2$};
        \node[left] at (0,1) {$e_3$};
        \node[above] at (3.5,1) {$f_3$};
        \node[right] at (4.6,1) {$g_3$};

    \end{tikzpicture}
\end{center}
The loop $g_3$ and the cycles $f_1,g_1$ and $f_2,g_2$ are odd, and the $FS_3$-sets are $\{e_1,f_1,g_1\}$ and $\{e_2,f_2,g_2\}$. There are eight domains of polynomiality. On the cone $e_1\geq e_2+e_3$ we set
\[
q(\tGa/\Ga)=p_2(e_1,e_2)w_0(\tGa'_3/\Ga'_3)+p_2(e_3,e_1)w_0(\tGa'_2/\Ga'_2)+p_3(e_1-e_2-e_3,f_1,g_1)+
\]
\[
+12\left[
(2e_1-e_2-e_3)((e_2+e_3)f_1g_1+e_2e_3(f_1+g_1))+e_3^2e_2(4f_3+g_3)+e_3e_2^2(f_2+g_2)+e_2^2f_2g_2
\right],
\]
with three domains of polynomiality determined by which of the quantities $e_1-e_2-e_3$, $f_1$, and $g_1$ is the smallest. On the cone $e_2\geq e_1+e_3$ we exchange 1 and 2. On the cone $e_3\geq e_1+e_2$ we set
\[
q(\tGa/\Ga)=p_2(e_1,e_3)w_0(\tGa'_3/\Ga'_3)+p_2(e_2,e_3)w_0(\tGa'_1/\Ga'_1)+
\]
\[
+12\left[e_1e_2(e_1(f_1+g_1)+e_2(f_2+g_2)+(2e_3-e_1-e_2)(4f_3+g_3))+e_1^2f_1g_1+e_2^2f_2g_2
\right].
\]
Finally, on the central cone $e_1\leq e_2+e_3$, $e_2\leq e_1+e_3$, $e_3\leq e_1+e_2$ we set
\[
q(\tGa/\Ga)=S(e_1,e_2,e_3)+\sum_{i=1}^2[p_2(e_i,s-e_i)(f_i+g_i)+12e_i^2f_ig_i]+p_2(e_3,e_1+e_2)(4f_3+g_3).
\]


\subsubsection*{Three $FS_2$-sets, three $FS_3$-sets} The graph $\Ga$ has the form
\begin{center}
    \begin{tikzpicture}
        \draw[thin] (0,0) -- (2,0);
        \draw[thin] (3,1.7) -- (2,3.4);
        \draw[thin] (0,3.4) -- (-1,1.7);
        \draw[thin] (0,3.4) .. controls (0.4,3.6) and (1.6,3.6) .. (2,3.4);
        \draw[thin] (0,3.4) .. controls (0.4,3.2) and (1.6,3.2) .. (2,3.4);
        \draw[thin] (2,0) .. controls (2,0.5) and (2.6,1.5) .. (3,1.7);
        \draw[thin] (2,0) .. controls (2.4,0.2) and (3,1.2) .. (3,1.7);
        \draw[thin] (0,0) .. controls (0,0.5) and (-0.6,1.5) .. (-1,1.7);
        \draw[thin] (0,0) .. controls (-0.4,0.2) and (-1,1.2) .. (-1,1.7);
        \draw[fill] (0,0) circle(0.07);
        \draw[fill] (2,0) circle(0.07);
        \draw[fill] (0,3.4) circle(0.07);
        \draw[fill] (2,3.4) circle(0.07);
        \draw[fill] (3,1.7) circle(0.07);
        \draw[fill] (-1,1.7) circle(0.07);
        \node[below] at (1,0) {$e_1$};
        \node[above] at (1,3.6) {$f_1$};
        \node[below] at (1,3.2) {$g_1$};
        \node[left] at (-0.4, 2.7) {$e_2$};
        \node[left] at (2.4, 1) {$f_2$};
        \node[right] at (2.6, 0.7) {$g_2$};
        \node[right] at (2.4, 2.7) {$e_3$};
        \node[left] at (-0.6, 0.7) {$f_3$};
        \node[right] at (-0.4, 1) {$g_3$};
    \end{tikzpicture}
\end{center}
The cycles $f_1,g_1$, $f_2,g_2$, and $f_3,g_3$ are odd, and the $FS_3$-sets are $\{e_1,f_1,g_1\}$, $\{e_2,f_2,g_2\}$, and $\{e_3,f_3,g_3\}$. There are ten domains of polynomiality. On the cone $e_3\geq e_1+e_2$ we set
\[
q(\tGa/\Ga)=p_2(e_1,e_3)w_0(\tGa'_2/\Ga'_2)+p_2(e_2,e_3)w_0(\tGa'_1/\Ga'_1)+p_3(e_3-e_1-e_2,f_3,g_3)+
\]
\[
+12\left[(f_3g_3(e_1+e_2)+(f_3+g_3)e_1e_2)(2e_3-e_1-e_2)
+e_1^2f_1g_1+e_2^2g_2f_2+e_1^2e_2(f_1+g_1)+e_1e_2^2(f_2+g_2)\right].
\]
There are three domains of polynomiality on this cone, corresponding to which of the quantities $e_3-e_1-e_2$, $f_3$, and $g_3$ is the smallest. The formula for $q(\tGa/\Ga)$ on the cones $e_1\geq e_2+e_3$ and $e_2\geq e_1+e_3$ is obtained by cyclically permuting the indices. Finally, on the central cone $e_1\leq e_2+e_3$, $e_2\leq e_1+e_3$, $e_3\leq e_1+e_2$ we set 
\[
q(\tGa/\Ga)=S(e_1,e_2,e_3)+\sum_{i=1}^3\left[p_2(e_i,s_1-e_i)(f_i+g_i)+12e_i^2f_ig_i\right].
\]





