\noindent \textbf{3.9 Generalized existence and root number theorem of a random transcendental equation.}

\vspace{6pt}
\noindent \textbf{3.9.1. Definition} Type of function means one of the 5 general forms of functions, which appear in mathematics namely: Exponential Function, Logarithmic Function, Trigonometric Function, Dynamic Function, Exponential Dynamic Function.

\vspace{6pt}
\noindent \textbf{3.9.2. Definitions of primary functions}
\\[6pt]
\noindent (i). A primary simple transcendental equation is any equation of the form: $\Psi(z) = q(z) + t = 0$, with $t \in \mathbb{C}$, which has its roots in $\mathbb{C}$.

\noindent (ii). A primary composite transcendental equation is any equation of the form: $\Psi_2(z) = q(z) + m \cdot p(z) + t = 0$, which has its roots in $\mathbb{C}$. Furthermore, the coefficients $m$, $t$ are different from $0$, and also take values from $\mathbb{C}$. In general, the functions $q(z)$, $p(z)$ are different types, with values in $\mathbb{C}$.
\\[6pt]
\textbf{Theorem 9. }\label{theo:random}
%\begin{theorem}\label{theo:random}
  \textit{Every random transcendental equation of the form:}
\[
p_{\lambda}(z) = \frac{1}{m_{\lambda}} \sum_{\substack{k=1 \\ k \ne \lambda}}^{n} m_k \cdot p_k(z) + \frac{t}{m_{\lambda}} = 0, \quad k=1,2,\ldots,n, \quad \lambda \ne k 
